INSERT INTO stronghold_terrain_type (id, sort, label, label_ko) VALUES ('ridge', 0, 'Ridge type', '산성형');
INSERT INTO stronghold_terrain_type (id, sort, label, label_ko) VALUES ('river', 1, 'Riverside type', '수변형');
INSERT INTO stronghold_terrain_type (id, sort, label, label_ko) VALUES ('rail', 2, 'Rail embankment type', '철도성토형');
INSERT INTO stronghold_terrain_type (id, sort, label, label_ko) VALUES ('tower', 3, 'High-rise block type', '고층블록형');
INSERT INTO stronghold_terrain_type (id, sort, label, label_ko) VALUES ('estate', 4, 'Apartment estate type', '단지형');
INSERT INTO stronghold_terrain_type (id, sort, label, label_ko) VALUES ('warren', 5, 'Alley warren type', '골목형');
INSERT INTO stronghold_terrain_type (id, sort, label, label_ko) VALUES ('plain', 6, 'Flat ground type', '평지형');
INSERT INTO stronghold_terrain_text (terrain_id, stage, text, text_ko) VALUES ('ridge', 3, 'Air intakes placed upslope (upwind) and exhaust sent down into the valley', '급기구를 비탈 위쪽(공기 상류)에 두고 배기는 골짜기 아래로');
INSERT INTO stronghold_terrain_text (terrain_id, stage, text, text_ko) VALUES ('ridge', 4, 'The line runs along the ridge and slopes. The tallest building or rocky knoll is the watchtower, the slope itself is the cleared strip, and grilles close the sewer outlets on the valley side', '능선과 비탈을 따라 두른다. 가장 높은 건물·바위 언덕이 망루, 비탈 자체가 비워 둔 띠, 골짜기 쪽 하수 수구에 창살');
INSERT INTO stronghold_terrain_text (terrain_id, stage, text, text_ko) VALUES ('ridge', 5, 'Signal points on the ridge keep a line of sight to the neighbouring stations', '능선 위 신호 자리로 이웃 역과 보이는 줄을 잇는다');
INSERT INTO stronghold_terrain_text (terrain_id, stage, text, text_ko) VALUES ('river', 3, 'Sumps and drainage pumps in the last-stand zone, grilles at the ends of the drains on the river side', '집수정과 배수펌프를 최후 구역에, 하천 쪽 배수 관로 끝에 창살');
INSERT INTO stronghold_terrain_text (terrain_id, stage, text, text_ko) VALUES ('river', 4, 'The river is the moat on one side. The embankment is the wall, bridges and sewer outlets are the gates. A frozen river becomes a road in winter, so there is an ice watch post', '하천 한쪽이 해자다. 둑이 성벽, 다리와 하수 출구가 문. 겨울에 언 하천은 길이 되므로 얼음 감시 초소');
INSERT INTO stronghold_terrain_text (terrain_id, stage, text, text_ko) VALUES ('river', 5, 'One bridge is blocked and one is held as the crossing', '다리 하나를 막고 하나는 지켜 건너는 길로 쓴다');
INSERT INTO stronghold_terrain_text (terrain_id, stage, text, text_ko) VALUES ('rail', 3, 'Underpasses and passages below the tracks hardened into inner gates', '철길 아래 지하차도와 통로를 안쪽 문으로 굳힌다');
INSERT INTO stronghold_terrain_text (terrain_id, stage, text, text_ko) VALUES ('rail', 4, 'The railway embankments and cuttings are ready-made ramparts. Barriers stand on top, the underpasses and spaces below the rail bridges are the gates, and the top of the embankment is the line of watchtowers', '철도 성토·절토가 이미 둑이다. 둑 위에 방벽, 지하차도와 철교 아래가 문, 성토 위가 망루 줄');
INSERT INTO stronghold_terrain_text (terrain_id, stage, text, text_ko) VALUES ('rail', 5, 'Surface tracks become haul roads (push carts); rail bridges are gates that can be cut or joined', '지상 선로를 짐 나르는 길로(밀차), 철교는 끊고 잇는 문');
INSERT INTO stronghold_terrain_text (terrain_id, stage, text, text_ko) VALUES ('tower', 3, 'Basements of adjoining high-rise buildings used as precinct storerooms', '붙은 고층 건물의 지하층을 구내 창고로');
INSERT INTO stronghold_terrain_text (terrain_id, stage, text, text_ko) VALUES ('tower', 4, 'The outer walls of the high-rise buildings form the wall. Ground and first-floor windows are blocked, the rooftops are watchtowers, and only the gaps between buildings get barriers', '고층 건물의 외벽 줄이 성벽, 1~2층 창을 막고 고층 꼭대기가 망루, 건물 사이 틈만 방벽');
INSERT INTO stronghold_terrain_text (terrain_id, stage, text, text_ko) VALUES ('tower', 5, 'High-rise buildings are linked through underground car parks and connecting passages, so people move between them without going outside', '고층 건물끼리 지하 주차장·연결 통로로 이어 지상에 나가지 않고 오간다');
INSERT INTO stronghold_terrain_text (terrain_id, stage, text, text_ko) VALUES ('estate', 3, 'A passage is cut from the estate''s underground car park to the station precinct', '단지 지하 주차장을 구내와 잇는 통로를 낸다');
INSERT INTO stronghold_terrain_text (terrain_id, stage, text, text_ko) VALUES ('estate', 4, 'The apartment estate wall is the inner wall and the estate main gate is the gate. Yards between the blocks become vegetable plots and a firewood yard', '아파트 단지 담장이 안뜰 성벽, 단지 정문이 성문, 동 사이 마당이 텃밭과 땔감 마당');
INSERT INTO stronghold_terrain_text (terrain_id, stage, text, text_ko) VALUES ('estate', 5, 'Neighbouring estates are taken in one by one, joining several estate strongholds', '이웃 단지를 차례로 편입해 단지 성채 여럿을 잇는다');
INSERT INTO stronghold_terrain_text (terrain_id, stage, text, text_ko) VALUES ('warren', 3, 'Basements of low-rise buildings above the entrances used as hidden storerooms', '출입구 위 저층 건물의 지하실을 숨긴 창고로');
INSERT INTO stronghold_terrain_text (terrain_id, stage, text, text_ko) VALUES ('warren', 4, 'Only a few alley mouths stay open and the rest are blocked into a maze of dead ends; building walls are broken through to make inner passages', '골목 입구 몇 곳만 열고 나머지는 막아 막다른 미로로, 건물 벽을 뚫어 안쪽 통로를 낸다');
INSERT INTO stronghold_terrain_text (terrain_id, stage, text, text_ko) VALUES ('warren', 5, 'Passages through buildings are joined toward the neighbouring station, giving a route that never goes outside', '건물 안 통로를 이어 이웃 역 방향으로 지상에 나가지 않는 길을 낸다');
INSERT INTO stronghold_terrain_text (terrain_id, stage, text, text_ko) VALUES ('plain', 3, 'For a shallow station, pairing with a deep neighbour comes first', '얕은 역이면 깊은 이웃 역과 짝을 맺는 것이 먼저');
INSERT INTO stronghold_terrain_text (terrain_id, stage, text, text_ko) VALUES ('plain', 4, 'With no terrain to lean on, banks are raised and ditches dug. Wide roads are kept as the cleared strip (field of fire), with watchtowers at the corners', '기댈 지형이 없어 둑을 쌓고 해자를 판다. 넓은 길은 비워 둔 띠(사격 띠)로, 모서리에 망루');
INSERT INTO stronghold_terrain_text (terrain_id, stage, text, text_ko) VALUES ('plain', 5, 'A shallow station cannot stand alone. It exists only as a pair with a deep neighbour', '얕은 역은 혼자 서지 못한다. 깊은 이웃 역과의 짝으로만 성립');
INSERT INTO stronghold_stage_text (stage, variant, name, name_ko, works, works_ko, facilities, facilities_ko, labor, labor_ko, duration, duration_ko, entry, entry_ko) VALUES (1, 'common', 'Entrance Post', '출입구 초소', 'Lower the shutters and block the unused entrances with sandbags. One entrance stays in use, with a guard post and a gate', '셔터를 내리고 쓰지 않는 출입구를 모래주머니로 막는다. 쓰는 출입구 하나에 초소와 문', 'Water drums, a first-aid corner, one shared kitchen', '물통, 응급 구석, 공동 취사 하나', '10-20 person-days to block one entrance, 10 for a guard post', '출입구 하나 막기 10~20, 초소 10 인일', 'A few hours to 3 days', '몇 시간~3일', 'At least 10 people come in and there is a threat', '사람 10명 이상이 들어오고 위협이 있음');
INSERT INTO stronghold_stage_text (stage, variant, name, name_ko, works, works_ko, facilities, facilities_ko, labor, labor_ko, duration, duration_ko, entry, entry_ko) VALUES (2, 'common', 'Concourse Stronghold', '대합실 거점', 'Bulkheads and gates in the tunnels at both ends of the platform, the ticket-gate line hardened into an inner checkpoint, temporary materials replaced with brick and concrete', '승강장 양 끝 터널에 방벽과 문, 개찰구 선을 안쪽 검문선으로 굳힘, 임시 재료를 벽돌·콘크리트로 바꿈', 'Storerooms (shallow levels), water tanks, toilets, a care corner (treatment by doctors in Free City stations; first aid only in Government and Arc stations), a register desk, a tool corner', '창고(얕은 층), 저수조, 화장실, 진료 자리(자유도시 역은 의사의 진료, 정부·아크 역은 응급 처치만), 명부 자리, 공구 자리', '1,000-3,000 person-days in total', '전체 1,000~3,000 인일', '2 weeks to 3 months', '2주~3달', '14 days survived, a water source secured, population of 40 or more', '14일 생존, 물원 확보, 인구 40명 이상');
INSERT INTO stronghold_stage_text (stage, variant, name, name_ko, works, works_ko, facilities, facilities_ko, labor, labor_ko, duration, duration_ko, entry, entry_ko) VALUES (3, 'common', 'Station Precinct Defence', '역 구내 방어', 'Entrances sorted into used, hidden and sealed doors, an airlock (double door) at every door in use, covers and grilles on the vents, outposts 100-300 m inside the tunnels, fire compartments for the living sections', '출입구를 쓰는·숨긴·막은 문으로 정리, 쓰는 문마다 전실(이중문), 환기구 덮개와 창살, 터널 안 100~300 m 전초, 사는 칸 방화 구획', 'Clinic and isolation room (Free City: a clinic with an operating room; Government and Arc: a first-aid post and isolation room, no doctors), school, ration point, workshops, mushroom growing rooms, laundry, mortuary (shallow levels)', '진료소와 격리실(자유도시: 진료소·수술실. 정부·아크: 응급 처치소와 격리실, 의사 없음), 학교, 배급소, 작업장, 버섯 재배실, 세탁, 안치소(얕은 층)', '3,000-8,000 person-days in total', '전체 3,000~8,000 인일', '6 months to 3 years', '6달~3년', 'Occupancy of 75% or more or one attack withstood, reserves for 60 days or more, at least 10% spare labour', '점유율 75% 이상 또는 공격 한 번을 버팀, 비축 60일 이상, 남는 일손 10% 이상');
INSERT INTO stronghold_stage_text (stage, variant, name, name_ko, works, works_ko, facilities, facilities_ko, labor, labor_ko, duration, duration_ko, entry, entry_ko) VALUES (4, 'arc', 'Deep-Level Seal', '깊은 층 봉쇄', 'Deep-level seal: surface entrances blocked and camouflaged, digging down below the deep tunnels and machine rooms, no light or heat let out at the surface', '깊은 층 봉쇄: 지상 출입구를 막고 위장, 대심도 터널·기계실 아래로 파 내려감, 빛과 열을 지상에 내지 않음', 'Surface storehouses and cold storage, summer greenhouses, a firewood yard, surface workshops (unheated)', '지상 창고와 냉장, 여름 온실, 땔감 마당, 지상 작업장(데우지 않음)', '2-10 person-days per metre of raised barrier, 20-50 per watchtower', '세운 방벽 1 m당 2~10, 망루 하나 20~50 인일', '3 to 10 years', '3~10년', 'Population above the stage 3 capacity so that people outside the register live outside, or a change in the surface threat; reserves for 120 days or more; emergency watch no larger than the mobilisable force', '인구가 3단계 정원을 넘어 명부 밖 사람이 바깥에 삶 또는 지상 위협 변화, 비축 120일 이상, 비상 경계 ≤ 동원 가능');
INSERT INTO stronghold_stage_text (stage, variant, name, name_ko, works, works_ko, facilities, facilities_ko, labor, labor_ko, duration, duration_ko, entry, entry_ko) VALUES (4, 'common', 'Surface Perimeter Line', '지상 외곽 방어선', 'A surface defence line around the entrances that joins measured city blocks, an outer buffer (a cleared strip 30-100 m wide), watchtowers and checkpoints, basements of adjoining buildings taken in', '출입구 둘레 지상에 실측 블록을 이은 방어선, 바깥 완충 지대(비워 둔 띠 30~100 m), 망루와 검문소, 붙은 건물 지하 편입', 'Surface storehouses and cold storage, summer greenhouses, a firewood yard, surface workshops (unheated)', '지상 창고와 냉장, 여름 온실, 땔감 마당, 지상 작업장(데우지 않음)', '2-10 person-days per metre of raised barrier, 20-50 per watchtower', '세운 방벽 1 m당 2~10, 망루 하나 20~50 인일', '3 to 10 years', '3~10년', 'Population above the stage 3 capacity so that people outside the register live outside, or a change in the surface threat; reserves for 120 days or more; emergency watch no larger than the mobilisable force', '인구가 3단계 정원을 넘어 명부 밖 사람이 바깥에 삶 또는 지상 위협 변화, 비축 120일 이상, 비상 경계 ≤ 동원 가능');
INSERT INTO stronghold_stage_text (stage, variant, name, name_ko, works, works_ko, facilities, facilities_ko, labor, labor_ko, duration, duration_ko, entry, entry_ko) VALUES (5, 'arc', 'Inter-Station Defence Network', '역간 방어 체계', 'Passages that join the deep lines into one mass, few and narrow passages to the outside, a shared reserve in the last-stand zone (data centre, sanctuary)', '깊은 노선끼리 한 덩어리로 잇는 통로, 바깥과 잇는 통로는 적고 좁게, 최후 구역(데이터센터·성소) 공동 비축', 'District storehouse, communications, a data centre server room, a computer maintenance room. No hospital (treatment is contracted from the Free City)', '권역 창고, 통신, 데이터센터 서버실, 전산 정비실. 병원 없음(치료는 자유도시와 계약)', '200-500 person-days to make 100 m of tunnel habitable, 30 per midway post', '터널 100 m 거처화 200~500, 중간 초소 하나 30 인일', '10 to 30 years', '10~30년', 'At least one neighbouring station at stage 3 or higher, a shared threat or market and passage gains, a political agreement', '이웃 역 하나 이상이 3단계 이상, 공동 위협이나 장·통행 이익, 정치 합의');
INSERT INTO stronghold_stage_text (stage, variant, name, name_ko, works, works_ko, facilities, facilities_ko, labor, labor_ko, duration, duration_ko, entry, entry_ko) VALUES (5, 'common', 'Inter-Station Defence Network', '역간 방어 체계', 'Tunnels to the neighbouring stations turned into safe passages (midway posts, lighting, signal lines), tunnel sections used as housing and growing rooms, one deep station designated as the shelter, a responsible group for every section', '이웃 역까지 터널을 안전 통로로(중간 초소·조명·신호선), 터널 구간을 거처·재배실로, 깊은 역 하나를 대피소로 지정, 구간별 책임', 'District storehouse, market (large interchanges), communications, maintenance base, hospital (Free City: doctors, a clinic and an operating room; Government: a university hospital building it owns, first aid and isolation only, no doctors)', '권역 창고, 장(큰 환승역), 통신, 정비 기지, 병원(자유도시: 의사가 있는 진료소·수술실. 정부: 정부 소유 대학병원 건물, 응급 처치·격리만, 의사 없음)', '200-500 person-days to make 100 m of tunnel habitable, 30 per midway post', '터널 100 m 거처화 200~500, 중간 초소 하나 30 인일', '10 to 30 years', '10~30년', 'At least one neighbouring station at stage 3 or higher, a shared threat or market and passage gains, a political agreement', '이웃 역 하나 이상이 3단계 이상, 공동 위협이나 장·통행 이익, 정치 합의');
