INSERT INTO stronghold_stage (stronghold_id, stage, variant, terrain_works, terrain_works_ko, floor_m2, capacity, cap_by_max, living_capacity, cap_by, over_living, over_max, air_speed, overcrowd_limit, guard_standing, guard_emergency, mobilisable, defensible, food_t, water_m3, fuel_t, surface_line_m, surface_line_real_m, watchtowers) VALUES ('4-19-democratic-cemetery', 2, 'common', '', '', 1373, 490, 'water', 392, 'space', 1, 0, 1.0, 713, 24, 22, 98, 1, 17.6, 26, 64.7, 0, 0, 0);
INSERT INTO stronghold_stage (stronghold_id, stage, variant, terrain_works, terrain_works_ko, floor_m2, capacity, cap_by_max, living_capacity, cap_by, over_living, over_max, air_speed, overcrowd_limit, guard_standing, guard_emergency, mobilisable, defensible, food_t, water_m3, fuel_t, surface_line_m, surface_line_real_m, watchtowers) VALUES ('4-19-democratic-cemetery', 3, 'common', 'Basements of low-rise buildings above the entrances used as hidden storerooms; Sumps and drainage pumps in the last-stand zone, grilles at the ends of the drains on the river side', '출입구 위 저층 건물의 지하실을 숨긴 창고로; 집수정과 배수펌프를 최후 구역에, 하천 쪽 배수 관로 끝에 창살', 2122, 490, 'water', 245, 'water', 1, 0, 2.0, 713, 46, 22, 98, 1, 35.3, 103, 129.4, 0, 0, 0);
INSERT INTO stronghold_stage (stronghold_id, stage, variant, terrain_works, terrain_works_ko, floor_m2, capacity, cap_by_max, living_capacity, cap_by, over_living, over_max, air_speed, overcrowd_limit, guard_standing, guard_emergency, mobilisable, defensible, food_t, water_m3, fuel_t, surface_line_m, surface_line_real_m, watchtowers) VALUES ('4-19-democratic-cemetery', 4, 'common', 'Only a few alley mouths stay open and the rest are blocked into a maze of dead ends; building walls are broken through to make inner passages; The river is the moat on one side. The embankment is the wall, bridges and sewer outlets are the gates. A frozen river becomes a road in winter, so there is an ice watch post', '골목 입구 몇 곳만 열고 나머지는 막아 막다른 미로로, 건물 벽을 뚫어 안쪽 통로를 낸다; 하천 한쪽이 해자다. 둑이 성벽, 다리와 하수 출구가 문. 겨울에 언 하천은 길이 되므로 얼음 감시 초소', 2290, 761, 'space', 286, 'space', 1, 0, 2.5, 761, 51, 40, 98, 1, 52.9, 294, 194.0, 89, 154, 1);
INSERT INTO stronghold_stage (stronghold_id, stage, variant, terrain_works, terrain_works_ko, floor_m2, capacity, cap_by_max, living_capacity, cap_by, over_living, over_max, air_speed, overcrowd_limit, guard_standing, guard_emergency, mobilisable, defensible, food_t, water_m3, fuel_t, surface_line_m, surface_line_real_m, watchtowers) VALUES ('4-19-democratic-cemetery', 5, 'common', 'Passages through buildings are joined toward the neighbouring station, giving a route that never goes outside; One bridge is blocked and one is held as the crossing', '건물 안 통로를 이어 이웃 역 방향으로 지상에 나가지 않는 길을 낸다; 다리 하나를 막고 하나는 지켜 건너는 길로 쓴다', 7690, 839, 'water', 251, 'water', 1, 0, 3.0, 2303, 51, 40, 98, 1, 107.3, 735, 393.5, 89, 154, 1);
