INSERT INTO stronghold_stage (stronghold_id, stage, variant, terrain_works, terrain_works_ko, floor_m2, capacity, cap_by_max, living_capacity, cap_by, over_living, over_max, air_speed, overcrowd_limit, guard_standing, guard_emergency, mobilisable, defensible, food_t, water_m3, fuel_t, surface_line_m, surface_line_real_m, watchtowers) VALUES ('garak-market', 2, 'common', '', '', 12922, 6712, 'space', 3692, 'space', 0, 0, 1.0, 6712, 34, 80, 846, 1, 101.5, 148, 203.0, 0, 0, 0);
INSERT INTO stronghold_stage (stronghold_id, stage, variant, terrain_works, terrain_works_ko, floor_m2, capacity, cap_by_max, living_capacity, cap_by, over_living, over_max, air_speed, overcrowd_limit, guard_standing, guard_emergency, mobilisable, defensible, food_t, water_m3, fuel_t, surface_line_m, surface_line_real_m, watchtowers) VALUES ('garak-market', 3, 'common', 'Basements of adjoining high-rise buildings used as precinct storerooms; A passage is cut from the estate''s underground car park to the station precinct', '붙은 고층 건물의 지하층을 구내 창고로; 단지 지하 주차장을 구내와 잇는 통로를 낸다', 19971, 6712, 'space', 3631, 'space', 0, 0, 2.0, 6712, 82, 84, 846, 1, 203.0, 592, 406.1, 0, 0, 0);
INSERT INTO stronghold_stage (stronghold_id, stage, variant, terrain_works, terrain_works_ko, floor_m2, capacity, cap_by_max, living_capacity, cap_by, over_living, over_max, air_speed, overcrowd_limit, guard_standing, guard_emergency, mobilisable, defensible, food_t, water_m3, fuel_t, surface_line_m, surface_line_real_m, watchtowers) VALUES ('garak-market', 4, 'arc', 'The outer walls of the high-rise buildings form the wall. Ground and first-floor windows are blocked, the rooftops are watchtowers, and only the gaps between buildings get barriers; The apartment estate wall is the inner wall and the estate main gate is the gate. Yards between the blocks become vegetable plots and a firewood yard', '고층 건물의 외벽 줄이 성벽, 1~2층 창을 막고 고층 꼭대기가 망루, 건물 사이 틈만 방벽; 아파트 단지 담장이 안뜰 성벽, 단지 정문이 성문, 동 사이 마당이 텃밭과 땔감 마당', 19971, 6712, 'space', 2496, 'space', 1, 0, 2.5, 6712, 82, 84, 846, 1, 304.6, 1692, 609.1, 0, 0, 0);
INSERT INTO stronghold_stage (stronghold_id, stage, variant, terrain_works, terrain_works_ko, floor_m2, capacity, cap_by_max, living_capacity, cap_by, over_living, over_max, air_speed, overcrowd_limit, guard_standing, guard_emergency, mobilisable, defensible, food_t, water_m3, fuel_t, surface_line_m, surface_line_real_m, watchtowers) VALUES ('garak-market', 5, 'arc', 'High-rise buildings are linked through underground car parks and connecting passages, so people move between them without going outside; Neighbouring estates are taken in one by one, joining several estate strongholds', '고층 건물끼리 지하 주차장·연결 통로로 이어 지상에 나가지 않고 오간다; 이웃 단지를 차례로 편입해 단지 성채 여럿을 잇는다', 30771, 9400, 'water', 2820, 'water', 0, 0, 3.0, 9798, 82, 84, 846, 1, 617.6, 4230, 1235.2, 0, 0, 0);
