INSERT INTO stronghold_stage (stronghold_id, stage, variant, terrain_works, terrain_works_ko, floor_m2, capacity, cap_by_max, living_capacity, cap_by, over_living, over_max, air_speed, overcrowd_limit, guard_standing, guard_emergency, mobilisable, defensible, food_t, water_m3, fuel_t, surface_line_m, surface_line_real_m, watchtowers) VALUES ('gasan-digital-complex', 3, 'common', 'Basements of adjoining high-rise buildings used as precinct storerooms; Underpasses and passages below the tracks hardened into inner gates', '붙은 고층 건물의 지하층을 구내 창고로; 철길 아래 지하차도와 통로를 안쪽 문으로 굳힌다', 23306, 7834, 'space', 4237, 'space', 0, 0, 2.0, 7834, 70, 88, 702, 1, 187.2, 546, 374.4, 0, 0, 0);
INSERT INTO stronghold_stage (stronghold_id, stage, variant, terrain_works, terrain_works_ko, floor_m2, capacity, cap_by_max, living_capacity, cap_by, over_living, over_max, air_speed, overcrowd_limit, guard_standing, guard_emergency, mobilisable, defensible, food_t, water_m3, fuel_t, surface_line_m, surface_line_real_m, watchtowers) VALUES ('gasan-digital-complex', 4, 'common', 'The outer walls of the high-rise buildings form the wall. Ground and first-floor windows are blocked, the rooftops are watchtowers, and only the gaps between buildings get barriers; The railway embankments and cuttings are ready-made ramparts. Barriers stand on top, the underpasses and spaces below the rail bridges are the gates, and the top of the embankment is the line of watchtowers', '고층 건물의 외벽 줄이 성벽, 1~2층 창을 막고 고층 꼭대기가 망루, 건물 사이 틈만 방벽; 철도 성토·절토가 이미 둑이다. 둑 위에 방벽, 지하차도와 철교 아래가 문, 성토 위가 망루 줄', 34076, 10240, 'water', 3840, 'water', 0, 0, 2.5, 10910, 78, 169, 702, 1, 280.8, 1560, 561.6, 271, 329, 2);
INSERT INTO stronghold_stage (stronghold_id, stage, variant, terrain_works, terrain_works_ko, floor_m2, capacity, cap_by_max, living_capacity, cap_by, over_living, over_max, air_speed, overcrowd_limit, guard_standing, guard_emergency, mobilisable, defensible, food_t, water_m3, fuel_t, surface_line_m, surface_line_real_m, watchtowers) VALUES ('gasan-digital-complex', 5, 'common', 'High-rise buildings are linked through underground car parks and connecting passages, so people move between them without going outside; Surface tracks become haul roads (push carts); rail bridges are gates that can be cut or joined', '고층 건물끼리 지하 주차장·연결 통로로 이어 지상에 나가지 않고 오간다; 지상 선로를 짐 나르는 길로(밀차), 철교는 끊고 잇는 문', 42176, 10240, 'water', 3072, 'water', 0, 0, 3.0, 13225, 78, 169, 702, 1, 569.4, 3900, 1138.8, 271, 329, 2);
