INSERT INTO stronghold_stage (stronghold_id, stage, variant, terrain_works, terrain_works_ko, floor_m2, capacity, cap_by_max, living_capacity, cap_by, over_living, over_max, air_speed, overcrowd_limit, guard_standing, guard_emergency, mobilisable, defensible, food_t, water_m3, fuel_t, surface_line_m, surface_line_real_m, watchtowers) VALUES ('gaori', 3, 'common', 'Basements of low-rise buildings above the entrances used as hidden storerooms; A passage is cut from the estate''s underground car park to the station precinct', '출입구 위 저층 건물의 지하실을 숨긴 창고로; 단지 지하 주차장을 구내와 잇는 통로를 낸다', 2339, 590, 'water', 295, 'water', 1, 0, 2.0, 786, 46, 24, 118, 1, 42.5, 124, 155.8, 0, 0, 0);
INSERT INTO stronghold_stage (stronghold_id, stage, variant, terrain_works, terrain_works_ko, floor_m2, capacity, cap_by_max, living_capacity, cap_by, over_living, over_max, air_speed, overcrowd_limit, guard_standing, guard_emergency, mobilisable, defensible, food_t, water_m3, fuel_t, surface_line_m, surface_line_real_m, watchtowers) VALUES ('gaori', 4, 'common', 'Only a few alley mouths stay open and the rest are blocked into a maze of dead ends; building walls are broken through to make inner passages; The apartment estate wall is the inner wall and the estate main gate is the gate. Yards between the blocks become vegetable plots and a firewood yard', '골목 입구 몇 곳만 열고 나머지는 막아 막다른 미로로, 건물 벽을 뚫어 안쪽 통로를 낸다; 아파트 단지 담장이 안뜰 성벽, 단지 정문이 성문, 동 사이 마당이 텃밭과 땔감 마당', 4454, 1390, 'space', 556, 'space', 1, 0, 2.5, 1390, 56, 92, 118, 1, 63.7, 354, 233.6, 342, 500, 2);
INSERT INTO stronghold_stage (stronghold_id, stage, variant, terrain_works, terrain_works_ko, floor_m2, capacity, cap_by_max, living_capacity, cap_by, over_living, over_max, air_speed, overcrowd_limit, guard_standing, guard_emergency, mobilisable, defensible, food_t, water_m3, fuel_t, surface_line_m, surface_line_real_m, watchtowers) VALUES ('gaori', 5, 'common', 'Passages through buildings are joined toward the neighbouring station, giving a route that never goes outside; Neighbouring estates are taken in one by one, joining several estate strongholds', '건물 안 통로를 이어 이웃 역 방향으로 지상에 나가지 않는 길을 낸다; 이웃 단지를 차례로 편입해 단지 성채 여럿을 잇는다', 9854, 2054, 'water', 616, 'water', 0, 0, 3.0, 2933, 56, 92, 118, 1, 129.2, 885, 473.8, 342, 500, 2);
INSERT INTO stronghold_stage (stronghold_id, stage, variant, terrain_works, terrain_works_ko, floor_m2, capacity, cap_by_max, living_capacity, cap_by, over_living, over_max, air_speed, overcrowd_limit, guard_standing, guard_emergency, mobilisable, defensible, food_t, water_m3, fuel_t, surface_line_m, surface_line_real_m, watchtowers) VALUES ('gajwa', 1, 'common', '', '', 2562, 2020, 'water', 1708, 'space', 0, 0, 1.0, 2562, 9, 24, 202, 1, 8.5, 15, 22.6, 0, 0, 0);
INSERT INTO stronghold_stage (stronghold_id, stage, variant, terrain_works, terrain_works_ko, floor_m2, capacity, cap_by_max, living_capacity, cap_by, over_living, over_max, air_speed, overcrowd_limit, guard_standing, guard_emergency, mobilisable, defensible, food_t, water_m3, fuel_t, surface_line_m, surface_line_real_m, watchtowers) VALUES ('gajwa', 2, 'common', '', '', 5636, 2020, 'water', 1610, 'space', 0, 0, 1.0, 2928, 33, 40, 202, 1, 36.4, 53, 97.0, 0, 0, 0);
INSERT INTO stronghold_stage (stronghold_id, stage, variant, terrain_works, terrain_works_ko, floor_m2, capacity, cap_by_max, living_capacity, cap_by, over_living, over_max, air_speed, overcrowd_limit, guard_standing, guard_emergency, mobilisable, defensible, food_t, water_m3, fuel_t, surface_line_m, surface_line_real_m, watchtowers) VALUES ('gajwa', 3, 'common', 'A passage is cut from the estate''s underground car park to the station precinct; Sumps and drainage pumps in the last-stand zone, grilles at the ends of the drains on the river side', '단지 지하 주차장을 구내와 잇는 통로를 낸다; 집수정과 배수펌프를 최후 구역에, 하천 쪽 배수 관로 끝에 창살', 8711, 2020, 'water', 1010, 'water', 0, 0, 2.0, 2928, 60, 44, 202, 1, 72.7, 212, 193.9, 0, 0, 0);
INSERT INTO stronghold_stage (stronghold_id, stage, variant, terrain_works, terrain_works_ko, floor_m2, capacity, cap_by_max, living_capacity, cap_by, over_living, over_max, air_speed, overcrowd_limit, guard_standing, guard_emergency, mobilisable, defensible, food_t, water_m3, fuel_t, surface_line_m, surface_line_real_m, watchtowers) VALUES ('gajwa', 4, 'common', 'The apartment estate wall is the inner wall and the estate main gate is the gate. Yards between the blocks become vegetable plots and a firewood yard; The river is the moat on one side. The embankment is the wall, bridges and sewer outlets are the gates. A frozen river becomes a road in winter, so there is an ice watch post', '아파트 단지 담장이 안뜰 성벽, 단지 정문이 성문, 동 사이 마당이 텃밭과 땔감 마당; 하천 한쪽이 해자다. 둑이 성벽, 다리와 하수 출구가 문. 겨울에 언 하천은 길이 되므로 얼음 감시 초소', 8711, 2020, 'water', 757, 'water', 1, 0, 2.5, 2928, 64, 83, 202, 1, 109.1, 606, 290.9, 192, 267, 1);
INSERT INTO stronghold_stage (stronghold_id, stage, variant, terrain_works, terrain_works_ko, floor_m2, capacity, cap_by_max, living_capacity, cap_by, over_living, over_max, air_speed, overcrowd_limit, guard_standing, guard_emergency, mobilisable, defensible, food_t, water_m3, fuel_t, surface_line_m, surface_line_real_m, watchtowers) VALUES ('gajwa', 5, 'common', 'Neighbouring estates are taken in one by one, joining several estate strongholds; One bridge is blocked and one is held as the crossing', '이웃 단지를 차례로 편입해 단지 성채 여럿을 잇는다; 다리 하나를 막고 하나는 지켜 건너는 길로 쓴다', 14111, 2020, 'water', 606, 'water', 1, 0, 3.0, 4470, 64, 83, 202, 1, 221.2, 1515, 589.8, 192, 267, 1);
