INSERT INTO stronghold_stage (stronghold_id, stage, variant, terrain_works, terrain_works_ko, floor_m2, capacity, cap_by_max, living_capacity, cap_by, over_living, over_max, air_speed, overcrowd_limit, guard_standing, guard_emergency, mobilisable, defensible, food_t, water_m3, fuel_t, surface_line_m, surface_line_real_m, watchtowers) VALUES ('gangdong-gu-office', 5, 'arc', 'Neighbouring estates are taken in one by one, joining several estate strongholds; Passages through buildings are joined toward the neighbouring station, giving a route that never goes outside', '이웃 단지를 차례로 편입해 단지 성채 여럿을 잇는다; 건물 안 통로를 이어 이웃 역 방향으로 지상에 나가지 않는 길을 낸다', 14625, 1833, 'water', 550, 'water', 0, 0, 3.0, 4643, 46, 27, 165, 1, 120.5, 825, 240.9, 0, 0, 0);
INSERT INTO stronghold_stage (stronghold_id, stage, variant, terrain_works, terrain_works_ko, floor_m2, capacity, cap_by_max, living_capacity, cap_by, over_living, over_max, air_speed, overcrowd_limit, guard_standing, guard_emergency, mobilisable, defensible, food_t, water_m3, fuel_t, surface_line_m, surface_line_real_m, watchtowers) VALUES ('gangbyeon', 1, 'common', '', '', 3782, 4322, 'space', 2521, 'space', 0, 0, 1.0, 3782, 9, 8, 38, 1, 1.6, 3, 8.0, 0, 0, 0);
INSERT INTO stronghold_stage (stronghold_id, stage, variant, terrain_works, terrain_works_ko, floor_m2, capacity, cap_by_max, living_capacity, cap_by, over_living, over_max, air_speed, overcrowd_limit, guard_standing, guard_emergency, mobilisable, defensible, food_t, water_m3, fuel_t, surface_line_m, surface_line_real_m, watchtowers) VALUES ('gangbyeon', 2, 'common', '', '', 8320, 4322, 'space', 2377, 'space', 0, 0, 1.0, 4322, 24, 16, 38, 1, 6.8, 10, 34.2, 0, 0, 0);
INSERT INTO stronghold_stage (stronghold_id, stage, variant, terrain_works, terrain_works_ko, floor_m2, capacity, cap_by_max, living_capacity, cap_by, over_living, over_max, air_speed, overcrowd_limit, guard_standing, guard_emergency, mobilisable, defensible, food_t, water_m3, fuel_t, surface_line_m, surface_line_real_m, watchtowers) VALUES ('gangbyeon', 3, 'common', 'Sumps and drainage pumps in the last-stand zone, grilles at the ends of the drains on the river side; Basements of adjoining high-rise buildings used as precinct storerooms', '집수정과 배수펌프를 최후 구역에, 하천 쪽 배수 관로 끝에 창살; 붙은 고층 건물의 지하층을 구내 창고로', 12859, 4322, 'space', 2337, 'space', 0, 0, 2.0, 4322, 51, 20, 38, 1, 13.7, 40, 68.4, 0, 0, 0);
INSERT INTO stronghold_stage (stronghold_id, stage, variant, terrain_works, terrain_works_ko, floor_m2, capacity, cap_by_max, living_capacity, cap_by, over_living, over_max, air_speed, overcrowd_limit, guard_standing, guard_emergency, mobilisable, defensible, food_t, water_m3, fuel_t, surface_line_m, surface_line_real_m, watchtowers) VALUES ('gangbyeon', 4, 'common', 'The river is the moat on one side. The embankment is the wall, bridges and sewer outlets are the gates. A frozen river becomes a road in winter, so there is an ice watch post; The outer walls of the high-rise buildings form the wall. Ground and first-floor windows are blocked, the rooftops are watchtowers, and only the gaps between buildings get barriers', '하천 한쪽이 해자다. 둑이 성벽, 다리와 하수 출구가 문. 겨울에 언 하천은 길이 되므로 얼음 감시 초소; 고층 건물의 외벽 줄이 성벽, 1~2층 창을 막고 고층 꼭대기가 망루, 건물 사이 틈만 방벽', 12859, 4322, 'space', 1607, 'space', 0, 0, 2.5, 4322, 56, 47, 38, 0, 20.5, 114, 102.6, 136, 184, 1);
INSERT INTO stronghold_stage (stronghold_id, stage, variant, terrain_works, terrain_works_ko, floor_m2, capacity, cap_by_max, living_capacity, cap_by, over_living, over_max, air_speed, overcrowd_limit, guard_standing, guard_emergency, mobilisable, defensible, food_t, water_m3, fuel_t, surface_line_m, surface_line_real_m, watchtowers) VALUES ('gangbyeon', 5, 'common', 'One bridge is blocked and one is held as the crossing; High-rise buildings are linked through underground car parks and connecting passages, so people move between them without going outside', '다리 하나를 막고 하나는 지켜 건너는 길로 쓴다; 고층 건물끼리 지하 주차장·연결 통로로 이어 지상에 나가지 않고 오간다', 18259, 5865, 'space', 1825, 'space', 0, 0, 3.0, 5865, 56, 47, 38, 0, 41.6, 285, 208.1, 136, 184, 1);
