INSERT INTO stronghold_stage (stronghold_id, stage, variant, terrain_works, terrain_works_ko, floor_m2, capacity, cap_by_max, living_capacity, cap_by, over_living, over_max, air_speed, overcrowd_limit, guard_standing, guard_emergency, mobilisable, defensible, food_t, water_m3, fuel_t, surface_line_m, surface_line_real_m, watchtowers) VALUES ('gaehwa', 2, 'common', '', '', 8128, 4222, 'space', 2322, 'space', 1, 1, 1.0, 4222, 16, 134, 1642, 1, 218.9, 319, 437.8, 0, 0, 0);
INSERT INTO stronghold_stage (stronghold_id, stage, variant, terrain_works, terrain_works_ko, floor_m2, capacity, cap_by_max, living_capacity, cap_by, over_living, over_max, air_speed, overcrowd_limit, guard_standing, guard_emergency, mobilisable, defensible, food_t, water_m3, fuel_t, surface_line_m, surface_line_real_m, watchtowers) VALUES ('gaehwa', 3, 'common', 'Underpasses and passages below the tracks hardened into inner gates; Basements of low-rise buildings above the entrances used as hidden storerooms', '철길 아래 지하차도와 통로를 안쪽 문으로 굳힌다; 출입구 위 저층 건물의 지하실을 숨긴 창고로', 12561, 4222, 'space', 2283, 'space', 1, 1, 2.0, 4222, 32, 134, 1642, 1, 437.8, 1277, 875.5, 0, 0, 0);
INSERT INTO stronghold_stage (stronghold_id, stage, variant, terrain_works, terrain_works_ko, floor_m2, capacity, cap_by_max, living_capacity, cap_by, over_living, over_max, air_speed, overcrowd_limit, guard_standing, guard_emergency, mobilisable, defensible, food_t, water_m3, fuel_t, surface_line_m, surface_line_real_m, watchtowers) VALUES ('gaehwa', 4, 'common', 'The railway embankments and cuttings are ready-made ramparts. Barriers stand on top, the underpasses and spaces below the rail bridges are the gates, and the top of the embankment is the line of watchtowers; Only a few alley mouths stay open and the rest are blocked into a maze of dead ends; building walls are broken through to make inner passages', '철도 성토·절토가 이미 둑이다. 둑 위에 방벽, 지하차도와 철교 아래가 문, 성토 위가 망루 줄; 골목 입구 몇 곳만 열고 나머지는 막아 막다른 미로로, 건물 벽을 뚫어 안쪽 통로를 낸다', 15190, 4973, 'space', 1898, 'space', 1, 1, 2.5, 4973, 56, 447, 1642, 1, 656.6, 3648, 1313.3, 1044, 1310, 6);
INSERT INTO stronghold_stage (stronghold_id, stage, variant, terrain_works, terrain_works_ko, floor_m2, capacity, cap_by_max, living_capacity, cap_by, over_living, over_max, air_speed, overcrowd_limit, guard_standing, guard_emergency, mobilisable, defensible, food_t, water_m3, fuel_t, surface_line_m, surface_line_real_m, watchtowers) VALUES ('gaehwa', 5, 'common', 'Surface tracks become haul roads (push carts); rail bridges are gates that can be cut or joined; Passages through buildings are joined toward the neighbouring station, giving a route that never goes outside', '지상 선로를 짐 나르는 길로(밀차), 철교는 끊고 잇는 문; 건물 안 통로를 이어 이웃 역 방향으로 지상에 나가지 않는 길을 낸다', 17890, 5744, 'space', 1788, 'space', 1, 1, 3.0, 5744, 56, 447, 1642, 1, 1331.5, 9120, 2663.0, 1044, 1310, 6);
INSERT INTO stronghold_stage (stronghold_id, stage, variant, terrain_works, terrain_works_ko, floor_m2, capacity, cap_by_max, living_capacity, cap_by, over_living, over_max, air_speed, overcrowd_limit, guard_standing, guard_emergency, mobilisable, defensible, food_t, water_m3, fuel_t, surface_line_m, surface_line_real_m, watchtowers) VALUES ('gaehwasan', 1, 'common', '', '', 2210, 710, 'water', 1065, 'water', 0, 0, 1.0, 2209, 3, 18, 192, 1, 6.0, 11, 21.9, 0, 0, 0);
INSERT INTO stronghold_stage (stronghold_id, stage, variant, terrain_works, terrain_works_ko, floor_m2, capacity, cap_by_max, living_capacity, cap_by, over_living, over_max, air_speed, overcrowd_limit, guard_standing, guard_emergency, mobilisable, defensible, food_t, water_m3, fuel_t, surface_line_m, surface_line_real_m, watchtowers) VALUES ('gaehwasan', 2, 'common', '', '', 4861, 710, 'water', 710, 'water', 0, 0, 1.0, 2525, 16, 26, 192, 1, 25.6, 37, 93.7, 0, 0, 0);
INSERT INTO stronghold_stage (stronghold_id, stage, variant, terrain_works, terrain_works_ko, floor_m2, capacity, cap_by_max, living_capacity, cap_by, over_living, over_max, air_speed, overcrowd_limit, guard_standing, guard_emergency, mobilisable, defensible, food_t, water_m3, fuel_t, surface_line_m, surface_line_real_m, watchtowers) VALUES ('gaehwasan', 3, 'common', 'A passage is cut from the estate''s underground car park to the station precinct; Basements of adjoining high-rise buildings used as precinct storerooms', '단지 지하 주차장을 구내와 잇는 통로를 낸다; 붙은 고층 건물의 지하층을 구내 창고로', 7512, 710, 'water', 355, 'water', 1, 0, 2.0, 2525, 40, 30, 192, 1, 51.1, 149, 187.4, 0, 0, 0);
INSERT INTO stronghold_stage (stronghold_id, stage, variant, terrain_works, terrain_works_ko, floor_m2, capacity, cap_by_max, living_capacity, cap_by, over_living, over_max, air_speed, overcrowd_limit, guard_standing, guard_emergency, mobilisable, defensible, food_t, water_m3, fuel_t, surface_line_m, surface_line_real_m, watchtowers) VALUES ('gaehwasan', 4, 'common', 'The apartment estate wall is the inner wall and the estate main gate is the gate. Yards between the blocks become vegetable plots and a firewood yard; The outer walls of the high-rise buildings form the wall. Ground and first-floor windows are blocked, the rooftops are watchtowers, and only the gaps between buildings get barriers', '아파트 단지 담장이 안뜰 성벽, 단지 정문이 성문, 동 사이 마당이 텃밭과 땔감 마당; 고층 건물의 외벽 줄이 성벽, 1~2층 창을 막고 고층 꼭대기가 망루, 건물 사이 틈만 방벽', 7685, 1668, 'water', 625, 'water', 1, 0, 2.5, 2574, 48, 124, 192, 1, 76.7, 426, 281.2, 312, 386, 2);
INSERT INTO stronghold_stage (stronghold_id, stage, variant, terrain_works, terrain_works_ko, floor_m2, capacity, cap_by_max, living_capacity, cap_by, over_living, over_max, air_speed, overcrowd_limit, guard_standing, guard_emergency, mobilisable, defensible, food_t, water_m3, fuel_t, surface_line_m, surface_line_real_m, watchtowers) VALUES ('gaehwasan', 5, 'common', 'Neighbouring estates are taken in one by one, joining several estate strongholds; High-rise buildings are linked through underground car parks and connecting passages, so people move between them without going outside', '이웃 단지를 차례로 편입해 단지 성채 여럿을 잇는다; 고층 건물끼리 지하 주차장·연결 통로로 이어 지상에 나가지 않고 오간다', 13085, 1668, 'water', 500, 'water', 1, 0, 3.0, 4117, 48, 124, 192, 1, 155.5, 1065, 570.1, 312, 386, 2);
