INSERT INTO stronghold_stage (stronghold_id, stage, variant, terrain_works, terrain_works_ko, floor_m2, capacity, cap_by_max, living_capacity, cap_by, over_living, over_max, air_speed, overcrowd_limit, guard_standing, guard_emergency, mobilisable, defensible, food_t, water_m3, fuel_t, surface_line_m, surface_line_real_m, watchtowers) VALUES ('gonghang-sijang', 2, 'common', '', '', 6006, 3120, 'space', 1716, 'space', 0, 0, 1.0, 3120, 30, 46, 348, 1, 46.4, 68, 92.9, 0, 0, 0);
INSERT INTO stronghold_stage (stronghold_id, stage, variant, terrain_works, terrain_works_ko, floor_m2, capacity, cap_by_max, living_capacity, cap_by, over_living, over_max, air_speed, overcrowd_limit, guard_standing, guard_emergency, mobilisable, defensible, food_t, water_m3, fuel_t, surface_line_m, surface_line_real_m, watchtowers) VALUES ('gonghang-sijang', 3, 'common', 'Basements of low-rise buildings above the entrances used as hidden storerooms; Basements of adjoining high-rise buildings used as precinct storerooms', '출입구 위 저층 건물의 지하실을 숨긴 창고로; 붙은 고층 건물의 지하층을 구내 창고로', 9282, 3120, 'space', 1687, 'space', 0, 0, 2.0, 3120, 54, 50, 348, 1, 92.9, 271, 185.8, 0, 0, 0);
INSERT INTO stronghold_stage (stronghold_id, stage, variant, terrain_works, terrain_works_ko, floor_m2, capacity, cap_by_max, living_capacity, cap_by, over_living, over_max, air_speed, overcrowd_limit, guard_standing, guard_emergency, mobilisable, defensible, food_t, water_m3, fuel_t, surface_line_m, surface_line_real_m, watchtowers) VALUES ('gonghang-sijang', 4, 'common', 'Only a few alley mouths stay open and the rest are blocked into a maze of dead ends; building walls are broken through to make inner passages; The outer walls of the high-rise buildings form the wall. Ground and first-floor windows are blocked, the rooftops are watchtowers, and only the gaps between buildings get barriers', '골목 입구 몇 곳만 열고 나머지는 막아 막다른 미로로, 건물 벽을 뚫어 안쪽 통로를 낸다; 고층 건물의 외벽 줄이 성벽, 1~2층 창을 막고 고층 꼭대기가 망루, 건물 사이 틈만 방벽', 9776, 3261, 'space', 1222, 'space', 1, 0, 2.5, 3261, 58, 89, 348, 1, 139.3, 774, 278.6, 132, 182, 1);
INSERT INTO stronghold_stage (stronghold_id, stage, variant, terrain_works, terrain_works_ko, floor_m2, capacity, cap_by_max, living_capacity, cap_by, over_living, over_max, air_speed, overcrowd_limit, guard_standing, guard_emergency, mobilisable, defensible, food_t, water_m3, fuel_t, surface_line_m, surface_line_real_m, watchtowers) VALUES ('gonghang-sijang', 5, 'common', 'Passages through buildings are joined toward the neighbouring station, giving a route that never goes outside; High-rise buildings are linked through underground car parks and connecting passages, so people move between them without going outside', '건물 안 통로를 이어 이웃 역 방향으로 지상에 나가지 않는 길을 낸다; 고층 건물끼리 지하 주차장·연결 통로로 이어 지상에 나가지 않고 오간다', 15176, 4722, 'water', 1416, 'water', 0, 0, 3.0, 4804, 58, 89, 348, 1, 282.5, 1935, 565.0, 132, 182, 1);
