INSERT INTO stronghold_stage (stronghold_id, stage, variant, terrain_works, terrain_works_ko, floor_m2, capacity, cap_by_max, living_capacity, cap_by, over_living, over_max, air_speed, overcrowd_limit, guard_standing, guard_emergency, mobilisable, defensible, food_t, water_m3, fuel_t, surface_line_m, surface_line_real_m, watchtowers) VALUES ('gwanaksan', 2, 'common', '', '', 2461, 1278, 'space', 703, 'space', 1, 1, 1.0, 1278, 12, 134, 1696, 1, 226.1, 330, 452.2, 0, 0, 0);
INSERT INTO stronghold_stage (stronghold_id, stage, variant, terrain_works, terrain_works_ko, floor_m2, capacity, cap_by_max, living_capacity, cap_by, over_living, over_max, air_speed, overcrowd_limit, guard_standing, guard_emergency, mobilisable, defensible, food_t, water_m3, fuel_t, surface_line_m, surface_line_real_m, watchtowers) VALUES ('gwanaksan', 3, 'common', 'Air intakes placed upslope (upwind) and exhaust sent down into the valley; For a shallow station, pairing with a deep neighbour comes first', '급기구를 비탈 위쪽(공기 상류)에 두고 배기는 골짜기 아래로; 얕은 역이면 깊은 이웃 역과 짝을 맺는 것이 먼저', 3804, 1278, 'space', 691, 'space', 1, 1, 2.0, 1278, 28, 134, 1696, 1, 452.2, 1319, 904.3, 0, 0, 0);
INSERT INTO stronghold_stage (stronghold_id, stage, variant, terrain_works, terrain_works_ko, floor_m2, capacity, cap_by_max, living_capacity, cap_by, over_living, over_max, air_speed, overcrowd_limit, guard_standing, guard_emergency, mobilisable, defensible, food_t, water_m3, fuel_t, surface_line_m, surface_line_real_m, watchtowers) VALUES ('gwanaksan', 4, 'common', 'The line runs along the ridge and slopes. The tallest building or rocky knoll is the watchtower, the slope itself is the cleared strip, and grilles close the sewer outlets on the valley side; With no terrain to lean on, banks are raised and ditches dug. Wide roads are kept as the cleared strip (field of fire), with watchtowers at the corners', '능선과 비탈을 따라 두른다. 가장 높은 건물·바위 언덕이 망루, 비탈 자체가 비워 둔 띠, 골짜기 쪽 하수 수구에 창살; 기댈 지형이 없어 둑을 쌓고 해자를 판다. 넓은 길은 비워 둔 띠(사격 띠)로, 모서리에 망루', 13846, 4147, 'space', 1730, 'space', 1, 1, 2.5, 4147, 56, 552, 1696, 1, 678.2, 3768, 1356.5, 1395, 1755, 7);
INSERT INTO stronghold_stage (stronghold_id, stage, variant, terrain_works, terrain_works_ko, floor_m2, capacity, cap_by_max, living_capacity, cap_by, over_living, over_max, air_speed, overcrowd_limit, guard_standing, guard_emergency, mobilisable, defensible, food_t, water_m3, fuel_t, surface_line_m, surface_line_real_m, watchtowers) VALUES ('gwanaksan', 5, 'common', 'Signal points on the ridge keep a line of sight to the neighbouring stations; A shallow station cannot stand alone. It exists only as a pair with a deep neighbour', '능선 위 신호 자리로 이웃 역과 보이는 줄을 잇는다; 얕은 역은 혼자 서지 못한다. 깊은 이웃 역과의 짝으로만 성립', 16546, 4919, 'space', 1654, 'space', 1, 1, 3.0, 4919, 56, 552, 1696, 1, 1375.3, 9420, 2750.6, 1395, 1755, 7);
