INSERT INTO stronghold_stage (stronghold_id, stage, variant, terrain_works, terrain_works_ko, floor_m2, capacity, cap_by_max, living_capacity, cap_by, over_living, over_max, air_speed, overcrowd_limit, guard_standing, guard_emergency, mobilisable, defensible, food_t, water_m3, fuel_t, surface_line_m, surface_line_real_m, watchtowers) VALUES ('gwangundae', 5, 'common', 'Neighbouring estates are taken in one by one, joining several estate strongholds; Surface tracks become haul roads (push carts); rail bridges are gates that can be cut or joined', '이웃 단지를 차례로 편입해 단지 성채 여럿을 잇는다; 지상 선로를 짐 나르는 길로(밀차), 철교는 끊고 잇는 문', 13008, 445, 'water', 133, 'space', 0, 0, 3.0, 4100, 60, 69, 12, 0, 13.1, 90, 65.7, 260, 388, 2);
