INSERT INTO stronghold_stage (stronghold_id, stage, variant, terrain_works, terrain_works_ko, floor_m2, capacity, cap_by_max, living_capacity, cap_by, over_living, over_max, air_speed, overcrowd_limit, guard_standing, guard_emergency, mobilisable, defensible, food_t, water_m3, fuel_t, surface_line_m, surface_line_real_m, watchtowers) VALUES ('gwangheungchang', 3, 'common', 'A passage is cut from the estate''s underground car park to the station precinct; Basements of low-rise buildings above the entrances used as hidden storerooms', '단지 지하 주차장을 구내와 잇는 통로를 낸다; 출입구 위 저층 건물의 지하실을 숨긴 창고로', 7976, 2680, 'space', 1450, 'space', 1, 0, 2.0, 2680, 51, 46, 300, 1, 108.0, 315, 216.0, 0, 0, 0);
INSERT INTO stronghold_stage (stronghold_id, stage, variant, terrain_works, terrain_works_ko, floor_m2, capacity, cap_by_max, living_capacity, cap_by, over_living, over_max, air_speed, overcrowd_limit, guard_standing, guard_emergency, mobilisable, defensible, food_t, water_m3, fuel_t, surface_line_m, surface_line_real_m, watchtowers) VALUES ('gwangheungchang', 4, 'common', 'The apartment estate wall is the inner wall and the estate main gate is the gate. Yards between the blocks become vegetable plots and a firewood yard; Only a few alley mouths stay open and the rest are blocked into a maze of dead ends; building walls are broken through to make inner passages', '아파트 단지 담장이 안뜰 성벽, 단지 정문이 성문, 동 사이 마당이 텃밭과 땔감 마당; 골목 입구 몇 곳만 열고 나머지는 막아 막다른 미로로, 건물 벽을 뚫어 안쪽 통로를 낸다', 8803, 2917, 'space', 1100, 'space', 1, 0, 2.5, 2917, 60, 88, 300, 1, 162.0, 900, 324.0, 212, 290, 2);
INSERT INTO stronghold_stage (stronghold_id, stage, variant, terrain_works, terrain_works_ko, floor_m2, capacity, cap_by_max, living_capacity, cap_by, over_living, over_max, air_speed, overcrowd_limit, guard_standing, guard_emergency, mobilisable, defensible, food_t, water_m3, fuel_t, surface_line_m, surface_line_real_m, watchtowers) VALUES ('gwangheungchang', 5, 'common', 'Neighbouring estates are taken in one by one, joining several estate strongholds; Passages through buildings are joined toward the neighbouring station, giving a route that never goes outside', '이웃 단지를 차례로 편입해 단지 성채 여럿을 잇는다; 건물 안 통로를 이어 이웃 역 방향으로 지상에 나가지 않는 길을 낸다', 14203, 4460, 'space', 1420, 'space', 1, 0, 3.0, 4460, 60, 88, 300, 1, 328.5, 2250, 657.0, 212, 290, 2);
INSERT INTO stronghold_stage (stronghold_id, stage, variant, terrain_works, terrain_works_ko, floor_m2, capacity, cap_by_max, living_capacity, cap_by, over_living, over_max, air_speed, overcrowd_limit, guard_standing, guard_emergency, mobilisable, defensible, food_t, water_m3, fuel_t, surface_line_m, surface_line_real_m, watchtowers) VALUES ('gyodae', 1, 'common', '', '', 5110, 3160, 'water', 3406, 'space', 0, 0, 1.0, 5110, 21, 36, 474, 1, 13.3, 24, 35.4, 0, 0, 0);
INSERT INTO stronghold_stage (stronghold_id, stage, variant, terrain_works, terrain_works_ko, floor_m2, capacity, cap_by_max, living_capacity, cap_by, over_living, over_max, air_speed, overcrowd_limit, guard_standing, guard_emergency, mobilisable, defensible, food_t, water_m3, fuel_t, surface_line_m, surface_line_real_m, watchtowers) VALUES ('gyodae', 2, 'common', '', '', 11242, 3160, 'water', 3160, 'water', 0, 0, 1.0, 5840, 42, 52, 474, 1, 56.9, 83, 151.7, 0, 0, 0);
INSERT INTO stronghold_stage (stronghold_id, stage, variant, terrain_works, terrain_works_ko, floor_m2, capacity, cap_by_max, living_capacity, cap_by, over_living, over_max, air_speed, overcrowd_limit, guard_standing, guard_emergency, mobilisable, defensible, food_t, water_m3, fuel_t, surface_line_m, surface_line_real_m, watchtowers) VALUES ('gyodae', 3, 'common', 'Basements of adjoining high-rise buildings used as precinct storerooms; Basements of low-rise buildings above the entrances used as hidden storerooms', '붙은 고층 건물의 지하층을 구내 창고로; 출입구 위 저층 건물의 지하실을 숨긴 창고로', 17374, 3160, 'water', 1580, 'water', 0, 0, 2.0, 5840, 90, 56, 474, 1, 113.8, 332, 303.4, 0, 0, 0);
INSERT INTO stronghold_stage (stronghold_id, stage, variant, terrain_works, terrain_works_ko, floor_m2, capacity, cap_by_max, living_capacity, cap_by, over_living, over_max, air_speed, overcrowd_limit, guard_standing, guard_emergency, mobilisable, defensible, food_t, water_m3, fuel_t, surface_line_m, surface_line_real_m, watchtowers) VALUES ('gyodae', 4, 'arc', 'The outer walls of the high-rise buildings form the wall. Ground and first-floor windows are blocked, the rooftops are watchtowers, and only the gaps between buildings get barriers; Only a few alley mouths stay open and the rest are blocked into a maze of dead ends; building walls are broken through to make inner passages', '고층 건물의 외벽 줄이 성벽, 1~2층 창을 막고 고층 꼭대기가 망루, 건물 사이 틈만 방벽; 골목 입구 몇 곳만 열고 나머지는 막아 막다른 미로로, 건물 벽을 뚫어 안쪽 통로를 낸다', 17374, 3160, 'water', 1185, 'water', 1, 0, 2.5, 5840, 90, 56, 474, 1, 170.6, 948, 455.0, 0, 0, 0);
INSERT INTO stronghold_stage (stronghold_id, stage, variant, terrain_works, terrain_works_ko, floor_m2, capacity, cap_by_max, living_capacity, cap_by, over_living, over_max, air_speed, overcrowd_limit, guard_standing, guard_emergency, mobilisable, defensible, food_t, water_m3, fuel_t, surface_line_m, surface_line_real_m, watchtowers) VALUES ('gyodae', 5, 'arc', 'High-rise buildings are linked through underground car parks and connecting passages, so people move between them without going outside; Passages through buildings are joined toward the neighbouring station, giving a route that never goes outside', '고층 건물끼리 지하 주차장·연결 통로로 이어 지상에 나가지 않고 오간다; 건물 안 통로를 이어 이웃 역 방향으로 지상에 나가지 않는 길을 낸다', 28174, 3160, 'water', 948, 'water', 1, 0, 3.0, 8925, 90, 56, 474, 1, 346.0, 2370, 922.7, 0, 0, 0);
