INSERT INTO stronghold_stage (stronghold_id, stage, variant, terrain_works, terrain_works_ko, floor_m2, capacity, cap_by_max, living_capacity, cap_by, over_living, over_max, air_speed, overcrowd_limit, guard_standing, guard_emergency, mobilisable, defensible, food_t, water_m3, fuel_t, surface_line_m, surface_line_real_m, watchtowers) VALUES ('guro', 4, 'common', 'The railway embankments and cuttings are ready-made ramparts. Barriers stand on top, the underpasses and spaces below the rail bridges are the gates, and the top of the embankment is the line of watchtowers; Only a few alley mouths stay open and the rest are blocked into a maze of dead ends; building walls are broken through to make inner passages', '철도 성토·절토가 이미 둑이다. 둑 위에 방벽, 지하차도와 철교 아래가 문, 성토 위가 망루 줄; 골목 입구 몇 곳만 열고 나머지는 막아 막다른 미로로, 건물 벽을 뚫어 안쪽 통로를 낸다', 22668, 7619, 'space', 2833, 'space', 0, 0, 2.5, 7619, 56, 122, 707, 1, 283.0, 1572, 1414.8, 152, 253, 1);
INSERT INTO stronghold_stage (stronghold_id, stage, variant, terrain_works, terrain_works_ko, floor_m2, capacity, cap_by_max, living_capacity, cap_by, over_living, over_max, air_speed, overcrowd_limit, guard_standing, guard_emergency, mobilisable, defensible, food_t, water_m3, fuel_t, surface_line_m, surface_line_real_m, watchtowers) VALUES ('guro', 5, 'common', 'Surface tracks become haul roads (push carts); rail bridges are gates that can be cut or joined; Passages through buildings are joined toward the neighbouring station, giving a route that never goes outside', '지상 선로를 짐 나르는 길로(밀차), 철교는 끊고 잇는 문; 건물 안 통로를 이어 이웃 역 방향으로 지상에 나가지 않는 길을 낸다', 30768, 9933, 'space', 3076, 'space', 0, 0, 3.0, 9933, 56, 122, 707, 1, 573.8, 3930, 2868.9, 152, 253, 1);
