INSERT INTO stronghold_stage (stronghold_id, stage, variant, terrain_works, terrain_works_ko, floor_m2, capacity, cap_by_max, living_capacity, cap_by, over_living, over_max, air_speed, overcrowd_limit, guard_standing, guard_emergency, mobilisable, defensible, food_t, water_m3, fuel_t, surface_line_m, surface_line_real_m, watchtowers) VALUES ('guil', 3, 'common', 'Sumps and drainage pumps in the last-stand zone, grilles at the ends of the drains on the river side; Underpasses and passages below the tracks hardened into inner gates', '집수정과 배수펌프를 최후 구역에, 하천 쪽 배수 관로 끝에 창살; 철길 아래 지하차도와 통로를 안쪽 문으로 굳힌다', 11754, 3950, 'space', 2137, 'space', 0, 0, 2.0, 3950, 42, 14, 22, 1, 5.8, 17, 28.8, 0, 0, 0);
INSERT INTO stronghold_stage (stronghold_id, stage, variant, terrain_works, terrain_works_ko, floor_m2, capacity, cap_by_max, living_capacity, cap_by, over_living, over_max, air_speed, overcrowd_limit, guard_standing, guard_emergency, mobilisable, defensible, food_t, water_m3, fuel_t, surface_line_m, surface_line_real_m, watchtowers) VALUES ('guil', 4, 'common', 'The river is the moat on one side. The embankment is the wall, bridges and sewer outlets are the gates. A frozen river becomes a road in winter, so there is an ice watch post; The railway embankments and cuttings are ready-made ramparts. Barriers stand on top, the underpasses and spaces below the rail bridges are the gates, and the top of the embankment is the line of watchtowers', '하천 한쪽이 해자다. 둑이 성벽, 다리와 하수 출구가 문. 겨울에 언 하천은 길이 되므로 얼음 감시 초소; 철도 성토·절토가 이미 둑이다. 둑 위에 방벽, 지하차도와 철교 아래가 문, 성토 위가 망루 줄', 11754, 158, 'water', 59, 'space', 1, 0, 2.5, 3950, 50, 80, 22, 0, 8.6, 48, 43.2, 220, 359, 2);
INSERT INTO stronghold_stage (stronghold_id, stage, variant, terrain_works, terrain_works_ko, floor_m2, capacity, cap_by_max, living_capacity, cap_by, over_living, over_max, air_speed, overcrowd_limit, guard_standing, guard_emergency, mobilisable, defensible, food_t, water_m3, fuel_t, surface_line_m, surface_line_real_m, watchtowers) VALUES ('guil', 5, 'common', 'One bridge is blocked and one is held as the crossing; Surface tracks become haul roads (push carts); rail bridges are gates that can be cut or joined', '다리 하나를 막고 하나는 지켜 건너는 길로 쓴다; 지상 선로를 짐 나르는 길로(밀차), 철교는 끊고 잇는 문', 17154, 158, 'water', 47, 'space', 1, 0, 3.0, 5493, 50, 80, 22, 0, 17.5, 120, 87.6, 220, 359, 2);
INSERT INTO stronghold_stage (stronghold_id, stage, variant, terrain_works, terrain_works_ko, floor_m2, capacity, cap_by_max, living_capacity, cap_by, over_living, over_max, air_speed, overcrowd_limit, guard_standing, guard_emergency, mobilisable, defensible, food_t, water_m3, fuel_t, surface_line_m, surface_line_real_m, watchtowers) VALUES ('gupabal', 1, 'common', '', '', 1729, 1976, 'space', 1152, 'space', 1, 1, 1.0, 1729, 9, 59, 546, 1, 22.9, 41, 84.1, 0, 0, 0);
