INSERT INTO stronghold_stage (stronghold_id, stage, variant, terrain_works, terrain_works_ko, floor_m2, capacity, cap_by_max, living_capacity, cap_by, over_living, over_max, air_speed, overcrowd_limit, guard_standing, guard_emergency, mobilisable, defensible, food_t, water_m3, fuel_t, surface_line_m, surface_line_real_m, watchtowers) VALUES ('gupabal', 3, 'common', 'Air intakes placed upslope (upwind) and exhaust sent down into the valley; Basements of adjoining high-rise buildings used as precinct storerooms', '급기구를 비탈 위쪽(공기 상류)에 두고 배기는 골짜기 아래로; 붙은 고층 건물의 지하층을 구내 창고로', 5879, 1976, 'space', 1068, 'space', 1, 1, 2.0, 1976, 51, 71, 546, 1, 196.6, 573, 720.7, 0, 0, 0);
INSERT INTO stronghold_stage (stronghold_id, stage, variant, terrain_works, terrain_works_ko, floor_m2, capacity, cap_by_max, living_capacity, cap_by, over_living, over_max, air_speed, overcrowd_limit, guard_standing, guard_emergency, mobilisable, defensible, food_t, water_m3, fuel_t, surface_line_m, surface_line_real_m, watchtowers) VALUES ('gupabal', 4, 'common', 'The line runs along the ridge and slopes. The tallest building or rocky knoll is the watchtower, the slope itself is the cleared strip, and grilles close the sewer outlets on the valley side; The outer walls of the high-rise buildings form the wall. Ground and first-floor windows are blocked, the rooftops are watchtowers, and only the gaps between buildings get barriers', '능선과 비탈을 따라 두른다. 가장 높은 건물·바위 언덕이 망루, 비탈 자체가 비워 둔 띠, 골짜기 쪽 하수 수구에 창살; 고층 건물의 외벽 줄이 성벽, 1~2층 창을 막고 고층 꼭대기가 망루, 건물 사이 틈만 방벽', 5879, 1976, 'space', 734, 'space', 1, 1, 2.5, 1976, 56, 106, 546, 1, 294.8, 1638, 1081.1, 178, 188, 1);
INSERT INTO stronghold_stage (stronghold_id, stage, variant, terrain_works, terrain_works_ko, floor_m2, capacity, cap_by_max, living_capacity, cap_by, over_living, over_max, air_speed, overcrowd_limit, guard_standing, guard_emergency, mobilisable, defensible, food_t, water_m3, fuel_t, surface_line_m, surface_line_real_m, watchtowers) VALUES ('gupabal', 5, 'common', 'Signal points on the ridge keep a line of sight to the neighbouring stations; High-rise buildings are linked through underground car parks and connecting passages, so people move between them without going outside', '능선 위 신호 자리로 이웃 역과 보이는 줄을 잇는다; 고층 건물끼리 지하 주차장·연결 통로로 이어 지상에 나가지 않고 오간다', 8579, 2730, 'water', 819, 'water', 1, 0, 3.0, 2747, 56, 106, 546, 1, 597.9, 4095, 2192.2, 178, 188, 1);
