INSERT INTO stronghold_stage (stronghold_id, stage, variant, terrain_works, terrain_works_ko, floor_m2, capacity, cap_by_max, living_capacity, cap_by, over_living, over_max, air_speed, overcrowd_limit, guard_standing, guard_emergency, mobilisable, defensible, food_t, water_m3, fuel_t, surface_line_m, surface_line_real_m, watchtowers) VALUES ('national-assembly-building', 3, 'common', 'Basements of adjoining high-rise buildings used as precinct storerooms; For a shallow station, pairing with a deep neighbour comes first', '붙은 고층 건물의 지하층을 구내 창고로; 얕은 역이면 깊은 이웃 역과 짝을 맺는 것이 먼저', 11778, 3959, 'space', 2141, 'space', 0, 0, 2.0, 3959, 54, 51, 370, 1, 98.6, 288, 197.3, 0, 0, 0);
INSERT INTO stronghold_stage (stronghold_id, stage, variant, terrain_works, terrain_works_ko, floor_m2, capacity, cap_by_max, living_capacity, cap_by, over_living, over_max, air_speed, overcrowd_limit, guard_standing, guard_emergency, mobilisable, defensible, food_t, water_m3, fuel_t, surface_line_m, surface_line_real_m, watchtowers) VALUES ('national-assembly-building', 4, 'common', 'The outer walls of the high-rise buildings form the wall. Ground and first-floor windows are blocked, the rooftops are watchtowers, and only the gaps between buildings get barriers; With no terrain to lean on, banks are raised and ditches dug. Wide roads are kept as the cleared strip (field of fire), with watchtowers at the corners', '고층 건물의 외벽 줄이 성벽, 1~2층 창을 막고 고층 꼭대기가 망루, 건물 사이 틈만 방벽; 기댈 지형이 없어 둑을 쌓고 해자를 판다. 넓은 길은 비워 둔 띠(사격 띠)로, 모서리에 망루', 11778, 3959, 'space', 1472, 'space', 0, 0, 2.5, 3959, 62, 144, 370, 1, 148.0, 822, 295.9, 310, 332, 2);
INSERT INTO stronghold_stage (stronghold_id, stage, variant, terrain_works, terrain_works_ko, floor_m2, capacity, cap_by_max, living_capacity, cap_by, over_living, over_max, air_speed, overcrowd_limit, guard_standing, guard_emergency, mobilisable, defensible, food_t, water_m3, fuel_t, surface_line_m, surface_line_real_m, watchtowers) VALUES ('national-assembly-building', 5, 'common', 'High-rise buildings are linked through underground car parks and connecting passages, so people move between them without going outside; A shallow station cannot stand alone. It exists only as a pair with a deep neighbour', '고층 건물끼리 지하 주차장·연결 통로로 이어 지상에 나가지 않고 오간다; 얕은 역은 혼자 서지 못한다. 깊은 이웃 역과의 짝으로만 성립', 17178, 4566, 'water', 1370, 'water', 0, 0, 3.0, 5502, 62, 144, 370, 1, 300.0, 2055, 600.1, 310, 332, 2);
