INSERT INTO stronghold_stage (stronghold_id, stage, variant, terrain_works, terrain_works_ko, floor_m2, capacity, cap_by_max, living_capacity, cap_by, over_living, over_max, air_speed, overcrowd_limit, guard_standing, guard_emergency, mobilisable, defensible, food_t, water_m3, fuel_t, surface_line_m, surface_line_real_m, watchtowers) VALUES ('gubeundari', 3, 'common', 'Basements of low-rise buildings above the entrances used as hidden storerooms; A passage is cut from the estate''s underground car park to the station precinct', '출입구 위 저층 건물의 지하실을 숨긴 창고로; 단지 지하 주차장을 구내와 잇는 통로를 낸다', 4908, 840, 'water', 420, 'water', 0, 0, 2.0, 1649, 46, 24, 126, 1, 30.2, 88, 80.6, 0, 0, 0);
INSERT INTO stronghold_stage (stronghold_id, stage, variant, terrain_works, terrain_works_ko, floor_m2, capacity, cap_by_max, living_capacity, cap_by, over_living, over_max, air_speed, overcrowd_limit, guard_standing, guard_emergency, mobilisable, defensible, food_t, water_m3, fuel_t, surface_line_m, surface_line_real_m, watchtowers) VALUES ('gubeundari', 4, 'arc', 'Only a few alley mouths stay open and the rest are blocked into a maze of dead ends; building walls are broken through to make inner passages; The apartment estate wall is the inner wall and the estate main gate is the gate. Yards between the blocks become vegetable plots and a firewood yard', '골목 입구 몇 곳만 열고 나머지는 막아 막다른 미로로, 건물 벽을 뚫어 안쪽 통로를 낸다; 아파트 단지 담장이 안뜰 성벽, 단지 정문이 성문, 동 사이 마당이 텃밭과 땔감 마당', 4908, 840, 'water', 315, 'water', 1, 0, 2.5, 1649, 46, 24, 126, 1, 45.4, 252, 121.0, 0, 0, 0);
INSERT INTO stronghold_stage (stronghold_id, stage, variant, terrain_works, terrain_works_ko, floor_m2, capacity, cap_by_max, living_capacity, cap_by, over_living, over_max, air_speed, overcrowd_limit, guard_standing, guard_emergency, mobilisable, defensible, food_t, water_m3, fuel_t, surface_line_m, surface_line_real_m, watchtowers) VALUES ('gubeundari', 5, 'arc', 'Passages through buildings are joined toward the neighbouring station, giving a route that never goes outside; Neighbouring estates are taken in one by one, joining several estate strongholds', '건물 안 통로를 이어 이웃 역 방향으로 지상에 나가지 않는 길을 낸다; 이웃 단지를 차례로 편입해 단지 성채 여럿을 잇는다', 10308, 840, 'water', 252, 'water', 1, 0, 3.0, 3192, 46, 24, 126, 1, 92.0, 630, 245.3, 0, 0, 0);
