INSERT INTO stronghold_stage (stronghold_id, stage, variant, terrain_works, terrain_works_ko, floor_m2, capacity, cap_by_max, living_capacity, cap_by, over_living, over_max, air_speed, overcrowd_limit, guard_standing, guard_emergency, mobilisable, defensible, food_t, water_m3, fuel_t, surface_line_m, surface_line_real_m, watchtowers) VALUES ('geumho', 3, 'common', 'A passage is cut from the estate''s underground car park to the station precinct; Air intakes placed upslope (upwind) and exhaust sent down into the valley', '단지 지하 주차장을 구내와 잇는 통로를 낸다; 급기구를 비탈 위쪽(공기 상류)에 두고 배기는 골짜기 아래로', 5884, 810, 'water', 405, 'water', 1, 0, 2.0, 1977, 51, 32, 162, 1, 58.3, 170, 213.8, 0, 0, 0);
INSERT INTO stronghold_stage (stronghold_id, stage, variant, terrain_works, terrain_works_ko, floor_m2, capacity, cap_by_max, living_capacity, cap_by, over_living, over_max, air_speed, overcrowd_limit, guard_standing, guard_emergency, mobilisable, defensible, food_t, water_m3, fuel_t, surface_line_m, surface_line_real_m, watchtowers) VALUES ('geumho', 4, 'common', 'The apartment estate wall is the inner wall and the estate main gate is the gate. Yards between the blocks become vegetable plots and a firewood yard; The line runs along the ridge and slopes. The tallest building or rocky knoll is the watchtower, the slope itself is the cleared strip, and grilles close the sewer outlets on the valley side', '아파트 단지 담장이 안뜰 성벽, 단지 정문이 성문, 동 사이 마당이 텃밭과 땔감 마당; 능선과 비탈을 따라 두른다. 가장 높은 건물·바위 언덕이 망루, 비탈 자체가 비워 둔 띠, 골짜기 쪽 하수 수구에 창살', 7099, 1258, 'water', 471, 'water', 1, 0, 2.5, 2325, 60, 100, 162, 1, 87.5, 486, 320.8, 337, 392, 2);
INSERT INTO stronghold_stage (stronghold_id, stage, variant, terrain_works, terrain_works_ko, floor_m2, capacity, cap_by_max, living_capacity, cap_by, over_living, over_max, air_speed, overcrowd_limit, guard_standing, guard_emergency, mobilisable, defensible, food_t, water_m3, fuel_t, surface_line_m, surface_line_real_m, watchtowers) VALUES ('geumho', 5, 'common', 'Neighbouring estates are taken in one by one, joining several estate strongholds; Signal points on the ridge keep a line of sight to the neighbouring stations', '이웃 단지를 차례로 편입해 단지 성채 여럿을 잇는다; 능선 위 신호 자리로 이웃 역과 보이는 줄을 잇는다', 12499, 1258, 'water', 377, 'water', 1, 0, 3.0, 3867, 60, 100, 162, 1, 177.4, 1215, 650.4, 337, 392, 2);
