INSERT INTO stronghold_stage (stronghold_id, stage, variant, terrain_works, terrain_works_ko, floor_m2, capacity, cap_by_max, living_capacity, cap_by, over_living, over_max, air_speed, overcrowd_limit, guard_standing, guard_emergency, mobilisable, defensible, food_t, water_m3, fuel_t, surface_line_m, surface_line_real_m, watchtowers) VALUES ('male', 5, 'common', 'Neighbouring estates are taken in one by one, joining several estate strongholds; Passages through buildings are joined toward the neighbouring station, giving a route that never goes outside', '이웃 단지를 차례로 편입해 단지 성채 여럿을 잇는다; 건물 안 통로를 이어 이웃 역 방향으로 지상에 나가지 않는 길을 낸다', 12682, 3954, 'space', 1268, 'space', 1, 0, 3.0, 3954, 66, 135, 440, 1, 357.0, 2445, 713.9, 288, 324, 2);
