INSERT INTO stronghold_stage (stronghold_id, stage, variant, terrain_works, terrain_works_ko, floor_m2, capacity, cap_by_max, living_capacity, cap_by, over_living, over_max, air_speed, overcrowd_limit, guard_standing, guard_emergency, mobilisable, defensible, food_t, water_m3, fuel_t, surface_line_m, surface_line_real_m, watchtowers) VALUES ('namyeong', 3, 'common', 'Basements of low-rise buildings above the entrances used as hidden storerooms; Underpasses and passages below the tracks hardened into inner gates', '출입구 위 저층 건물의 지하실을 숨긴 창고로; 철길 아래 지하차도와 통로를 안쪽 문으로 굳힌다', 4490, 1509, 'space', 816, 'space', 0, 0, 2.0, 1509, 40, 14, 18, 1, 6.5, 19, 32.4, 0, 0, 0);
INSERT INTO stronghold_stage (stronghold_id, stage, variant, terrain_works, terrain_works_ko, floor_m2, capacity, cap_by_max, living_capacity, cap_by, over_living, over_max, air_speed, overcrowd_limit, guard_standing, guard_emergency, mobilisable, defensible, food_t, water_m3, fuel_t, surface_line_m, surface_line_real_m, watchtowers) VALUES ('namyeong', 4, 'common', 'Only a few alley mouths stay open and the rest are blocked into a maze of dead ends; building walls are broken through to make inner passages; The railway embankments and cuttings are ready-made ramparts. Barriers stand on top, the underpasses and spaces below the rail bridges are the gates, and the top of the embankment is the line of watchtowers', '골목 입구 몇 곳만 열고 나머지는 막아 막다른 미로로, 건물 벽을 뚫어 안쪽 통로를 낸다; 철도 성토·절토가 이미 둑이다. 둑 위에 방벽, 지하차도와 철교 아래가 문, 성토 위가 망루 줄', 7881, 670, 'water', 251, 'space', 0, 0, 2.5, 2478, 45, 40, 18, 0, 9.7, 54, 48.6, 128, 210, 1);
INSERT INTO stronghold_stage (stronghold_id, stage, variant, terrain_works, terrain_works_ko, floor_m2, capacity, cap_by_max, living_capacity, cap_by, over_living, over_max, air_speed, overcrowd_limit, guard_standing, guard_emergency, mobilisable, defensible, food_t, water_m3, fuel_t, surface_line_m, surface_line_real_m, watchtowers) VALUES ('namyeong', 5, 'common', 'Passages through buildings are joined toward the neighbouring station, giving a route that never goes outside; Surface tracks become haul roads (push carts); rail bridges are gates that can be cut or joined', '건물 안 통로를 이어 이웃 역 방향으로 지상에 나가지 않는 길을 낸다; 지상 선로를 짐 나르는 길로(밀차), 철교는 끊고 잇는 문', 13281, 670, 'water', 201, 'space', 0, 0, 3.0, 4020, 45, 40, 18, 0, 19.7, 135, 98.5, 128, 210, 1);
