INSERT INTO stronghold_stage (stronghold_id, stage, variant, terrain_works, terrain_works_ko, floor_m2, capacity, cap_by_max, living_capacity, cap_by, over_living, over_max, air_speed, overcrowd_limit, guard_standing, guard_emergency, mobilisable, defensible, food_t, water_m3, fuel_t, surface_line_m, surface_line_real_m, watchtowers) VALUES ('nowon', 2, 'common', '', '', 6879, 3573, 'space', 1965, 'space', 1, 1, 1.0, 3573, 44, 102, 778, 1, 140.0, 204, 280.1, 0, 0, 0);
INSERT INTO stronghold_stage (stronghold_id, stage, variant, terrain_works, terrain_works_ko, floor_m2, capacity, cap_by_max, living_capacity, cap_by, over_living, over_max, air_speed, overcrowd_limit, guard_standing, guard_emergency, mobilisable, defensible, food_t, water_m3, fuel_t, surface_line_m, surface_line_real_m, watchtowers) VALUES ('nowon', 3, 'common', 'A passage is cut from the estate''s underground car park to the station precinct; Basements of adjoining high-rise buildings used as precinct storerooms', '단지 지하 주차장을 구내와 잇는 통로를 낸다; 붙은 고층 건물의 지하층을 구내 창고로', 10631, 3573, 'space', 1932, 'space', 1, 1, 2.0, 3573, 80, 106, 778, 1, 280.1, 817, 560.2, 0, 0, 0);
INSERT INTO stronghold_stage (stronghold_id, stage, variant, terrain_works, terrain_works_ko, floor_m2, capacity, cap_by_max, living_capacity, cap_by, over_living, over_max, air_speed, overcrowd_limit, guard_standing, guard_emergency, mobilisable, defensible, food_t, water_m3, fuel_t, surface_line_m, surface_line_real_m, watchtowers) VALUES ('nowon', 4, 'common', 'The apartment estate wall is the inner wall and the estate main gate is the gate. Yards between the blocks become vegetable plots and a firewood yard; The outer walls of the high-rise buildings form the wall. Ground and first-floor windows are blocked, the rooftops are watchtowers, and only the gaps between buildings get barriers', '아파트 단지 담장이 안뜰 성벽, 단지 정문이 성문, 동 사이 마당이 텃밭과 땔감 마당; 고층 건물의 외벽 줄이 성벽, 1~2층 창을 막고 고층 꼭대기가 망루, 건물 사이 틈만 방벽', 10891, 3647, 'space', 1361, 'space', 1, 1, 2.5, 3647, 88, 164, 778, 1, 420.1, 2334, 840.2, 293, 375, 2);
INSERT INTO stronghold_stage (stronghold_id, stage, variant, terrain_works, terrain_works_ko, floor_m2, capacity, cap_by_max, living_capacity, cap_by, over_living, over_max, air_speed, overcrowd_limit, guard_standing, guard_emergency, mobilisable, defensible, food_t, water_m3, fuel_t, surface_line_m, surface_line_real_m, watchtowers) VALUES ('nowon', 5, 'common', 'Neighbouring estates are taken in one by one, joining several estate strongholds; High-rise buildings are linked through underground car parks and connecting passages, so people move between them without going outside', '이웃 단지를 차례로 편입해 단지 성채 여럿을 잇는다; 고층 건물끼리 지하 주차장·연결 통로로 이어 지상에 나가지 않고 오간다', 21691, 6733, 'space', 2169, 'space', 1, 0, 3.0, 6733, 88, 164, 778, 1, 851.9, 5835, 1703.8, 293, 375, 2);
