INSERT INTO stronghold_stage (stronghold_id, stage, variant, terrain_works, terrain_works_ko, floor_m2, capacity, cap_by_max, living_capacity, cap_by, over_living, over_max, air_speed, overcrowd_limit, guard_standing, guard_emergency, mobilisable, defensible, food_t, water_m3, fuel_t, surface_line_m, surface_line_real_m, watchtowers) VALUES ('daebang', 4, 'common', 'The railway embankments and cuttings are ready-made ramparts. Barriers stand on top, the underpasses and spaces below the rail bridges are the gates, and the top of the embankment is the line of watchtowers; The apartment estate wall is the inner wall and the estate main gate is the gate. Yards between the blocks become vegetable plots and a firewood yard', '철도 성토·절토가 이미 둑이다. 둑 위에 방벽, 지하차도와 철교 아래가 문, 성토 위가 망루 줄; 아파트 단지 담장이 안뜰 성벽, 단지 정문이 성문, 동 사이 마당이 텃밭과 땔감 마당', 5413, 1819, 'space', 676, 'space', 1, 1, 2.5, 1819, 74, 156, 756, 1, 302.4, 1680, 604.8, 241, 449, 2);
INSERT INTO stronghold_stage (stronghold_id, stage, variant, terrain_works, terrain_works_ko, floor_m2, capacity, cap_by_max, living_capacity, cap_by, over_living, over_max, air_speed, overcrowd_limit, guard_standing, guard_emergency, mobilisable, defensible, food_t, water_m3, fuel_t, surface_line_m, surface_line_real_m, watchtowers) VALUES ('daebang', 5, 'common', 'Surface tracks become haul roads (push carts); rail bridges are gates that can be cut or joined; Neighbouring estates are taken in one by one, joining several estate strongholds', '지상 선로를 짐 나르는 길로(밀차), 철교는 끊고 잇는 문; 이웃 단지를 차례로 편입해 단지 성채 여럿을 잇는다', 16213, 4905, 'space', 1621, 'space', 1, 0, 3.0, 4905, 74, 156, 756, 1, 613.2, 4200, 1226.4, 241, 449, 2);
