INSERT INTO stronghold_stage (stronghold_id, stage, variant, terrain_works, terrain_works_ko, floor_m2, capacity, cap_by_max, living_capacity, cap_by, over_living, over_max, air_speed, overcrowd_limit, guard_standing, guard_emergency, mobilisable, defensible, food_t, water_m3, fuel_t, surface_line_m, surface_line_real_m, watchtowers) VALUES ('dobongsan', 2, 'common', '', '', 9964, 5176, 'space', 2846, 'space', 0, 0, 1.0, 5176, 18, 46, 336, 1, 60.5, 88, 302.4, 0, 0, 0);
INSERT INTO stronghold_stage (stronghold_id, stage, variant, terrain_works, terrain_works_ko, floor_m2, capacity, cap_by_max, living_capacity, cap_by, over_living, over_max, air_speed, overcrowd_limit, guard_standing, guard_emergency, mobilisable, defensible, food_t, water_m3, fuel_t, surface_line_m, surface_line_real_m, watchtowers) VALUES ('dobongsan', 3, 'common', 'Underpasses and passages below the tracks hardened into inner gates; Basements of low-rise buildings above the entrances used as hidden storerooms', '철길 아래 지하차도와 통로를 안쪽 문으로 굳힌다; 출입구 위 저층 건물의 지하실을 숨긴 창고로', 15399, 5176, 'space', 2799, 'space', 0, 0, 2.0, 5176, 50, 54, 336, 1, 121.0, 353, 604.8, 0, 0, 0);
INSERT INTO stronghold_stage (stronghold_id, stage, variant, terrain_works, terrain_works_ko, floor_m2, capacity, cap_by_max, living_capacity, cap_by, over_living, over_max, air_speed, overcrowd_limit, guard_standing, guard_emergency, mobilisable, defensible, food_t, water_m3, fuel_t, surface_line_m, surface_line_real_m, watchtowers) VALUES ('dobongsan', 4, 'common', 'The railway embankments and cuttings are ready-made ramparts. Barriers stand on top, the underpasses and spaces below the rail bridges are the gates, and the top of the embankment is the line of watchtowers; Only a few alley mouths stay open and the rest are blocked into a maze of dead ends; building walls are broken through to make inner passages', '철도 성토·절토가 이미 둑이다. 둑 위에 방벽, 지하차도와 철교 아래가 문, 성토 위가 망루 줄; 골목 입구 몇 곳만 열고 나머지는 막아 막다른 미로로, 건물 벽을 뚫어 안쪽 통로를 낸다', 15507, 366, 'water', 137, 'space', 1, 1, 2.5, 5206, 63, 134, 336, 1, 181.4, 1008, 907.2, 401, 628, 3);
INSERT INTO stronghold_stage (stronghold_id, stage, variant, terrain_works, terrain_works_ko, floor_m2, capacity, cap_by_max, living_capacity, cap_by, over_living, over_max, air_speed, overcrowd_limit, guard_standing, guard_emergency, mobilisable, defensible, food_t, water_m3, fuel_t, surface_line_m, surface_line_real_m, watchtowers) VALUES ('dobongsan', 5, 'common', 'Surface tracks become haul roads (push carts); rail bridges are gates that can be cut or joined; Passages through buildings are joined toward the neighbouring station, giving a route that never goes outside', '지상 선로를 짐 나르는 길로(밀차), 철교는 끊고 잇는 문; 건물 안 통로를 이어 이웃 역 방향으로 지상에 나가지 않는 길을 낸다', 20907, 366, 'water', 109, 'space', 1, 1, 3.0, 6749, 63, 134, 336, 1, 367.9, 2520, 1839.6, 401, 628, 3);
