INSERT INTO stronghold_stage (stronghold_id, stage, variant, terrain_works, terrain_works_ko, floor_m2, capacity, cap_by_max, living_capacity, cap_by, over_living, over_max, air_speed, overcrowd_limit, guard_standing, guard_emergency, mobilisable, defensible, food_t, water_m3, fuel_t, surface_line_m, surface_line_real_m, watchtowers) VALUES ('dunchon-dong', 3, 'common', 'Basements of low-rise buildings above the entrances used as hidden storerooms; A passage is cut from the estate''s underground car park to the station precinct', '출입구 위 저층 건물의 지하실을 숨긴 창고로; 단지 지하 주차장을 구내와 잇는 통로를 낸다', 5092, 1711, 'space', 925, 'space', 0, 0, 2.0, 1711, 46, 28, 177, 1, 42.5, 124, 85.0, 0, 0, 0);
INSERT INTO stronghold_stage (stronghold_id, stage, variant, terrain_works, terrain_works_ko, floor_m2, capacity, cap_by_max, living_capacity, cap_by, over_living, over_max, air_speed, overcrowd_limit, guard_standing, guard_emergency, mobilisable, defensible, food_t, water_m3, fuel_t, surface_line_m, surface_line_real_m, watchtowers) VALUES ('dunchon-dong', 4, 'arc', 'Only a few alley mouths stay open and the rest are blocked into a maze of dead ends; building walls are broken through to make inner passages; The apartment estate wall is the inner wall and the estate main gate is the gate. Yards between the blocks become vegetable plots and a firewood yard', '골목 입구 몇 곳만 열고 나머지는 막아 막다른 미로로, 건물 벽을 뚫어 안쪽 통로를 낸다; 아파트 단지 담장이 안뜰 성벽, 단지 정문이 성문, 동 사이 마당이 텃밭과 땔감 마당', 5092, 1711, 'space', 636, 'space', 0, 0, 2.5, 1711, 46, 28, 177, 1, 63.7, 354, 127.4, 0, 0, 0);
INSERT INTO stronghold_stage (stronghold_id, stage, variant, terrain_works, terrain_works_ko, floor_m2, capacity, cap_by_max, living_capacity, cap_by, over_living, over_max, air_speed, overcrowd_limit, guard_standing, guard_emergency, mobilisable, defensible, food_t, water_m3, fuel_t, surface_line_m, surface_line_real_m, watchtowers) VALUES ('dunchon-dong', 5, 'arc', 'Passages through buildings are joined toward the neighbouring station, giving a route that never goes outside; Neighbouring estates are taken in one by one, joining several estate strongholds', '건물 안 통로를 이어 이웃 역 방향으로 지상에 나가지 않는 길을 낸다; 이웃 단지를 차례로 편입해 단지 성채 여럿을 잇는다', 10492, 1966, 'water', 590, 'water', 0, 0, 3.0, 3254, 46, 28, 177, 1, 129.2, 885, 258.4, 0, 0, 0);
INSERT INTO stronghold_stage (stronghold_id, stage, variant, terrain_works, terrain_works_ko, floor_m2, capacity, cap_by_max, living_capacity, cap_by, over_living, over_max, air_speed, overcrowd_limit, guard_standing, guard_emergency, mobilisable, defensible, food_t, water_m3, fuel_t, surface_line_m, surface_line_real_m, watchtowers) VALUES ('dunchon-oryun', 1, 'common', '', '', 3056, 3492, 'space', 2037, 'space', 0, 0, 1.0, 3056, 9, 44, 600, 1, 16.8, 30, 33.6, 0, 0, 0);
INSERT INTO stronghold_stage (stronghold_id, stage, variant, terrain_works, terrain_works_ko, floor_m2, capacity, cap_by_max, living_capacity, cap_by, over_living, over_max, air_speed, overcrowd_limit, guard_standing, guard_emergency, mobilisable, defensible, food_t, water_m3, fuel_t, surface_line_m, surface_line_real_m, watchtowers) VALUES ('dunchon-oryun', 2, 'common', '', '', 6723, 3492, 'space', 1920, 'space', 1, 0, 1.0, 3492, 30, 60, 600, 1, 72.0, 105, 144.0, 0, 0, 0);
INSERT INTO stronghold_stage (stronghold_id, stage, variant, terrain_works, terrain_works_ko, floor_m2, capacity, cap_by_max, living_capacity, cap_by, over_living, over_max, air_speed, overcrowd_limit, guard_standing, guard_emergency, mobilisable, defensible, food_t, water_m3, fuel_t, surface_line_m, surface_line_real_m, watchtowers) VALUES ('dunchon-oryun', 3, 'common', 'Air intakes placed upslope (upwind) and exhaust sent down into the valley; For a shallow station, pairing with a deep neighbour comes first', '급기구를 비탈 위쪽(공기 상류)에 두고 배기는 골짜기 아래로; 얕은 역이면 깊은 이웃 역과 짝을 맺는 것이 먼저', 10390, 3492, 'space', 1889, 'space', 1, 0, 2.0, 3492, 50, 60, 600, 1, 144.0, 420, 288.0, 0, 0, 0);
INSERT INTO stronghold_stage (stronghold_id, stage, variant, terrain_works, terrain_works_ko, floor_m2, capacity, cap_by_max, living_capacity, cap_by, over_living, over_max, air_speed, overcrowd_limit, guard_standing, guard_emergency, mobilisable, defensible, food_t, water_m3, fuel_t, surface_line_m, surface_line_real_m, watchtowers) VALUES ('dunchon-oryun', 4, 'arc', 'The line runs along the ridge and slopes. The tallest building or rocky knoll is the watchtower, the slope itself is the cleared strip, and grilles close the sewer outlets on the valley side; With no terrain to lean on, banks are raised and ditches dug. Wide roads are kept as the cleared strip (field of fire), with watchtowers at the corners', '능선과 비탈을 따라 두른다. 가장 높은 건물·바위 언덕이 망루, 비탈 자체가 비워 둔 띠, 골짜기 쪽 하수 수구에 창살; 기댈 지형이 없어 둑을 쌓고 해자를 판다. 넓은 길은 비워 둔 띠(사격 띠)로, 모서리에 망루', 10390, 3492, 'space', 1298, 'space', 1, 0, 2.5, 3492, 50, 60, 600, 1, 216.0, 1200, 432.0, 0, 0, 0);
INSERT INTO stronghold_stage (stronghold_id, stage, variant, terrain_works, terrain_works_ko, floor_m2, capacity, cap_by_max, living_capacity, cap_by, over_living, over_max, air_speed, overcrowd_limit, guard_standing, guard_emergency, mobilisable, defensible, food_t, water_m3, fuel_t, surface_line_m, surface_line_real_m, watchtowers) VALUES ('dunchon-oryun', 5, 'arc', 'Signal points on the ridge keep a line of sight to the neighbouring stations; A shallow station cannot stand alone. It exists only as a pair with a deep neighbour', '능선 위 신호 자리로 이웃 역과 보이는 줄을 잇는다; 얕은 역은 혼자 서지 못한다. 깊은 이웃 역과의 짝으로만 성립', 15790, 5035, 'space', 1579, 'space', 1, 0, 3.0, 5035, 50, 60, 600, 1, 438.0, 3000, 876.0, 0, 0, 0);
