INSERT INTO stronghold_stage (stronghold_id, stage, variant, terrain_works, terrain_works_ko, floor_m2, capacity, cap_by_max, living_capacity, cap_by, over_living, over_max, air_speed, overcrowd_limit, guard_standing, guard_emergency, mobilisable, defensible, food_t, water_m3, fuel_t, surface_line_m, surface_line_real_m, watchtowers) VALUES ('myeongdong', 3, 'common', 'Air intakes placed upslope (upwind) and exhaust sent down into the valley; Basements of low-rise buildings above the entrances used as hidden storerooms', '급기구를 비탈 위쪽(공기 상류)에 두고 배기는 골짜기 아래로; 출입구 위 저층 건물의 지하실을 숨긴 창고로', 1850, 621, 'space', 336, 'space', 1, 1, 2.0, 621, 51, 53, 368, 1, 132.5, 386, 353.3, 0, 0, 0);
INSERT INTO stronghold_stage (stronghold_id, stage, variant, terrain_works, terrain_works_ko, floor_m2, capacity, cap_by_max, living_capacity, cap_by, over_living, over_max, air_speed, overcrowd_limit, guard_standing, guard_emergency, mobilisable, defensible, food_t, water_m3, fuel_t, surface_line_m, surface_line_real_m, watchtowers) VALUES ('myeongdong', 4, 'common', 'The line runs along the ridge and slopes. The tallest building or rocky knoll is the watchtower, the slope itself is the cleared strip, and grilles close the sewer outlets on the valley side; Only a few alley mouths stay open and the rest are blocked into a maze of dead ends; building walls are broken through to make inner passages', '능선과 비탈을 따라 두른다. 가장 높은 건물·바위 언덕이 망루, 비탈 자체가 비워 둔 띠, 골짜기 쪽 하수 수구에 창살; 골목 입구 몇 곳만 열고 나머지는 막아 막다른 미로로, 건물 벽을 뚫어 안쪽 통로를 낸다', 3015, 954, 'space', 376, 'space', 1, 1, 2.5, 954, 56, 83, 368, 1, 198.7, 1104, 529.9, 153, 214, 1);
INSERT INTO stronghold_stage (stronghold_id, stage, variant, terrain_works, terrain_works_ko, floor_m2, capacity, cap_by_max, living_capacity, cap_by, over_living, over_max, air_speed, overcrowd_limit, guard_standing, guard_emergency, mobilisable, defensible, food_t, water_m3, fuel_t, surface_line_m, surface_line_real_m, watchtowers) VALUES ('myeongdong', 5, 'common', 'Signal points on the ridge keep a line of sight to the neighbouring stations; Passages through buildings are joined toward the neighbouring station, giving a route that never goes outside', '능선 위 신호 자리로 이웃 역과 보이는 줄을 잇는다; 건물 안 통로를 이어 이웃 역 방향으로 지상에 나가지 않는 길을 낸다', 8415, 2497, 'space', 841, 'space', 1, 0, 3.0, 2497, 56, 83, 368, 1, 403.0, 2760, 1074.6, 153, 214, 1);
