INSERT INTO stronghold_stage (stronghold_id, stage, variant, terrain_works, terrain_works_ko, floor_m2, capacity, cap_by_max, living_capacity, cap_by, over_living, over_max, air_speed, overcrowd_limit, guard_standing, guard_emergency, mobilisable, defensible, food_t, water_m3, fuel_t, surface_line_m, surface_line_real_m, watchtowers) VALUES ('beotigogae', 4, 'common', 'The line runs along the ridge and slopes. The tallest building or rocky knoll is the watchtower, the slope itself is the cleared strip, and grilles close the sewer outlets on the valley side; The apartment estate wall is the inner wall and the estate main gate is the gate. Yards between the blocks become vegetable plots and a firewood yard', '능선과 비탈을 따라 두른다. 가장 높은 건물·바위 언덕이 망루, 비탈 자체가 비워 둔 띠, 골짜기 쪽 하수 수구에 창살; 아파트 단지 담장이 안뜰 성벽, 단지 정문이 성문, 동 사이 마당이 텃밭과 땔감 마당', 6426, 2144, 'space', 803, 'space', 1, 0, 2.5, 2144, 64, 150, 420, 1, 226.8, 1260, 264.6, 418, 454, 3);
INSERT INTO stronghold_stage (stronghold_id, stage, variant, terrain_works, terrain_works_ko, floor_m2, capacity, cap_by_max, living_capacity, cap_by, over_living, over_max, air_speed, overcrowd_limit, guard_standing, guard_emergency, mobilisable, defensible, food_t, water_m3, fuel_t, surface_line_m, surface_line_real_m, watchtowers) VALUES ('beotigogae', 5, 'common', 'Signal points on the ridge keep a line of sight to the neighbouring stations; Neighbouring estates are taken in one by one, joining several estate strongholds', '능선 위 신호 자리로 이웃 역과 보이는 줄을 잇는다; 이웃 단지를 차례로 편입해 단지 성채 여럿을 잇는다', 11826, 3687, 'space', 1182, 'space', 1, 0, 3.0, 3687, 64, 150, 420, 1, 459.9, 3150, 536.5, 418, 454, 3);
