INSERT INTO stronghold_stage (stronghold_id, stage, variant, terrain_works, terrain_works_ko, floor_m2, capacity, cap_by_max, living_capacity, cap_by, over_living, over_max, air_speed, overcrowd_limit, guard_standing, guard_emergency, mobilisable, defensible, food_t, water_m3, fuel_t, surface_line_m, surface_line_real_m, watchtowers) VALUES ('boramae', 3, 'common', 'Basements of low-rise buildings above the entrances used as hidden storerooms; For a shallow station, pairing with a deep neighbour comes first', '출입구 위 저층 건물의 지하실을 숨긴 창고로; 얕은 역이면 깊은 이웃 역과 짝을 맺는 것이 먼저', 9967, 3350, 'space', 1812, 'space', 0, 0, 2.0, 3350, 76, 60, 486, 1, 129.6, 378, 259.2, 0, 0, 0);
INSERT INTO stronghold_stage (stronghold_id, stage, variant, terrain_works, terrain_works_ko, floor_m2, capacity, cap_by_max, living_capacity, cap_by, over_living, over_max, air_speed, overcrowd_limit, guard_standing, guard_emergency, mobilisable, defensible, food_t, water_m3, fuel_t, surface_line_m, surface_line_real_m, watchtowers) VALUES ('boramae', 4, 'common', 'Only a few alley mouths stay open and the rest are blocked into a maze of dead ends; building walls are broken through to make inner passages; With no terrain to lean on, banks are raised and ditches dug. Wide roads are kept as the cleared strip (field of fire), with watchtowers at the corners', '골목 입구 몇 곳만 열고 나머지는 막아 막다른 미로로, 건물 벽을 뚫어 안쪽 통로를 낸다; 기댈 지형이 없어 둑을 쌓고 해자를 판다. 넓은 길은 비워 둔 띠(사격 띠)로, 모서리에 망루', 10318, 3450, 'space', 1289, 'space', 1, 0, 2.5, 3450, 80, 109, 486, 1, 194.4, 1080, 388.8, 162, 274, 1);
INSERT INTO stronghold_stage (stronghold_id, stage, variant, terrain_works, terrain_works_ko, floor_m2, capacity, cap_by_max, living_capacity, cap_by, over_living, over_max, air_speed, overcrowd_limit, guard_standing, guard_emergency, mobilisable, defensible, food_t, water_m3, fuel_t, surface_line_m, surface_line_real_m, watchtowers) VALUES ('boramae', 5, 'common', 'Passages through buildings are joined toward the neighbouring station, giving a route that never goes outside; A shallow station cannot stand alone. It exists only as a pair with a deep neighbour', '건물 안 통로를 이어 이웃 역 방향으로 지상에 나가지 않는 길을 낸다; 얕은 역은 혼자 서지 못한다. 깊은 이웃 역과의 짝으로만 성립', 21118, 6536, 'space', 2032, 'water', 0, 0, 3.0, 6536, 80, 109, 486, 1, 394.2, 2700, 788.4, 162, 274, 1);
