INSERT INTO stronghold_stage (stronghold_id, stage, variant, terrain_works, terrain_works_ko, floor_m2, capacity, cap_by_max, living_capacity, cap_by, over_living, over_max, air_speed, overcrowd_limit, guard_standing, guard_emergency, mobilisable, defensible, food_t, water_m3, fuel_t, surface_line_m, surface_line_real_m, watchtowers) VALUES ('bongcheon', 3, 'common', 'Basements of low-rise buildings above the entrances used as hidden storerooms; Air intakes placed upslope (upwind) and exhaust sent down into the valley', '출입구 위 저층 건물의 지하실을 숨긴 창고로; 급기구를 비탈 위쪽(공기 상류)에 두고 배기는 골짜기 아래로', 6514, 600, 'water', 300, 'water', 1, 0, 2.0, 2189, 46, 28, 162, 1, 43.2, 126, 158.4, 0, 0, 0);
INSERT INTO stronghold_stage (stronghold_id, stage, variant, terrain_works, terrain_works_ko, floor_m2, capacity, cap_by_max, living_capacity, cap_by, over_living, over_max, air_speed, overcrowd_limit, guard_standing, guard_emergency, mobilisable, defensible, food_t, water_m3, fuel_t, surface_line_m, surface_line_real_m, watchtowers) VALUES ('bongcheon', 4, 'common', 'Only a few alley mouths stay open and the rest are blocked into a maze of dead ends; building walls are broken through to make inner passages; The line runs along the ridge and slopes. The tallest building or rocky knoll is the watchtower, the slope itself is the cleared strip, and grilles close the sewer outlets on the valley side', '골목 입구 몇 곳만 열고 나머지는 막아 막다른 미로로, 건물 벽을 뚫어 안쪽 통로를 낸다; 능선과 비탈을 따라 두른다. 가장 높은 건물·바위 언덕이 망루, 비탈 자체가 비워 둔 띠, 골짜기 쪽 하수 수구에 창살', 6954, 1839, 'water', 689, 'water', 0, 0, 2.5, 2315, 54, 104, 162, 1, 64.8, 360, 237.6, 254, 324, 2);
INSERT INTO stronghold_stage (stronghold_id, stage, variant, terrain_works, terrain_works_ko, floor_m2, capacity, cap_by_max, living_capacity, cap_by, over_living, over_max, air_speed, overcrowd_limit, guard_standing, guard_emergency, mobilisable, defensible, food_t, water_m3, fuel_t, surface_line_m, surface_line_real_m, watchtowers) VALUES ('bongcheon', 5, 'common', 'Passages through buildings are joined toward the neighbouring station, giving a route that never goes outside; Signal points on the ridge keep a line of sight to the neighbouring stations', '건물 안 통로를 이어 이웃 역 방향으로 지상에 나가지 않는 길을 낸다; 능선 위 신호 자리로 이웃 역과 보이는 줄을 잇는다', 12354, 1839, 'water', 551, 'water', 1, 0, 3.0, 3858, 54, 104, 162, 1, 131.4, 900, 481.8, 254, 324, 2);
INSERT INTO stronghold_stage (stronghold_id, stage, variant, terrain_works, terrain_works_ko, floor_m2, capacity, cap_by_max, living_capacity, cap_by, over_living, over_max, air_speed, overcrowd_limit, guard_standing, guard_emergency, mobilisable, defensible, food_t, water_m3, fuel_t, surface_line_m, surface_line_real_m, watchtowers) VALUES ('bonghwasan', 1, 'common', '', '', 2830, 1050, 'water', 1575, 'water', 0, 0, 1.0, 2830, 9, 25, 210, 1, 8.8, 16, 32.3, 0, 0, 0);
INSERT INTO stronghold_stage (stronghold_id, stage, variant, terrain_works, terrain_works_ko, floor_m2, capacity, cap_by_max, living_capacity, cap_by, over_living, over_max, air_speed, overcrowd_limit, guard_standing, guard_emergency, mobilisable, defensible, food_t, water_m3, fuel_t, surface_line_m, surface_line_real_m, watchtowers) VALUES ('bonghwasan', 2, 'common', '', '', 6227, 1050, 'water', 1050, 'water', 0, 0, 1.0, 3234, 24, 33, 210, 1, 37.8, 55, 138.6, 0, 0, 0);
INSERT INTO stronghold_stage (stronghold_id, stage, variant, terrain_works, terrain_works_ko, floor_m2, capacity, cap_by_max, living_capacity, cap_by, over_living, over_max, air_speed, overcrowd_limit, guard_standing, guard_emergency, mobilisable, defensible, food_t, water_m3, fuel_t, surface_line_m, surface_line_real_m, watchtowers) VALUES ('bonghwasan', 3, 'common', 'A passage is cut from the estate''s underground car park to the station precinct; Basements of adjoining high-rise buildings used as precinct storerooms', '단지 지하 주차장을 구내와 잇는 통로를 낸다; 붙은 고층 건물의 지하층을 구내 창고로', 9624, 1050, 'water', 525, 'water', 1, 0, 2.0, 3234, 42, 37, 210, 1, 75.6, 220, 277.2, 0, 0, 0);
INSERT INTO stronghold_stage (stronghold_id, stage, variant, terrain_works, terrain_works_ko, floor_m2, capacity, cap_by_max, living_capacity, cap_by, over_living, over_max, air_speed, overcrowd_limit, guard_standing, guard_emergency, mobilisable, defensible, food_t, water_m3, fuel_t, surface_line_m, surface_line_real_m, watchtowers) VALUES ('bonghwasan', 4, 'common', 'The apartment estate wall is the inner wall and the estate main gate is the gate. Yards between the blocks become vegetable plots and a firewood yard; The outer walls of the high-rise buildings form the wall. Ground and first-floor windows are blocked, the rooftops are watchtowers, and only the gaps between buildings get barriers', '아파트 단지 담장이 안뜰 성벽, 단지 정문이 성문, 동 사이 마당이 텃밭과 땔감 마당; 고층 건물의 외벽 줄이 성벽, 1~2층 창을 막고 고층 꼭대기가 망루, 건물 사이 틈만 방벽', 10174, 1534, 'water', 575, 'water', 1, 0, 2.5, 3391, 51, 85, 210, 1, 113.4, 630, 415.8, 239, 288, 2);
INSERT INTO stronghold_stage (stronghold_id, stage, variant, terrain_works, terrain_works_ko, floor_m2, capacity, cap_by_max, living_capacity, cap_by, over_living, over_max, air_speed, overcrowd_limit, guard_standing, guard_emergency, mobilisable, defensible, food_t, water_m3, fuel_t, surface_line_m, surface_line_real_m, watchtowers) VALUES ('bonghwasan', 5, 'common', 'Neighbouring estates are taken in one by one, joining several estate strongholds; High-rise buildings are linked through underground car parks and connecting passages, so people move between them without going outside', '이웃 단지를 차례로 편입해 단지 성채 여럿을 잇는다; 고층 건물끼리 지하 주차장·연결 통로로 이어 지상에 나가지 않고 오간다', 15574, 1534, 'water', 460, 'water', 1, 0, 3.0, 4934, 51, 85, 210, 1, 229.9, 1575, 843.1, 239, 288, 2);
