INSERT INTO stronghold_stage (stronghold_id, stage, variant, terrain_works, terrain_works_ko, floor_m2, capacity, cap_by_max, living_capacity, cap_by, over_living, over_max, air_speed, overcrowd_limit, guard_standing, guard_emergency, mobilisable, defensible, food_t, water_m3, fuel_t, surface_line_m, surface_line_real_m, watchtowers) VALUES ('buramsan', 5, 'common', 'Passages through buildings are joined toward the neighbouring station, giving a route that never goes outside; Signal points on the ridge keep a line of sight to the neighbouring stations', '건물 안 통로를 이어 이웃 역 방향으로 지상에 나가지 않는 길을 낸다; 능선 위 신호 자리로 이웃 역과 보이는 줄을 잇는다', 5796, 1810, 'space', 579, 'space', 1, 0, 3.0, 1810, 51, 106, 236, 1, 258.4, 1770, 689.1, 353, 578, 2);
