INSERT INTO stronghold_stage (stronghold_id, stage, variant, terrain_works, terrain_works_ko, floor_m2, capacity, cap_by_max, living_capacity, cap_by, over_living, over_max, air_speed, overcrowd_limit, guard_standing, guard_emergency, mobilisable, defensible, food_t, water_m3, fuel_t, surface_line_m, surface_line_real_m, watchtowers) VALUES ('samseong-jungang', 2, 'common', '', '', 5499, 2266, 'water', 1571, 'space', 0, 0, 1.0, 2856, 26, 30, 204, 1, 24.5, 36, 49.0, 0, 0, 0);
INSERT INTO stronghold_stage (stronghold_id, stage, variant, terrain_works, terrain_works_ko, floor_m2, capacity, cap_by_max, living_capacity, cap_by, over_living, over_max, air_speed, overcrowd_limit, guard_standing, guard_emergency, mobilisable, defensible, food_t, water_m3, fuel_t, surface_line_m, surface_line_real_m, watchtowers) VALUES ('samseong-jungang', 3, 'common', 'A passage is cut from the estate''s underground car park to the station precinct; Basements of low-rise buildings above the entrances used as hidden storerooms', '단지 지하 주차장을 구내와 잇는 통로를 낸다; 출입구 위 저층 건물의 지하실을 숨긴 창고로', 8499, 2266, 'water', 1133, 'water', 0, 0, 2.0, 2856, 54, 38, 204, 1, 49.0, 143, 97.9, 0, 0, 0);
INSERT INTO stronghold_stage (stronghold_id, stage, variant, terrain_works, terrain_works_ko, floor_m2, capacity, cap_by_max, living_capacity, cap_by, over_living, over_max, air_speed, overcrowd_limit, guard_standing, guard_emergency, mobilisable, defensible, food_t, water_m3, fuel_t, surface_line_m, surface_line_real_m, watchtowers) VALUES ('samseong-jungang', 4, 'arc', 'The apartment estate wall is the inner wall and the estate main gate is the gate. Yards between the blocks become vegetable plots and a firewood yard; Only a few alley mouths stay open and the rest are blocked into a maze of dead ends; building walls are broken through to make inner passages', '아파트 단지 담장이 안뜰 성벽, 단지 정문이 성문, 동 사이 마당이 텃밭과 땔감 마당; 골목 입구 몇 곳만 열고 나머지는 막아 막다른 미로로, 건물 벽을 뚫어 안쪽 통로를 낸다', 8499, 2266, 'water', 850, 'water', 0, 0, 2.5, 2856, 54, 38, 204, 1, 73.4, 408, 146.9, 0, 0, 0);
INSERT INTO stronghold_stage (stronghold_id, stage, variant, terrain_works, terrain_works_ko, floor_m2, capacity, cap_by_max, living_capacity, cap_by, over_living, over_max, air_speed, overcrowd_limit, guard_standing, guard_emergency, mobilisable, defensible, food_t, water_m3, fuel_t, surface_line_m, surface_line_real_m, watchtowers) VALUES ('samseong-jungang', 5, 'arc', 'Neighbouring estates are taken in one by one, joining several estate strongholds; Passages through buildings are joined toward the neighbouring station, giving a route that never goes outside', '이웃 단지를 차례로 편입해 단지 성채 여럿을 잇는다; 건물 안 통로를 이어 이웃 역 방향으로 지상에 나가지 않는 길을 낸다', 13899, 2266, 'water', 680, 'water', 0, 0, 3.0, 4399, 54, 38, 204, 1, 148.9, 1020, 297.8, 0, 0, 0);
INSERT INTO stronghold_stage (stronghold_id, stage, variant, terrain_works, terrain_works_ko, floor_m2, capacity, cap_by_max, living_capacity, cap_by, over_living, over_max, air_speed, overcrowd_limit, guard_standing, guard_emergency, mobilisable, defensible, food_t, water_m3, fuel_t, surface_line_m, surface_line_real_m, watchtowers) VALUES ('samyang', 1, 'common', '', '', 1015, 1160, 'space', 676, 'space', 1, 0, 1.0, 1015, 9, 21, 168, 1, 7.1, 13, 18.8, 0, 0, 0);
INSERT INTO stronghold_stage (stronghold_id, stage, variant, terrain_works, terrain_works_ko, floor_m2, capacity, cap_by_max, living_capacity, cap_by, over_living, over_max, air_speed, overcrowd_limit, guard_standing, guard_emergency, mobilisable, defensible, food_t, water_m3, fuel_t, surface_line_m, surface_line_real_m, watchtowers) VALUES ('samyang', 2, 'common', '', '', 2233, 1160, 'space', 638, 'space', 1, 0, 1.0, 1160, 24, 29, 168, 1, 30.2, 44, 80.6, 0, 0, 0);
INSERT INTO stronghold_stage (stronghold_id, stage, variant, terrain_works, terrain_works_ko, floor_m2, capacity, cap_by_max, living_capacity, cap_by, over_living, over_max, air_speed, overcrowd_limit, guard_standing, guard_emergency, mobilisable, defensible, food_t, water_m3, fuel_t, surface_line_m, surface_line_real_m, watchtowers) VALUES ('samyang', 3, 'common', 'Basements of low-rise buildings above the entrances used as hidden storerooms; Air intakes placed upslope (upwind) and exhaust sent down into the valley', '출입구 위 저층 건물의 지하실을 숨긴 창고로; 급기구를 비탈 위쪽(공기 상류)에 두고 배기는 골짜기 아래로', 3451, 1160, 'space', 627, 'space', 1, 0, 2.0, 1160, 46, 29, 168, 1, 60.5, 176, 161.3, 0, 0, 0);
INSERT INTO stronghold_stage (stronghold_id, stage, variant, terrain_works, terrain_works_ko, floor_m2, capacity, cap_by_max, living_capacity, cap_by, over_living, over_max, air_speed, overcrowd_limit, guard_standing, guard_emergency, mobilisable, defensible, food_t, water_m3, fuel_t, surface_line_m, surface_line_real_m, watchtowers) VALUES ('samyang', 4, 'common', 'Only a few alley mouths stay open and the rest are blocked into a maze of dead ends; building walls are broken through to make inner passages; The line runs along the ridge and slopes. The tallest building or rocky knoll is the watchtower, the slope itself is the cleared strip, and grilles close the sewer outlets on the valley side', '골목 입구 몇 곳만 열고 나머지는 막아 막다른 미로로, 건물 벽을 뚫어 안쪽 통로를 낸다; 능선과 비탈을 따라 두른다. 가장 높은 건물·바위 언덕이 망루, 비탈 자체가 비워 둔 띠, 골짜기 쪽 하수 수구에 창살', 4582, 1483, 'space', 572, 'space', 1, 0, 2.5, 1483, 51, 63, 168, 1, 90.7, 504, 241.9, 170, 275, 1);
INSERT INTO stronghold_stage (stronghold_id, stage, variant, terrain_works, terrain_works_ko, floor_m2, capacity, cap_by_max, living_capacity, cap_by, over_living, over_max, air_speed, overcrowd_limit, guard_standing, guard_emergency, mobilisable, defensible, food_t, water_m3, fuel_t, surface_line_m, surface_line_real_m, watchtowers) VALUES ('samyang', 5, 'common', 'Passages through buildings are joined toward the neighbouring station, giving a route that never goes outside; Signal points on the ridge keep a line of sight to the neighbouring stations', '건물 안 통로를 이어 이웃 역 방향으로 지상에 나가지 않는 길을 낸다; 능선 위 신호 자리로 이웃 역과 보이는 줄을 잇는다', 9982, 2450, 'water', 735, 'water', 1, 0, 3.0, 3026, 51, 63, 168, 1, 184.0, 1260, 490.6, 170, 275, 1);
