INSERT INTO stronghold_stage (stronghold_id, stage, variant, terrain_works, terrain_works_ko, floor_m2, capacity, cap_by_max, living_capacity, cap_by, over_living, over_max, air_speed, overcrowd_limit, guard_standing, guard_emergency, mobilisable, defensible, food_t, water_m3, fuel_t, surface_line_m, surface_line_real_m, watchtowers) VALUES ('sangdo', 4, 'common', 'The apartment estate wall is the inner wall and the estate main gate is the gate. Yards between the blocks become vegetable plots and a firewood yard; Only a few alley mouths stay open and the rest are blocked into a maze of dead ends; building walls are broken through to make inner passages', '아파트 단지 담장이 안뜰 성벽, 단지 정문이 성문, 동 사이 마당이 텃밭과 땔감 마당; 골목 입구 몇 곳만 열고 나머지는 막아 막다른 미로로, 건물 벽을 뚫어 안쪽 통로를 낸다', 8352, 2702, 'space', 1043, 'space', 1, 0, 2.5, 2702, 58, 117, 637, 1, 254.9, 1416, 509.8, 179, 295, 1);
INSERT INTO stronghold_stage (stronghold_id, stage, variant, terrain_works, terrain_works_ko, floor_m2, capacity, cap_by_max, living_capacity, cap_by, over_living, over_max, air_speed, overcrowd_limit, guard_standing, guard_emergency, mobilisable, defensible, food_t, water_m3, fuel_t, surface_line_m, surface_line_real_m, watchtowers) VALUES ('sangdo', 5, 'common', 'Neighbouring estates are taken in one by one, joining several estate strongholds; Passages through buildings are joined toward the neighbouring station, giving a route that never goes outside', '이웃 단지를 차례로 편입해 단지 성채 여럿을 잇는다; 건물 안 통로를 이어 이웃 역 방향으로 지상에 나가지 않는 길을 낸다', 13752, 4245, 'space', 1375, 'space', 1, 0, 3.0, 4245, 58, 117, 637, 1, 516.8, 3540, 1033.7, 179, 295, 1);
