INSERT INTO stronghold_stage (stronghold_id, stage, variant, terrain_works, terrain_works_ko, floor_m2, capacity, cap_by_max, living_capacity, cap_by, over_living, over_max, air_speed, overcrowd_limit, guard_standing, guard_emergency, mobilisable, defensible, food_t, water_m3, fuel_t, surface_line_m, surface_line_real_m, watchtowers) VALUES ('saetgang', 3, 'common', 'Basements of adjoining high-rise buildings used as precinct storerooms; For a shallow station, pairing with a deep neighbour comes first', '붙은 고층 건물의 지하층을 구내 창고로; 얕은 역이면 깊은 이웃 역과 짝을 맺는 것이 먼저', 17820, 5990, 'space', 3240, 'space', 0, 0, 2.0, 5990, 66, 91, 799, 1, 213.1, 622, 426.2, 0, 0, 0);
