INSERT INTO stronghold_stage (stronghold_id, stage, variant, terrain_works, terrain_works_ko, floor_m2, capacity, cap_by_max, living_capacity, cap_by, over_living, over_max, air_speed, overcrowd_limit, guard_standing, guard_emergency, mobilisable, defensible, food_t, water_m3, fuel_t, surface_line_m, surface_line_real_m, watchtowers) VALUES ('seoul-national-university-venture-town', 3, 'common', 'Basements of low-rise buildings above the entrances used as hidden storerooms; Sumps and drainage pumps in the last-stand zone, grilles at the ends of the drains on the river side', '출입구 위 저층 건물의 지하실을 숨긴 창고로; 집수정과 배수펌프를 최후 구역에, 하천 쪽 배수 관로 끝에 창살', 2766, 929, 'space', 502, 'space', 1, 1, 2.0, 929, 42, 38, 346, 1, 92.2, 269, 184.3, 0, 0, 0);
INSERT INTO stronghold_stage (stronghold_id, stage, variant, terrain_works, terrain_works_ko, floor_m2, capacity, cap_by_max, living_capacity, cap_by, over_living, over_max, air_speed, overcrowd_limit, guard_standing, guard_emergency, mobilisable, defensible, food_t, water_m3, fuel_t, surface_line_m, surface_line_real_m, watchtowers) VALUES ('seoul-national-university-venture-town', 4, 'common', 'Only a few alley mouths stay open and the rest are blocked into a maze of dead ends; building walls are broken through to make inner passages; The river is the moat on one side. The embankment is the wall, bridges and sewer outlets are the gates. A frozen river becomes a road in winter, so there is an ice watch post', '골목 입구 몇 곳만 열고 나머지는 막아 막다른 미로로, 건물 벽을 뚫어 안쪽 통로를 낸다; 하천 한쪽이 해자다. 둑이 성벽, 다리와 하수 출구가 문. 겨울에 언 하천은 길이 되므로 얼음 감시 초소', 5724, 1774, 'space', 715, 'space', 1, 0, 2.5, 1774, 50, 153, 346, 1, 138.2, 768, 276.5, 384, 686, 2);
INSERT INTO stronghold_stage (stronghold_id, stage, variant, terrain_works, terrain_works_ko, floor_m2, capacity, cap_by_max, living_capacity, cap_by, over_living, over_max, air_speed, overcrowd_limit, guard_standing, guard_emergency, mobilisable, defensible, food_t, water_m3, fuel_t, surface_line_m, surface_line_real_m, watchtowers) VALUES ('seoul-national-university-venture-town', 5, 'common', 'Passages through buildings are joined toward the neighbouring station, giving a route that never goes outside; One bridge is blocked and one is held as the crossing', '건물 안 통로를 이어 이웃 역 방향으로 지상에 나가지 않는 길을 낸다; 다리 하나를 막고 하나는 지켜 건너는 길로 쓴다', 11124, 3317, 'space', 1112, 'space', 1, 0, 3.0, 3317, 50, 153, 346, 1, 280.3, 1920, 560.6, 384, 686, 2);
INSERT INTO stronghold_stage (stronghold_id, stage, variant, terrain_works, terrain_works_ko, floor_m2, capacity, cap_by_max, living_capacity, cap_by, over_living, over_max, air_speed, overcrowd_limit, guard_standing, guard_emergency, mobilisable, defensible, food_t, water_m3, fuel_t, surface_line_m, surface_line_real_m, watchtowers) VALUES ('seoul-national-university-entrance', 1, 'common', '', '', 2096, 1940, 'water', 1397, 'space', 0, 0, 1.0, 2095, 15, 23, 262, 1, 8.1, 15, 21.7, 0, 0, 0);
INSERT INTO stronghold_stage (stronghold_id, stage, variant, terrain_works, terrain_works_ko, floor_m2, capacity, cap_by_max, living_capacity, cap_by, over_living, over_max, air_speed, overcrowd_limit, guard_standing, guard_emergency, mobilisable, defensible, food_t, water_m3, fuel_t, surface_line_m, surface_line_real_m, watchtowers) VALUES ('seoul-national-university-entrance', 2, 'common', '', '', 4610, 1940, 'water', 1317, 'space', 0, 0, 1.0, 2394, 28, 31, 262, 1, 34.9, 51, 93.1, 0, 0, 0);
INSERT INTO stronghold_stage (stronghold_id, stage, variant, terrain_works, terrain_works_ko, floor_m2, capacity, cap_by_max, living_capacity, cap_by, over_living, over_max, air_speed, overcrowd_limit, guard_standing, guard_emergency, mobilisable, defensible, food_t, water_m3, fuel_t, surface_line_m, surface_line_real_m, watchtowers) VALUES ('seoul-national-university-entrance', 3, 'common', 'Basements of low-rise buildings above the entrances used as hidden storerooms; Basements of adjoining high-rise buildings used as precinct storerooms', '출입구 위 저층 건물의 지하실을 숨긴 창고로; 붙은 고층 건물의 지하층을 구내 창고로', 7125, 1940, 'water', 970, 'water', 0, 0, 2.0, 2394, 52, 35, 262, 1, 69.8, 204, 186.2, 0, 0, 0);
INSERT INTO stronghold_stage (stronghold_id, stage, variant, terrain_works, terrain_works_ko, floor_m2, capacity, cap_by_max, living_capacity, cap_by, over_living, over_max, air_speed, overcrowd_limit, guard_standing, guard_emergency, mobilisable, defensible, food_t, water_m3, fuel_t, surface_line_m, surface_line_real_m, watchtowers) VALUES ('seoul-national-university-entrance', 4, 'common', 'Only a few alley mouths stay open and the rest are blocked into a maze of dead ends; building walls are broken through to make inner passages; The outer walls of the high-rise buildings form the wall. Ground and first-floor windows are blocked, the rooftops are watchtowers, and only the gaps between buildings get barriers', '골목 입구 몇 곳만 열고 나머지는 막아 막다른 미로로, 건물 벽을 뚫어 안쪽 통로를 낸다; 고층 건물의 외벽 줄이 성벽, 1~2층 창을 막고 고층 꼭대기가 망루, 건물 사이 틈만 방벽', 8835, 2876, 'water', 1078, 'water', 0, 0, 2.5, 2883, 56, 95, 262, 1, 104.8, 582, 279.4, 199, 273, 1);
INSERT INTO stronghold_stage (stronghold_id, stage, variant, terrain_works, terrain_works_ko, floor_m2, capacity, cap_by_max, living_capacity, cap_by, over_living, over_max, air_speed, overcrowd_limit, guard_standing, guard_emergency, mobilisable, defensible, food_t, water_m3, fuel_t, surface_line_m, surface_line_real_m, watchtowers) VALUES ('seoul-national-university-entrance', 5, 'common', 'Passages through buildings are joined toward the neighbouring station, giving a route that never goes outside; High-rise buildings are linked through underground car parks and connecting passages, so people move between them without going outside', '건물 안 통로를 이어 이웃 역 방향으로 지상에 나가지 않는 길을 낸다; 고층 건물끼리 지하 주차장·연결 통로로 이어 지상에 나가지 않고 오간다', 14235, 2876, 'water', 862, 'water', 1, 0, 3.0, 4426, 56, 95, 262, 1, 212.4, 1455, 566.5, 199, 273, 1);
INSERT INTO stronghold_stage (stronghold_id, stage, variant, terrain_works, terrain_works_ko, floor_m2, capacity, cap_by_max, living_capacity, cap_by, over_living, over_max, air_speed, overcrowd_limit, guard_standing, guard_emergency, mobilisable, defensible, food_t, water_m3, fuel_t, surface_line_m, surface_line_real_m, watchtowers) VALUES ('seoulsup', 1, 'common', '', '', 2963, 3386, 'space', 1975, 'space', 0, 0, 1.0, 2962, 9, 32, 282, 1, 11.8, 21, 23.7, 0, 0, 0);
