INSERT INTO stronghold_stage (stronghold_id, stage, variant, terrain_works, terrain_works_ko, floor_m2, capacity, cap_by_max, living_capacity, cap_by, over_living, over_max, air_speed, overcrowd_limit, guard_standing, guard_emergency, mobilisable, defensible, food_t, water_m3, fuel_t, surface_line_m, surface_line_real_m, watchtowers) VALUES ('seoul-station', 3, 'common', 'Air intakes placed upslope (upwind) and exhaust sent down into the valley; Underpasses and passages below the tracks hardened into inner gates', '급기구를 비탈 위쪽(공기 상류)에 두고 배기는 골짜기 아래로; 철길 아래 지하차도와 통로를 안쪽 문으로 굳힌다', 49110, 16507, 'space', 8929, 'space', 1, 0, 2.0, 16507, 138, 289, 2174, 1, 782.6, 2283, 913.1, 0, 0, 0);
INSERT INTO stronghold_stage (stronghold_id, stage, variant, terrain_works, terrain_works_ko, floor_m2, capacity, cap_by_max, living_capacity, cap_by, over_living, over_max, air_speed, overcrowd_limit, guard_standing, guard_emergency, mobilisable, defensible, food_t, water_m3, fuel_t, surface_line_m, surface_line_real_m, watchtowers) VALUES ('seoul-station', 4, 'common', 'The line runs along the ridge and slopes. The tallest building or rocky knoll is the watchtower, the slope itself is the cleared strip, and grilles close the sewer outlets on the valley side; The railway embankments and cuttings are ready-made ramparts. Barriers stand on top, the underpasses and spaces below the rail bridges are the gates, and the top of the embankment is the line of watchtowers', '능선과 비탈을 따라 두른다. 가장 높은 건물·바위 언덕이 망루, 비탈 자체가 비워 둔 띠, 골짜기 쪽 하수 수구에 창살; 철도 성토·절토가 이미 둑이다. 둑 위에 방벽, 지하차도와 철교 아래가 문, 성토 위가 망루 줄', 50027, 16769, 'space', 6253, 'space', 1, 0, 2.5, 16769, 147, 342, 2174, 1, 1174.0, 6522, 1369.6, 264, 445, 2);
INSERT INTO stronghold_stage (stronghold_id, stage, variant, terrain_works, terrain_works_ko, floor_m2, capacity, cap_by_max, living_capacity, cap_by, over_living, over_max, air_speed, overcrowd_limit, guard_standing, guard_emergency, mobilisable, defensible, food_t, water_m3, fuel_t, surface_line_m, surface_line_real_m, watchtowers) VALUES ('seoul-station', 5, 'common', 'Signal points on the ridge keep a line of sight to the neighbouring stations; Surface tracks become haul roads (push carts); rail bridges are gates that can be cut or joined', '능선 위 신호 자리로 이웃 역과 보이는 줄을 잇는다; 지상 선로를 짐 나르는 길로(밀차), 철교는 끊고 잇는 문', 66227, 21398, 'space', 6622, 'space', 1, 0, 3.0, 21398, 147, 342, 2174, 1, 2380.5, 16305, 2777.3, 264, 445, 2);
