INSERT INTO stronghold_stage (stronghold_id, stage, variant, terrain_works, terrain_works_ko, floor_m2, capacity, cap_by_max, living_capacity, cap_by, over_living, over_max, air_speed, overcrowd_limit, guard_standing, guard_emergency, mobilisable, defensible, food_t, water_m3, fuel_t, surface_line_m, surface_line_real_m, watchtowers) VALUES ('susaek', 5, 'common', 'Surface tracks become haul roads (push carts); rail bridges are gates that can be cut or joined; Passages through buildings are joined toward the neighbouring station, giving a route that never goes outside', '지상 선로를 짐 나르는 길로(밀차), 철교는 끊고 잇는 문; 건물 안 통로를 이어 이웃 역 방향으로 지상에 나가지 않는 길을 낸다', 13206, 468, 'water', 140, 'space', 1, 1, 3.0, 4302, 50, 87, 274, 1, 300.0, 2055, 1500.2, 258, 394, 2);
