INSERT INTO stronghold_stage (stronghold_id, stage, variant, terrain_works, terrain_works_ko, floor_m2, capacity, cap_by_max, living_capacity, cap_by, over_living, over_max, air_speed, overcrowd_limit, guard_standing, guard_emergency, mobilisable, defensible, food_t, water_m3, fuel_t, surface_line_m, surface_line_real_m, watchtowers) VALUES ('sindap', 3, 'common', 'Sumps and drainage pumps in the last-stand zone, grilles at the ends of the drains on the river side; A passage is cut from the estate''s underground car park to the station precinct', '집수정과 배수펌프를 최후 구역에, 하천 쪽 배수 관로 끝에 창살; 단지 지하 주차장을 구내와 잇는 통로를 낸다', 2760, 550, 'water', 275, 'water', 1, 0, 2.0, 927, 40, 23, 110, 1, 39.6, 116, 145.2, 0, 0, 0);
INSERT INTO stronghold_stage (stronghold_id, stage, variant, terrain_works, terrain_works_ko, floor_m2, capacity, cap_by_max, living_capacity, cap_by, over_living, over_max, air_speed, overcrowd_limit, guard_standing, guard_emergency, mobilisable, defensible, food_t, water_m3, fuel_t, surface_line_m, surface_line_real_m, watchtowers) VALUES ('sindap', 4, 'common', 'The river is the moat on one side. The embankment is the wall, bridges and sewer outlets are the gates. A frozen river becomes a road in winter, so there is an ice watch post; The apartment estate wall is the inner wall and the estate main gate is the gate. Yards between the blocks become vegetable plots and a firewood yard', '하천 한쪽이 해자다. 둑이 성벽, 다리와 하수 출구가 문. 겨울에 언 하천은 길이 되므로 얼음 감시 초소; 아파트 단지 담장이 안뜰 성벽, 단지 정문이 성문, 동 사이 마당이 텃밭과 땔감 마당', 2760, 667, 'water', 250, 'water', 1, 0, 2.5, 927, 45, 51, 110, 1, 59.4, 330, 217.8, 140, 358, 1);
INSERT INTO stronghold_stage (stronghold_id, stage, variant, terrain_works, terrain_works_ko, floor_m2, capacity, cap_by_max, living_capacity, cap_by, over_living, over_max, air_speed, overcrowd_limit, guard_standing, guard_emergency, mobilisable, defensible, food_t, water_m3, fuel_t, surface_line_m, surface_line_real_m, watchtowers) VALUES ('sindap', 5, 'common', 'One bridge is blocked and one is held as the crossing; Neighbouring estates are taken in one by one, joining several estate strongholds', '다리 하나를 막고 하나는 지켜 건너는 길로 쓴다; 이웃 단지를 차례로 편입해 단지 성채 여럿을 잇는다', 8160, 667, 'water', 200, 'water', 1, 0, 3.0, 2470, 45, 51, 110, 1, 120.5, 825, 441.6, 140, 358, 1);
