INSERT INTO stronghold_stage (stronghold_id, stage, variant, terrain_works, terrain_works_ko, floor_m2, capacity, cap_by_max, living_capacity, cap_by, over_living, over_max, air_speed, overcrowd_limit, guard_standing, guard_emergency, mobilisable, defensible, food_t, water_m3, fuel_t, surface_line_m, surface_line_real_m, watchtowers) VALUES ('sindaebang', 2, 'common', '', '', 5487, 2850, 'space', 1567, 'space', 0, 0, 1.0, 2850, 22, 16, 49, 1, 6.5, 9, 32.4, 0, 0, 0);
INSERT INTO stronghold_stage (stronghold_id, stage, variant, terrain_works, terrain_works_ko, floor_m2, capacity, cap_by_max, living_capacity, cap_by, over_living, over_max, air_speed, overcrowd_limit, guard_standing, guard_emergency, mobilisable, defensible, food_t, water_m3, fuel_t, surface_line_m, surface_line_real_m, watchtowers) VALUES ('sindaebang', 3, 'common', 'Sumps and drainage pumps in the last-stand zone, grilles at the ends of the drains on the river side; Basements of low-rise buildings above the entrances used as hidden storerooms', '집수정과 배수펌프를 최후 구역에, 하천 쪽 배수 관로 끝에 창살; 출입구 위 저층 건물의 지하실을 숨긴 창고로', 8480, 2850, 'space', 1541, 'space', 0, 0, 2.0, 2850, 46, 20, 49, 1, 13.0, 38, 64.8, 0, 0, 0);
INSERT INTO stronghold_stage (stronghold_id, stage, variant, terrain_works, terrain_works_ko, floor_m2, capacity, cap_by_max, living_capacity, cap_by, over_living, over_max, air_speed, overcrowd_limit, guard_standing, guard_emergency, mobilisable, defensible, food_t, water_m3, fuel_t, surface_line_m, surface_line_real_m, watchtowers) VALUES ('sindaebang', 4, 'common', 'The river is the moat on one side. The embankment is the wall, bridges and sewer outlets are the gates. A frozen river becomes a road in winter, so there is an ice watch post; Only a few alley mouths stay open and the rest are blocked into a maze of dead ends; building walls are broken through to make inner passages', '하천 한쪽이 해자다. 둑이 성벽, 다리와 하수 출구가 문. 겨울에 언 하천은 길이 되므로 얼음 감시 초소; 골목 입구 몇 곳만 열고 나머지는 막아 막다른 미로로, 건물 벽을 뚫어 안쪽 통로를 낸다', 9575, 695, 'water', 260, 'space', 0, 0, 2.5, 3163, 50, 62, 49, 0, 19.4, 108, 97.2, 140, 251, 1);
INSERT INTO stronghold_stage (stronghold_id, stage, variant, terrain_works, terrain_works_ko, floor_m2, capacity, cap_by_max, living_capacity, cap_by, over_living, over_max, air_speed, overcrowd_limit, guard_standing, guard_emergency, mobilisable, defensible, food_t, water_m3, fuel_t, surface_line_m, surface_line_real_m, watchtowers) VALUES ('sindaebang', 5, 'common', 'One bridge is blocked and one is held as the crossing; Passages through buildings are joined toward the neighbouring station, giving a route that never goes outside', '다리 하나를 막고 하나는 지켜 건너는 길로 쓴다; 건물 안 통로를 이어 이웃 역 방향으로 지상에 나가지 않는 길을 낸다', 14975, 695, 'water', 208, 'space', 0, 0, 3.0, 4705, 50, 62, 49, 0, 39.4, 270, 197.1, 140, 251, 1);
