INSERT INTO stronghold_stage (stronghold_id, stage, variant, terrain_works, terrain_works_ko, floor_m2, capacity, cap_by_max, living_capacity, cap_by, over_living, over_max, air_speed, overcrowd_limit, guard_standing, guard_emergency, mobilisable, defensible, food_t, water_m3, fuel_t, surface_line_m, surface_line_real_m, watchtowers) VALUES ('sindorim', 4, 'common', 'The railway embankments and cuttings are ready-made ramparts. Barriers stand on top, the underpasses and spaces below the rail bridges are the gates, and the top of the embankment is the line of watchtowers; The outer walls of the high-rise buildings form the wall. Ground and first-floor windows are blocked, the rooftops are watchtowers, and only the gaps between buildings get barriers', '철도 성토·절토가 이미 둑이다. 둑 위에 방벽, 지하차도와 철교 아래가 문, 성토 위가 망루 줄; 고층 건물의 외벽 줄이 성벽, 1~2층 창을 막고 고층 꼭대기가 망루, 건물 사이 틈만 방벽', 41970, 6350, 'water', 2381, 'water', 1, 0, 2.5, 14031, 100, 273, 1493, 1, 597.2, 3318, 2189.9, 396, 593, 2);
INSERT INTO stronghold_stage (stronghold_id, stage, variant, terrain_works, terrain_works_ko, floor_m2, capacity, cap_by_max, living_capacity, cap_by, over_living, over_max, air_speed, overcrowd_limit, guard_standing, guard_emergency, mobilisable, defensible, food_t, water_m3, fuel_t, surface_line_m, surface_line_real_m, watchtowers) VALUES ('sindorim', 5, 'common', 'Surface tracks become haul roads (push carts); rail bridges are gates that can be cut or joined; High-rise buildings are linked through underground car parks and connecting passages, so people move between them without going outside', '지상 선로를 짐 나르는 길로(밀차), 철교는 끊고 잇는 문; 고층 건물끼리 지하 주차장·연결 통로로 이어 지상에 나가지 않고 오간다', 55470, 6350, 'water', 1905, 'water', 1, 0, 3.0, 17889, 100, 273, 1493, 1, 1211.1, 8295, 4440.6, 396, 593, 2);
