INSERT INTO stronghold_stage (stronghold_id, stage, variant, terrain_works, terrain_works_ko, floor_m2, capacity, cap_by_max, living_capacity, cap_by, over_living, over_max, air_speed, overcrowd_limit, guard_standing, guard_emergency, mobilisable, defensible, food_t, water_m3, fuel_t, surface_line_m, surface_line_real_m, watchtowers) VALUES ('sinmokdong', 4, 'common', 'The river is the moat on one side. The embankment is the wall, bridges and sewer outlets are the gates. A frozen river becomes a road in winter, so there is an ice watch post; The line runs along the ridge and slopes. The tallest building or rocky knoll is the watchtower, the slope itself is the cleared strip, and grilles close the sewer outlets on the valley side', '하천 한쪽이 해자다. 둑이 성벽, 다리와 하수 출구가 문. 겨울에 언 하천은 길이 되므로 얼음 감시 초소; 능선과 비탈을 따라 두른다. 가장 높은 건물·바위 언덕이 망루, 비탈 자체가 비워 둔 띠, 골짜기 쪽 하수 수구에 창살', 8635, 2856, 'space', 1079, 'space', 1, 0, 2.5, 2856, 54, 125, 383, 1, 153.4, 852, 306.7, 270, 288, 2);
INSERT INTO stronghold_stage (stronghold_id, stage, variant, terrain_works, terrain_works_ko, floor_m2, capacity, cap_by_max, living_capacity, cap_by, over_living, over_max, air_speed, overcrowd_limit, guard_standing, guard_emergency, mobilisable, defensible, food_t, water_m3, fuel_t, surface_line_m, surface_line_real_m, watchtowers) VALUES ('sinmokdong', 5, 'common', 'One bridge is blocked and one is held as the crossing; Signal points on the ridge keep a line of sight to the neighbouring stations', '다리 하나를 막고 하나는 지켜 건너는 길로 쓴다; 능선 위 신호 자리로 이웃 역과 보이는 줄을 잇는다', 14035, 4399, 'space', 1403, 'space', 1, 0, 3.0, 4399, 54, 125, 383, 1, 311.0, 2130, 622.0, 270, 288, 2);
