INSERT INTO stronghold_stage (stronghold_id, stage, variant, terrain_works, terrain_works_ko, floor_m2, capacity, cap_by_max, living_capacity, cap_by, over_living, over_max, air_speed, overcrowd_limit, guard_standing, guard_emergency, mobilisable, defensible, food_t, water_m3, fuel_t, surface_line_m, surface_line_real_m, watchtowers) VALUES ('yangjae', 3, 'common', 'Basements of adjoining high-rise buildings used as precinct storerooms; Basements of low-rise buildings above the entrances used as hidden storerooms', '붙은 고층 건물의 지하층을 구내 창고로; 출입구 위 저층 건물의 지하실을 숨긴 창고로', 27656, 8733, 'water', 4366, 'water', 0, 0, 2.0, 9296, 84, 74, 393, 1, 94.3, 275, 110.0, 0, 0, 0);
INSERT INTO stronghold_stage (stronghold_id, stage, variant, terrain_works, terrain_works_ko, floor_m2, capacity, cap_by_max, living_capacity, cap_by, over_living, over_max, air_speed, overcrowd_limit, guard_standing, guard_emergency, mobilisable, defensible, food_t, water_m3, fuel_t, surface_line_m, surface_line_real_m, watchtowers) VALUES ('yangjae', 4, 'arc', 'The outer walls of the high-rise buildings form the wall. Ground and first-floor windows are blocked, the rooftops are watchtowers, and only the gaps between buildings get barriers; Only a few alley mouths stay open and the rest are blocked into a maze of dead ends; building walls are broken through to make inner passages', '고층 건물의 외벽 줄이 성벽, 1~2층 창을 막고 고층 꼭대기가 망루, 건물 사이 틈만 방벽; 골목 입구 몇 곳만 열고 나머지는 막아 막다른 미로로, 건물 벽을 뚫어 안쪽 통로를 낸다', 27656, 8733, 'water', 3275, 'water', 0, 0, 2.5, 9296, 84, 74, 393, 1, 141.5, 786, 165.1, 0, 0, 0);
INSERT INTO stronghold_stage (stronghold_id, stage, variant, terrain_works, terrain_works_ko, floor_m2, capacity, cap_by_max, living_capacity, cap_by, over_living, over_max, air_speed, overcrowd_limit, guard_standing, guard_emergency, mobilisable, defensible, food_t, water_m3, fuel_t, surface_line_m, surface_line_real_m, watchtowers) VALUES ('yangjae', 5, 'arc', 'High-rise buildings are linked through underground car parks and connecting passages, so people move between them without going outside; Passages through buildings are joined toward the neighbouring station, giving a route that never goes outside', '고층 건물끼리 지하 주차장·연결 통로로 이어 지상에 나가지 않고 오간다; 건물 안 통로를 이어 이웃 역 방향으로 지상에 나가지 않는 길을 낸다', 38456, 8733, 'water', 2620, 'water', 0, 0, 3.0, 12382, 84, 74, 393, 1, 286.9, 1965, 334.7, 0, 0, 0);
INSERT INTO stronghold_stage (stronghold_id, stage, variant, terrain_works, terrain_works_ko, floor_m2, capacity, cap_by_max, living_capacity, cap_by, over_living, over_max, air_speed, overcrowd_limit, guard_standing, guard_emergency, mobilisable, defensible, food_t, water_m3, fuel_t, surface_line_m, surface_line_real_m, watchtowers) VALUES ('yangjae-citizen-s-forest', 1, 'common', '', '', 5398, 6169, 'space', 3598, 'space', 0, 0, 1.0, 5398, 9, 27, 348, 1, 9.7, 17, 11.4, 0, 0, 0);
INSERT INTO stronghold_stage (stronghold_id, stage, variant, terrain_works, terrain_works_ko, floor_m2, capacity, cap_by_max, living_capacity, cap_by, over_living, over_max, air_speed, overcrowd_limit, guard_standing, guard_emergency, mobilisable, defensible, food_t, water_m3, fuel_t, surface_line_m, surface_line_real_m, watchtowers) VALUES ('yangjae-citizen-s-forest', 2, 'common', '', '', 11876, 6169, 'space', 3393, 'space', 0, 0, 1.0, 6169, 30, 43, 348, 1, 41.8, 61, 48.7, 0, 0, 0);
INSERT INTO stronghold_stage (stronghold_id, stage, variant, terrain_works, terrain_works_ko, floor_m2, capacity, cap_by_max, living_capacity, cap_by, over_living, over_max, air_speed, overcrowd_limit, guard_standing, guard_emergency, mobilisable, defensible, food_t, water_m3, fuel_t, surface_line_m, surface_line_real_m, watchtowers) VALUES ('yangjae-citizen-s-forest', 3, 'common', 'Basements of low-rise buildings above the entrances used as hidden storerooms; For a shallow station, pairing with a deep neighbour comes first', '출입구 위 저층 건물의 지하실을 숨긴 창고로; 얕은 역이면 깊은 이웃 역과 짝을 맺는 것이 먼저', 18354, 6169, 'space', 3337, 'space', 0, 0, 2.0, 6169, 54, 47, 348, 1, 83.5, 244, 97.4, 0, 0, 0);
INSERT INTO stronghold_stage (stronghold_id, stage, variant, terrain_works, terrain_works_ko, floor_m2, capacity, cap_by_max, living_capacity, cap_by, over_living, over_max, air_speed, overcrowd_limit, guard_standing, guard_emergency, mobilisable, defensible, food_t, water_m3, fuel_t, surface_line_m, surface_line_real_m, watchtowers) VALUES ('yangjae-citizen-s-forest', 4, 'arc', 'Only a few alley mouths stay open and the rest are blocked into a maze of dead ends; building walls are broken through to make inner passages; With no terrain to lean on, banks are raised and ditches dug. Wide roads are kept as the cleared strip (field of fire), with watchtowers at the corners', '골목 입구 몇 곳만 열고 나머지는 막아 막다른 미로로, 건물 벽을 뚫어 안쪽 통로를 낸다; 기댈 지형이 없어 둑을 쌓고 해자를 판다. 넓은 길은 비워 둔 띠(사격 띠)로, 모서리에 망루', 18354, 6169, 'space', 2294, 'space', 0, 0, 2.5, 6169, 54, 47, 348, 1, 125.3, 696, 146.2, 0, 0, 0);
INSERT INTO stronghold_stage (stronghold_id, stage, variant, terrain_works, terrain_works_ko, floor_m2, capacity, cap_by_max, living_capacity, cap_by, over_living, over_max, air_speed, overcrowd_limit, guard_standing, guard_emergency, mobilisable, defensible, food_t, water_m3, fuel_t, surface_line_m, surface_line_real_m, watchtowers) VALUES ('yangjae-citizen-s-forest', 5, 'arc', 'Passages through buildings are joined toward the neighbouring station, giving a route that never goes outside; A shallow station cannot stand alone. It exists only as a pair with a deep neighbour', '건물 안 통로를 이어 이웃 역 방향으로 지상에 나가지 않는 길을 낸다; 얕은 역은 혼자 서지 못한다. 깊은 이웃 역과의 짝으로만 성립', 23754, 7712, 'space', 2320, 'water', 0, 0, 3.0, 7712, 54, 47, 348, 1, 254.0, 1740, 296.4, 0, 0, 0);
INSERT INTO stronghold_stage (stronghold_id, stage, variant, terrain_works, terrain_works_ko, floor_m2, capacity, cap_by_max, living_capacity, cap_by, over_living, over_max, air_speed, overcrowd_limit, guard_standing, guard_emergency, mobilisable, defensible, food_t, water_m3, fuel_t, surface_line_m, surface_line_real_m, watchtowers) VALUES ('yangcheon-gu-office', 1, 'common', '', '', 972, 540, 'water', 647, 'space', 0, 0, 1.0, 971, 3, 15, 146, 1, 4.5, 8, 16.6, 0, 0, 0);
