INSERT INTO stronghold_stage (stronghold_id, stage, variant, terrain_works, terrain_works_ko, floor_m2, capacity, cap_by_max, living_capacity, cap_by, over_living, over_max, air_speed, overcrowd_limit, guard_standing, guard_emergency, mobilisable, defensible, food_t, water_m3, fuel_t, surface_line_m, surface_line_real_m, watchtowers) VALUES ('yeouinaru', 3, 'common', 'A passage is cut from the estate''s underground car park to the station precinct; Sumps and drainage pumps in the last-stand zone, grilles at the ends of the drains on the river side', '단지 지하 주차장을 구내와 잇는 통로를 낸다; 집수정과 배수펌프를 최후 구역에, 하천 쪽 배수 관로 끝에 창살', 7726, 2596, 'space', 1404, 'space', 1, 0, 2.0, 2596, 46, 74, 672, 1, 179.3, 523, 209.2, 0, 0, 0);
INSERT INTO stronghold_stage (stronghold_id, stage, variant, terrain_works, terrain_works_ko, floor_m2, capacity, cap_by_max, living_capacity, cap_by, over_living, over_max, air_speed, overcrowd_limit, guard_standing, guard_emergency, mobilisable, defensible, food_t, water_m3, fuel_t, surface_line_m, surface_line_real_m, watchtowers) VALUES ('yeouinaru', 4, 'common', 'The apartment estate wall is the inner wall and the estate main gate is the gate. Yards between the blocks become vegetable plots and a firewood yard; The river is the moat on one side. The embankment is the wall, bridges and sewer outlets are the gates. A frozen river becomes a road in winter, so there is an ice watch post', '아파트 단지 담장이 안뜰 성벽, 단지 정문이 성문, 동 사이 마당이 텃밭과 땔감 마당; 하천 한쪽이 해자다. 둑이 성벽, 다리와 하수 출구가 문. 겨울에 언 하천은 길이 되므로 얼음 감시 초소', 7726, 2596, 'space', 965, 'space', 1, 0, 2.5, 2596, 54, 145, 672, 1, 268.9, 1494, 313.7, 238, 305, 2);
