INSERT INTO stronghold_stage (stronghold_id, stage, variant, terrain_works, terrain_works_ko, floor_m2, capacity, cap_by_max, living_capacity, cap_by, over_living, over_max, air_speed, overcrowd_limit, guard_standing, guard_emergency, mobilisable, defensible, food_t, water_m3, fuel_t, surface_line_m, surface_line_real_m, watchtowers) VALUES ('yeonsinnae', 4, 'common', 'Only a few alley mouths stay open and the rest are blocked into a maze of dead ends; building walls are broken through to make inner passages; The line runs along the ridge and slopes. The tallest building or rocky knoll is the watchtower, the slope itself is the cleared strip, and grilles close the sewer outlets on the valley side', '골목 입구 몇 곳만 열고 나머지는 막아 막다른 미로로, 건물 벽을 뚫어 안쪽 통로를 낸다; 능선과 비탈을 따라 두른다. 가장 높은 건물·바위 언덕이 망루, 비탈 자체가 비워 둔 띠, 골짜기 쪽 하수 수구에 창살', 29523, 9606, 'space', 3690, 'space', 1, 0, 2.5, 9606, 132, 186, 770, 1, 415.8, 2310, 485.1, 287, 442, 2);
INSERT INTO stronghold_stage (stronghold_id, stage, variant, terrain_works, terrain_works_ko, floor_m2, capacity, cap_by_max, living_capacity, cap_by, over_living, over_max, air_speed, overcrowd_limit, guard_standing, guard_emergency, mobilisable, defensible, food_t, water_m3, fuel_t, surface_line_m, surface_line_real_m, watchtowers) VALUES ('yeonsinnae', 5, 'common', 'Passages through buildings are joined toward the neighbouring station, giving a route that never goes outside; Signal points on the ridge keep a line of sight to the neighbouring stations', '건물 안 통로를 이어 이웃 역 방향으로 지상에 나가지 않는 길을 낸다; 능선 위 신호 자리로 이웃 역과 보이는 줄을 잇는다', 43023, 13463, 'space', 4302, 'space', 0, 0, 3.0, 13463, 132, 186, 770, 1, 843.1, 5775, 983.7, 287, 442, 2);
