INSERT INTO stronghold_stage (stronghold_id, stage, variant, terrain_works, terrain_works_ko, floor_m2, capacity, cap_by_max, living_capacity, cap_by, over_living, over_max, air_speed, overcrowd_limit, guard_standing, guard_emergency, mobilisable, defensible, food_t, water_m3, fuel_t, surface_line_m, surface_line_real_m, watchtowers) VALUES ('euljiro-4-ga', 4, 'common', 'Only a few alley mouths stay open and the rest are blocked into a maze of dead ends; building walls are broken through to make inner passages; The outer walls of the high-rise buildings form the wall. Ground and first-floor windows are blocked, the rooftops are watchtowers, and only the gaps between buildings get barriers', '골목 입구 몇 곳만 열고 나머지는 막아 막다른 미로로, 건물 벽을 뚫어 안쪽 통로를 낸다; 고층 건물의 외벽 줄이 성벽, 1~2층 창을 막고 고층 꼭대기가 망루, 건물 사이 틈만 방벽', 17755, 5896, 'space', 2219, 'space', 1, 1, 2.5, 5896, 114, 268, 1504, 1, 812.2, 4512, 1624.3, 366, 520, 2);
INSERT INTO stronghold_stage (stronghold_id, stage, variant, terrain_works, terrain_works_ko, floor_m2, capacity, cap_by_max, living_capacity, cap_by, over_living, over_max, air_speed, overcrowd_limit, guard_standing, guard_emergency, mobilisable, defensible, food_t, water_m3, fuel_t, surface_line_m, surface_line_real_m, watchtowers) VALUES ('euljiro-4-ga', 5, 'common', 'Passages through buildings are joined toward the neighbouring station, giving a route that never goes outside; High-rise buildings are linked through underground car parks and connecting passages, so people move between them without going outside', '건물 안 통로를 이어 이웃 역 방향으로 지상에 나가지 않는 길을 낸다; 고층 건물끼리 지하 주차장·연결 통로로 이어 지상에 나가지 않고 오간다', 25855, 8210, 'space', 2585, 'space', 1, 0, 3.0, 8210, 114, 268, 1504, 1, 1646.9, 11280, 3293.8, 366, 520, 2);
INSERT INTO stronghold_stage (stronghold_id, stage, variant, terrain_works, terrain_works_ko, floor_m2, capacity, cap_by_max, living_capacity, cap_by, over_living, over_max, air_speed, overcrowd_limit, guard_standing, guard_emergency, mobilisable, defensible, food_t, water_m3, fuel_t, surface_line_m, surface_line_real_m, watchtowers) VALUES ('euljiro-ipgu', 1, 'common', '', '', 2260, 2583, 'space', 1506, 'space', 1, 1, 1.0, 2260, 9, 155, 1512, 1, 63.5, 113, 169.3, 0, 0, 0);
INSERT INTO stronghold_stage (stronghold_id, stage, variant, terrain_works, terrain_works_ko, floor_m2, capacity, cap_by_max, living_capacity, cap_by, over_living, over_max, air_speed, overcrowd_limit, guard_standing, guard_emergency, mobilisable, defensible, food_t, water_m3, fuel_t, surface_line_m, surface_line_real_m, watchtowers) VALUES ('euljiro-ipgu', 2, 'common', '', '', 4973, 2583, 'space', 1420, 'space', 1, 1, 1.0, 2583, 38, 175, 1512, 1, 272.2, 397, 725.8, 0, 0, 0);
INSERT INTO stronghold_stage (stronghold_id, stage, variant, terrain_works, terrain_works_ko, floor_m2, capacity, cap_by_max, living_capacity, cap_by, over_living, over_max, air_speed, overcrowd_limit, guard_standing, guard_emergency, mobilisable, defensible, food_t, water_m3, fuel_t, surface_line_m, surface_line_real_m, watchtowers) VALUES ('euljiro-ipgu', 3, 'common', 'Basements of adjoining high-rise buildings used as precinct storerooms; For a shallow station, pairing with a deep neighbour comes first', '붙은 고층 건물의 지하층을 구내 창고로; 얕은 역이면 깊은 이웃 역과 짝을 맺는 것이 먼저', 7685, 2583, 'space', 1397, 'space', 1, 1, 2.0, 2583, 64, 179, 1512, 1, 544.3, 1588, 1451.5, 0, 0, 0);
INSERT INTO stronghold_stage (stronghold_id, stage, variant, terrain_works, terrain_works_ko, floor_m2, capacity, cap_by_max, living_capacity, cap_by, over_living, over_max, air_speed, overcrowd_limit, guard_standing, guard_emergency, mobilisable, defensible, food_t, water_m3, fuel_t, surface_line_m, surface_line_real_m, watchtowers) VALUES ('euljiro-ipgu', 4, 'common', 'The outer walls of the high-rise buildings form the wall. Ground and first-floor windows are blocked, the rooftops are watchtowers, and only the gaps between buildings get barriers; With no terrain to lean on, banks are raised and ditches dug. Wide roads are kept as the cleared strip (field of fire), with watchtowers at the corners', '고층 건물의 외벽 줄이 성벽, 1~2층 창을 막고 고층 꼭대기가 망루, 건물 사이 틈만 방벽; 기댈 지형이 없어 둑을 쌓고 해자를 판다. 넓은 길은 비워 둔 띠(사격 띠)로, 모서리에 망루', 8587, 2840, 'space', 1073, 'space', 1, 1, 2.5, 2840, 74, 250, 1512, 1, 816.5, 4536, 2177.3, 354, 422, 2);
INSERT INTO stronghold_stage (stronghold_id, stage, variant, terrain_works, terrain_works_ko, floor_m2, capacity, cap_by_max, living_capacity, cap_by, over_living, over_max, air_speed, overcrowd_limit, guard_standing, guard_emergency, mobilisable, defensible, food_t, water_m3, fuel_t, surface_line_m, surface_line_real_m, watchtowers) VALUES ('euljiro-ipgu', 5, 'common', 'High-rise buildings are linked through underground car parks and connecting passages, so people move between them without going outside; A shallow station cannot stand alone. It exists only as a pair with a deep neighbour', '고층 건물끼리 지하 주차장·연결 통로로 이어 지상에 나가지 않고 오간다; 얕은 역은 혼자 서지 못한다. 깊은 이웃 역과의 짝으로만 성립', 13987, 4383, 'space', 1398, 'space', 1, 1, 3.0, 4383, 74, 250, 1512, 1, 1655.6, 11340, 4415.0, 354, 422, 2);
INSERT INTO stronghold_stage (stronghold_id, stage, variant, terrain_works, terrain_works_ko, floor_m2, capacity, cap_by_max, living_capacity, cap_by, over_living, over_max, air_speed, overcrowd_limit, guard_standing, guard_emergency, mobilisable, defensible, food_t, water_m3, fuel_t, surface_line_m, surface_line_real_m, watchtowers) VALUES ('eungbong', 1, 'common', '', '', 1324, 1513, 'space', 882, 'space', 0, 0, 1.0, 1324, 9, 6, 24, 1, 1.0, 2, 5.0, 0, 0, 0);
