INSERT INTO stronghold_stage (stronghold_id, stage, variant, terrain_works, terrain_works_ko, floor_m2, capacity, cap_by_max, living_capacity, cap_by, over_living, over_max, air_speed, overcrowd_limit, guard_standing, guard_emergency, mobilisable, defensible, food_t, water_m3, fuel_t, surface_line_m, surface_line_real_m, watchtowers) VALUES ('itaewon', 3, 'common', 'Air intakes placed upslope (upwind) and exhaust sent down into the valley; Basements of low-rise buildings above the entrances used as hidden storerooms', '급기구를 비탈 위쪽(공기 상류)에 두고 배기는 골짜기 아래로; 출입구 위 저층 건물의 지하실을 숨긴 창고로', 6477, 2177, 'space', 1177, 'space', 1, 0, 2.0, 2177, 60, 63, 390, 1, 140.4, 410, 163.8, 0, 0, 0);
INSERT INTO stronghold_stage (stronghold_id, stage, variant, terrain_works, terrain_works_ko, floor_m2, capacity, cap_by_max, living_capacity, cap_by, over_living, over_max, air_speed, overcrowd_limit, guard_standing, guard_emergency, mobilisable, defensible, food_t, water_m3, fuel_t, surface_line_m, surface_line_real_m, watchtowers) VALUES ('itaewon', 4, 'common', 'The line runs along the ridge and slopes. The tallest building or rocky knoll is the watchtower, the slope itself is the cleared strip, and grilles close the sewer outlets on the valley side; Only a few alley mouths stay open and the rest are blocked into a maze of dead ends; building walls are broken through to make inner passages', '능선과 비탈을 따라 두른다. 가장 높은 건물·바위 언덕이 망루, 비탈 자체가 비워 둔 띠, 골짜기 쪽 하수 수구에 창살; 골목 입구 몇 곳만 열고 나머지는 막아 막다른 미로로, 건물 벽을 뚫어 안쪽 통로를 낸다', 8405, 2728, 'space', 1050, 'space', 1, 0, 2.5, 2728, 64, 93, 390, 1, 210.6, 1170, 245.7, 152, 251, 1);
INSERT INTO stronghold_stage (stronghold_id, stage, variant, terrain_works, terrain_works_ko, floor_m2, capacity, cap_by_max, living_capacity, cap_by, over_living, over_max, air_speed, overcrowd_limit, guard_standing, guard_emergency, mobilisable, defensible, food_t, water_m3, fuel_t, surface_line_m, surface_line_real_m, watchtowers) VALUES ('itaewon', 5, 'common', 'Signal points on the ridge keep a line of sight to the neighbouring stations; Passages through buildings are joined toward the neighbouring station, giving a route that never goes outside', '능선 위 신호 자리로 이웃 역과 보이는 줄을 잇는다; 건물 안 통로를 이어 이웃 역 방향으로 지상에 나가지 않는 길을 낸다', 13805, 4270, 'space', 1380, 'space', 1, 0, 3.0, 4270, 64, 93, 390, 1, 427.1, 2925, 498.2, 152, 251, 1);
