INSERT INTO stronghold_stage (stronghold_id, stage, variant, terrain_works, terrain_works_ko, floor_m2, capacity, cap_by_max, living_capacity, cap_by, over_living, over_max, air_speed, overcrowd_limit, guard_standing, guard_emergency, mobilisable, defensible, food_t, water_m3, fuel_t, surface_line_m, surface_line_real_m, watchtowers) VALUES ('jayang', 4, 'common', 'The apartment estate wall is the inner wall and the estate main gate is the gate. Yards between the blocks become vegetable plots and a firewood yard; The river is the moat on one side. The embankment is the wall, bridges and sewer outlets are the gates. A frozen river becomes a road in winter, so there is an ice watch post', '아파트 단지 담장이 안뜰 성벽, 단지 정문이 성문, 동 사이 마당이 텃밭과 땔감 마당; 하천 한쪽이 해자다. 둑이 성벽, 다리와 하수 출구가 문. 겨울에 언 하천은 길이 되므로 얼음 감시 초소', 8212, 2703, 'space', 1026, 'space', 0, 0, 2.5, 2703, 60, 102, 198, 1, 106.9, 594, 213.8, 329, 408, 2);
INSERT INTO stronghold_stage (stronghold_id, stage, variant, terrain_works, terrain_works_ko, floor_m2, capacity, cap_by_max, living_capacity, cap_by, over_living, over_max, air_speed, overcrowd_limit, guard_standing, guard_emergency, mobilisable, defensible, food_t, water_m3, fuel_t, surface_line_m, surface_line_real_m, watchtowers) VALUES ('jayang', 5, 'common', 'Neighbouring estates are taken in one by one, joining several estate strongholds; One bridge is blocked and one is held as the crossing', '이웃 단지를 차례로 편입해 단지 성채 여럿을 잇는다; 다리 하나를 막고 하나는 지켜 건너는 길로 쓴다', 13612, 4246, 'space', 1361, 'space', 0, 0, 3.0, 4246, 60, 102, 198, 1, 216.8, 1485, 433.6, 329, 408, 2);
