INSERT INTO stronghold_stage (stronghold_id, stage, variant, terrain_works, terrain_works_ko, floor_m2, capacity, cap_by_max, living_capacity, cap_by, over_living, over_max, air_speed, overcrowd_limit, guard_standing, guard_emergency, mobilisable, defensible, food_t, water_m3, fuel_t, surface_line_m, surface_line_real_m, watchtowers) VALUES ('jungnang', 4, 'common', 'Only a few alley mouths stay open and the rest are blocked into a maze of dead ends; building walls are broken through to make inner passages; The railway embankments and cuttings are ready-made ramparts. Barriers stand on top, the underpasses and spaces below the rail bridges are the gates, and the top of the embankment is the line of watchtowers', '골목 입구 몇 곳만 열고 나머지는 막아 막다른 미로로, 건물 벽을 뚫어 안쪽 통로를 낸다; 철도 성토·절토가 이미 둑이다. 둑 위에 방벽, 지하차도와 철교 아래가 문, 성토 위가 망루 줄', 3808, 1095, 'water', 410, 'space', 0, 0, 2.5, 1236, 56, 54, 14, 0, 7.6, 42, 37.8, 182, 288, 1);
INSERT INTO stronghold_stage (stronghold_id, stage, variant, terrain_works, terrain_works_ko, floor_m2, capacity, cap_by_max, living_capacity, cap_by, over_living, over_max, air_speed, overcrowd_limit, guard_standing, guard_emergency, mobilisable, defensible, food_t, water_m3, fuel_t, surface_line_m, surface_line_real_m, watchtowers) VALUES ('jungnang', 5, 'common', 'Passages through buildings are joined toward the neighbouring station, giving a route that never goes outside; Surface tracks become haul roads (push carts); rail bridges are gates that can be cut or joined', '건물 안 통로를 이어 이웃 역 방향으로 지상에 나가지 않는 길을 낸다; 지상 선로를 짐 나르는 길로(밀차), 철교는 끊고 잇는 문', 9208, 1095, 'water', 328, 'space', 0, 0, 3.0, 2779, 56, 54, 14, 0, 15.3, 105, 76.7, 182, 288, 1);
INSERT INTO stronghold_stage (stronghold_id, stage, variant, terrain_works, terrain_works_ko, floor_m2, capacity, cap_by_max, living_capacity, cap_by, over_living, over_max, air_speed, overcrowd_limit, guard_standing, guard_emergency, mobilisable, defensible, food_t, water_m3, fuel_t, surface_line_m, surface_line_real_m, watchtowers) VALUES ('jungang-bohun-byeongwon', 1, 'common', '', '', 3212, 1080, 'water', 1620, 'water', 0, 0, 1.0, 3211, 9, 15, 162, 1, 4.5, 8, 12.1, 0, 0, 0);
