INSERT INTO stronghold_stage (stronghold_id, stage, variant, terrain_works, terrain_works_ko, floor_m2, capacity, cap_by_max, living_capacity, cap_by, over_living, over_max, air_speed, overcrowd_limit, guard_standing, guard_emergency, mobilisable, defensible, food_t, water_m3, fuel_t, surface_line_m, surface_line_real_m, watchtowers) VALUES ('jeungsan', 4, 'common', 'Only a few alley mouths stay open and the rest are blocked into a maze of dead ends; building walls are broken through to make inner passages; The apartment estate wall is the inner wall and the estate main gate is the gate. Yards between the blocks become vegetable plots and a firewood yard', '골목 입구 몇 곳만 열고 나머지는 막아 막다른 미로로, 건물 벽을 뚫어 안쪽 통로를 낸다; 아파트 단지 담장이 안뜰 성벽, 단지 정문이 성문, 동 사이 마당이 텃밭과 땔감 마당', 8905, 2838, 'space', 1113, 'space', 0, 0, 2.5, 2838, 60, 78, 146, 1, 78.8, 438, 210.2, 235, 341, 2);
INSERT INTO stronghold_stage (stronghold_id, stage, variant, terrain_works, terrain_works_ko, floor_m2, capacity, cap_by_max, living_capacity, cap_by, over_living, over_max, air_speed, overcrowd_limit, guard_standing, guard_emergency, mobilisable, defensible, food_t, water_m3, fuel_t, surface_line_m, surface_line_real_m, watchtowers) VALUES ('jeungsan', 5, 'common', 'Passages through buildings are joined toward the neighbouring station, giving a route that never goes outside; Neighbouring estates are taken in one by one, joining several estate strongholds', '건물 안 통로를 이어 이웃 역 방향으로 지상에 나가지 않는 길을 낸다; 이웃 단지를 차례로 편입해 단지 성채 여럿을 잇는다', 14305, 3107, 'water', 932, 'water', 0, 0, 3.0, 4381, 60, 78, 146, 1, 159.9, 1095, 426.3, 235, 341, 2);
