INSERT INTO stronghold_stage (stronghold_id, stage, variant, terrain_works, terrain_works_ko, floor_m2, capacity, cap_by_max, living_capacity, cap_by, over_living, over_max, air_speed, overcrowd_limit, guard_standing, guard_emergency, mobilisable, defensible, food_t, water_m3, fuel_t, surface_line_m, surface_line_real_m, watchtowers) VALUES ('changdong', 3, 'common', 'A passage is cut from the estate''s underground car park to the station precinct; Underpasses and passages below the tracks hardened into inner gates', '단지 지하 주차장을 구내와 잇는 통로를 낸다; 철길 아래 지하차도와 통로를 안쪽 문으로 굳힌다', 29538, 9928, 'space', 5370, 'space', 0, 0, 2.0, 9928, 63, 61, 374, 1, 134.6, 393, 673.2, 0, 0, 0);
INSERT INTO stronghold_stage (stronghold_id, stage, variant, terrain_works, terrain_works_ko, floor_m2, capacity, cap_by_max, living_capacity, cap_by, over_living, over_max, air_speed, overcrowd_limit, guard_standing, guard_emergency, mobilisable, defensible, food_t, water_m3, fuel_t, surface_line_m, surface_line_real_m, watchtowers) VALUES ('changdong', 4, 'common', 'The apartment estate wall is the inner wall and the estate main gate is the gate. Yards between the blocks become vegetable plots and a firewood yard; The railway embankments and cuttings are ready-made ramparts. Barriers stand on top, the underpasses and spaces below the rail bridges are the gates, and the top of the embankment is the line of watchtowers', '아파트 단지 담장이 안뜰 성벽, 단지 정문이 성문, 동 사이 마당이 텃밭과 땔감 마당; 철도 성토·절토가 이미 둑이다. 둑 위에 방벽, 지하차도와 철교 아래가 문, 성토 위가 망루 줄', 30027, 915, 'water', 343, 'space', 1, 1, 2.5, 10068, 72, 111, 374, 1, 202.0, 1122, 1009.8, 248, 348, 2);
INSERT INTO stronghold_stage (stronghold_id, stage, variant, terrain_works, terrain_works_ko, floor_m2, capacity, cap_by_max, living_capacity, cap_by, over_living, over_max, air_speed, overcrowd_limit, guard_standing, guard_emergency, mobilisable, defensible, food_t, water_m3, fuel_t, surface_line_m, surface_line_real_m, watchtowers) VALUES ('changdong', 5, 'common', 'Neighbouring estates are taken in one by one, joining several estate strongholds; Surface tracks become haul roads (push carts); rail bridges are gates that can be cut or joined', '이웃 단지를 차례로 편입해 단지 성채 여럿을 잇는다; 지상 선로를 짐 나르는 길로(밀차), 철교는 끊고 잇는 문', 40827, 915, 'water', 274, 'space', 1, 1, 3.0, 13154, 72, 111, 374, 1, 409.5, 2805, 2047.7, 248, 348, 2);
