INSERT INTO stronghold_stage (stronghold_id, stage, variant, terrain_works, terrain_works_ko, floor_m2, capacity, cap_by_max, living_capacity, cap_by, over_living, over_max, air_speed, overcrowd_limit, guard_standing, guard_emergency, mobilisable, defensible, food_t, water_m3, fuel_t, surface_line_m, surface_line_real_m, watchtowers) VALUES ('cheonggyesan-ipgu', 2, 'common', '', '', 8361, 4343, 'space', 2388, 'space', 0, 0, 1.0, 4343, 22, 42, 453, 1, 54.4, 79, 63.4, 0, 0, 0);
INSERT INTO stronghold_stage (stronghold_id, stage, variant, terrain_works, terrain_works_ko, floor_m2, capacity, cap_by_max, living_capacity, cap_by, over_living, over_max, air_speed, overcrowd_limit, guard_standing, guard_emergency, mobilisable, defensible, food_t, water_m3, fuel_t, surface_line_m, surface_line_real_m, watchtowers) VALUES ('cheonggyesan-ipgu', 3, 'common', 'A passage is cut from the estate''s underground car park to the station precinct; For a shallow station, pairing with a deep neighbour comes first', '단지 지하 주차장을 구내와 잇는 통로를 낸다; 얕은 역이면 깊은 이웃 역과 짝을 맺는 것이 먼저', 12921, 4343, 'space', 2349, 'space', 0, 0, 2.0, 4343, 38, 42, 453, 1, 108.7, 317, 126.8, 0, 0, 0);
INSERT INTO stronghold_stage (stronghold_id, stage, variant, terrain_works, terrain_works_ko, floor_m2, capacity, cap_by_max, living_capacity, cap_by, over_living, over_max, air_speed, overcrowd_limit, guard_standing, guard_emergency, mobilisable, defensible, food_t, water_m3, fuel_t, surface_line_m, surface_line_real_m, watchtowers) VALUES ('cheonggyesan-ipgu', 4, 'arc', 'The apartment estate wall is the inner wall and the estate main gate is the gate. Yards between the blocks become vegetable plots and a firewood yard; With no terrain to lean on, banks are raised and ditches dug. Wide roads are kept as the cleared strip (field of fire), with watchtowers at the corners', '아파트 단지 담장이 안뜰 성벽, 단지 정문이 성문, 동 사이 마당이 텃밭과 땔감 마당; 기댈 지형이 없어 둑을 쌓고 해자를 판다. 넓은 길은 비워 둔 띠(사격 띠)로, 모서리에 망루', 12921, 4343, 'space', 1615, 'space', 0, 0, 2.5, 4343, 38, 42, 453, 1, 163.1, 906, 190.3, 0, 0, 0);
INSERT INTO stronghold_stage (stronghold_id, stage, variant, terrain_works, terrain_works_ko, floor_m2, capacity, cap_by_max, living_capacity, cap_by, over_living, over_max, air_speed, overcrowd_limit, guard_standing, guard_emergency, mobilisable, defensible, food_t, water_m3, fuel_t, surface_line_m, surface_line_real_m, watchtowers) VALUES ('cheonggyesan-ipgu', 5, 'arc', 'Neighbouring estates are taken in one by one, joining several estate strongholds; A shallow station cannot stand alone. It exists only as a pair with a deep neighbour', '이웃 단지를 차례로 편입해 단지 성채 여럿을 잇는다; 얕은 역은 혼자 서지 못한다. 깊은 이웃 역과의 짝으로만 성립', 15621, 5114, 'space', 1562, 'space', 0, 0, 3.0, 5114, 38, 42, 453, 1, 330.7, 2265, 385.8, 0, 0, 0);
