INSERT INTO stronghold_stage (stronghold_id, stage, variant, terrain_works, terrain_works_ko, floor_m2, capacity, cap_by_max, living_capacity, cap_by, over_living, over_max, air_speed, overcrowd_limit, guard_standing, guard_emergency, mobilisable, defensible, food_t, water_m3, fuel_t, surface_line_m, surface_line_real_m, watchtowers) VALUES ('chungmuro', 4, 'common', 'Only a few alley mouths stay open and the rest are blocked into a maze of dead ends; building walls are broken through to make inner passages; The outer walls of the high-rise buildings form the wall. Ground and first-floor windows are blocked, the rooftops are watchtowers, and only the gaps between buildings get barriers', '골목 입구 몇 곳만 열고 나머지는 막아 막다른 미로로, 건물 벽을 뚫어 안쪽 통로를 낸다; 고층 건물의 외벽 줄이 성벽, 1~2층 창을 막고 고층 꼭대기가 망루, 건물 사이 틈만 방벽', 23159, 7679, 'space', 2894, 'space', 1, 0, 2.5, 7679, 105, 141, 636, 1, 343.4, 1908, 686.9, 165, 236, 1);
INSERT INTO stronghold_stage (stronghold_id, stage, variant, terrain_works, terrain_works_ko, floor_m2, capacity, cap_by_max, living_capacity, cap_by, over_living, over_max, air_speed, overcrowd_limit, guard_standing, guard_emergency, mobilisable, defensible, food_t, water_m3, fuel_t, surface_line_m, surface_line_real_m, watchtowers) VALUES ('chungmuro', 5, 'common', 'Passages through buildings are joined toward the neighbouring station, giving a route that never goes outside; High-rise buildings are linked through underground car parks and connecting passages, so people move between them without going outside', '건물 안 통로를 이어 이웃 역 방향으로 지상에 나가지 않는 길을 낸다; 고층 건물끼리 지하 주차장·연결 통로로 이어 지상에 나가지 않고 오간다', 33959, 10765, 'space', 3395, 'space', 0, 0, 3.0, 10765, 105, 141, 636, 1, 696.4, 4770, 1392.8, 165, 236, 1);
INSERT INTO stronghold_stage (stronghold_id, stage, variant, terrain_works, terrain_works_ko, floor_m2, capacity, cap_by_max, living_capacity, cap_by, over_living, over_max, air_speed, overcrowd_limit, guard_standing, guard_emergency, mobilisable, defensible, food_t, water_m3, fuel_t, surface_line_m, surface_line_real_m, watchtowers) VALUES ('chungjeongno', 1, 'common', '', '', 4914, 5616, 'space', 3276, 'space', 1, 0, 1.0, 4914, 15, 102, 982, 1, 41.2, 74, 48.1, 0, 0, 0);
INSERT INTO stronghold_stage (stronghold_id, stage, variant, terrain_works, terrain_works_ko, floor_m2, capacity, cap_by_max, living_capacity, cap_by, over_living, over_max, air_speed, overcrowd_limit, guard_standing, guard_emergency, mobilisable, defensible, food_t, water_m3, fuel_t, surface_line_m, surface_line_real_m, watchtowers) VALUES ('chungjeongno', 2, 'common', '', '', 10812, 5616, 'space', 3089, 'space', 1, 0, 1.0, 5616, 62, 138, 982, 1, 176.8, 258, 206.2, 0, 0, 0);
INSERT INTO stronghold_stage (stronghold_id, stage, variant, terrain_works, terrain_works_ko, floor_m2, capacity, cap_by_max, living_capacity, cap_by, over_living, over_max, air_speed, overcrowd_limit, guard_standing, guard_emergency, mobilisable, defensible, food_t, water_m3, fuel_t, surface_line_m, surface_line_real_m, watchtowers) VALUES ('chungjeongno', 3, 'common', 'Air intakes placed upslope (upwind) and exhaust sent down into the valley; Basements of low-rise buildings above the entrances used as hidden storerooms', '급기구를 비탈 위쪽(공기 상류)에 두고 배기는 골짜기 아래로; 출입구 위 저층 건물의 지하실을 숨긴 창고로', 16709, 5616, 'space', 3038, 'space', 1, 0, 2.0, 5616, 124, 142, 982, 1, 353.5, 1031, 412.4, 0, 0, 0);
INSERT INTO stronghold_stage (stronghold_id, stage, variant, terrain_works, terrain_works_ko, floor_m2, capacity, cap_by_max, living_capacity, cap_by, over_living, over_max, air_speed, overcrowd_limit, guard_standing, guard_emergency, mobilisable, defensible, food_t, water_m3, fuel_t, surface_line_m, surface_line_real_m, watchtowers) VALUES ('chungjeongno', 4, 'common', 'The line runs along the ridge and slopes. The tallest building or rocky knoll is the watchtower, the slope itself is the cleared strip, and grilles close the sewer outlets on the valley side; Only a few alley mouths stay open and the rest are blocked into a maze of dead ends; building walls are broken through to make inner passages', '능선과 비탈을 따라 두른다. 가장 높은 건물·바위 언덕이 망루, 비탈 자체가 비워 둔 띠, 골짜기 쪽 하수 수구에 창살; 골목 입구 몇 곳만 열고 나머지는 막아 막다른 미로로, 건물 벽을 뚫어 안쪽 통로를 낸다', 20427, 6678, 'space', 2553, 'space', 1, 0, 2.5, 6678, 134, 188, 982, 1, 530.3, 2946, 618.7, 229, 286, 2);
INSERT INTO stronghold_stage (stronghold_id, stage, variant, terrain_works, terrain_works_ko, floor_m2, capacity, cap_by_max, living_capacity, cap_by, over_living, over_max, air_speed, overcrowd_limit, guard_standing, guard_emergency, mobilisable, defensible, food_t, water_m3, fuel_t, surface_line_m, surface_line_real_m, watchtowers) VALUES ('chungjeongno', 5, 'common', 'Signal points on the ridge keep a line of sight to the neighbouring stations; Passages through buildings are joined toward the neighbouring station, giving a route that never goes outside', '능선 위 신호 자리로 이웃 역과 보이는 줄을 잇는다; 건물 안 통로를 이어 이웃 역 방향으로 지상에 나가지 않는 길을 낸다', 31227, 9764, 'space', 3122, 'space', 1, 0, 3.0, 9764, 134, 188, 982, 1, 1075.3, 7365, 1254.5, 229, 286, 2);
