INSERT INTO stronghold_stage (stronghold_id, stage, variant, terrain_works, terrain_works_ko, floor_m2, capacity, cap_by_max, living_capacity, cap_by, over_living, over_max, air_speed, overcrowd_limit, guard_standing, guard_emergency, mobilisable, defensible, food_t, water_m3, fuel_t, surface_line_m, surface_line_real_m, watchtowers) VALUES ('hangangjin', 1, 'common', '', '', 1633, 1866, 'space', 1088, 'space', 1, 0, 1.0, 1633, 9, 35, 306, 1, 12.9, 23, 25.7, 0, 0, 0);
INSERT INTO stronghold_stage (stronghold_id, stage, variant, terrain_works, terrain_works_ko, floor_m2, capacity, cap_by_max, living_capacity, cap_by, over_living, over_max, air_speed, overcrowd_limit, guard_standing, guard_emergency, mobilisable, defensible, food_t, water_m3, fuel_t, surface_line_m, surface_line_real_m, watchtowers) VALUES ('hangangjin', 2, 'common', '', '', 3593, 1866, 'space', 1026, 'space', 1, 0, 1.0, 1866, 33, 51, 306, 1, 55.1, 80, 110.2, 0, 0, 0);
INSERT INTO stronghold_stage (stronghold_id, stage, variant, terrain_works, terrain_works_ko, floor_m2, capacity, cap_by_max, living_capacity, cap_by, over_living, over_max, air_speed, overcrowd_limit, guard_standing, guard_emergency, mobilisable, defensible, food_t, water_m3, fuel_t, surface_line_m, surface_line_real_m, watchtowers) VALUES ('hangangjin', 3, 'common', 'Air intakes placed upslope (upwind) and exhaust sent down into the valley; For a shallow station, pairing with a deep neighbour comes first', '급기구를 비탈 위쪽(공기 상류)에 두고 배기는 골짜기 아래로; 얕은 역이면 깊은 이웃 역과 짝을 맺는 것이 먼저', 5553, 1866, 'space', 1009, 'space', 1, 0, 2.0, 1866, 51, 55, 306, 1, 110.2, 321, 220.3, 0, 0, 0);
INSERT INTO stronghold_stage (stronghold_id, stage, variant, terrain_works, terrain_works_ko, floor_m2, capacity, cap_by_max, living_capacity, cap_by, over_living, over_max, air_speed, overcrowd_limit, guard_standing, guard_emergency, mobilisable, defensible, food_t, water_m3, fuel_t, surface_line_m, surface_line_real_m, watchtowers) VALUES ('hangangjin', 4, 'common', 'The line runs along the ridge and slopes. The tallest building or rocky knoll is the watchtower, the slope itself is the cleared strip, and grilles close the sewer outlets on the valley side; With no terrain to lean on, banks are raised and ditches dug. Wide roads are kept as the cleared strip (field of fire), with watchtowers at the corners', '능선과 비탈을 따라 두른다. 가장 높은 건물·바위 언덕이 망루, 비탈 자체가 비워 둔 띠, 골짜기 쪽 하수 수구에 창살; 기댈 지형이 없어 둑을 쌓고 해자를 판다. 넓은 길은 비워 둔 띠(사격 띠)로, 모서리에 망루', 8644, 2749, 'space', 1080, 'space', 1, 0, 2.5, 2749, 60, 98, 306, 1, 165.2, 918, 330.5, 216, 307, 2);
INSERT INTO stronghold_stage (stronghold_id, stage, variant, terrain_works, terrain_works_ko, floor_m2, capacity, cap_by_max, living_capacity, cap_by, over_living, over_max, air_speed, overcrowd_limit, guard_standing, guard_emergency, mobilisable, defensible, food_t, water_m3, fuel_t, surface_line_m, surface_line_real_m, watchtowers) VALUES ('hangangjin', 5, 'common', 'Signal points on the ridge keep a line of sight to the neighbouring stations; A shallow station cannot stand alone. It exists only as a pair with a deep neighbour', '능선 위 신호 자리로 이웃 역과 보이는 줄을 잇는다; 얕은 역은 혼자 서지 못한다. 깊은 이웃 역과의 짝으로만 성립', 14044, 4292, 'space', 1404, 'space', 1, 0, 3.0, 4292, 60, 98, 306, 1, 335.1, 2295, 670.1, 216, 307, 2);
INSERT INTO stronghold_stage (stronghold_id, stage, variant, terrain_works, terrain_works_ko, floor_m2, capacity, cap_by_max, living_capacity, cap_by, over_living, over_max, air_speed, overcrowd_limit, guard_standing, guard_emergency, mobilisable, defensible, food_t, water_m3, fuel_t, surface_line_m, surface_line_real_m, watchtowers) VALUES ('hannam', 1, 'common', '', '', 1070, 1222, 'space', 713, 'space', 0, 0, 1.0, 1069, 3, 6, 16, 1, 0.7, 1, 3.4, 0, 0, 0);
INSERT INTO stronghold_stage (stronghold_id, stage, variant, terrain_works, terrain_works_ko, floor_m2, capacity, cap_by_max, living_capacity, cap_by, over_living, over_max, air_speed, overcrowd_limit, guard_standing, guard_emergency, mobilisable, defensible, food_t, water_m3, fuel_t, surface_line_m, surface_line_real_m, watchtowers) VALUES ('hannam', 2, 'common', '', '', 2353, 1222, 'space', 672, 'space', 0, 0, 1.0, 1222, 18, 14, 16, 1, 2.9, 4, 14.4, 0, 0, 0);
INSERT INTO stronghold_stage (stronghold_id, stage, variant, terrain_works, terrain_works_ko, floor_m2, capacity, cap_by_max, living_capacity, cap_by, over_living, over_max, air_speed, overcrowd_limit, guard_standing, guard_emergency, mobilisable, defensible, food_t, water_m3, fuel_t, surface_line_m, surface_line_real_m, watchtowers) VALUES ('hannam', 3, 'common', 'Air intakes placed upslope (upwind) and exhaust sent down into the valley; Sumps and drainage pumps in the last-stand zone, grilles at the ends of the drains on the river side', '급기구를 비탈 위쪽(공기 상류)에 두고 배기는 골짜기 아래로; 집수정과 배수펌프를 최후 구역에, 하천 쪽 배수 관로 끝에 창살', 3637, 1222, 'space', 661, 'space', 0, 0, 2.0, 1222, 40, 14, 16, 1, 5.8, 17, 28.8, 0, 0, 0);
INSERT INTO stronghold_stage (stronghold_id, stage, variant, terrain_works, terrain_works_ko, floor_m2, capacity, cap_by_max, living_capacity, cap_by, over_living, over_max, air_speed, overcrowd_limit, guard_standing, guard_emergency, mobilisable, defensible, food_t, water_m3, fuel_t, surface_line_m, surface_line_real_m, watchtowers) VALUES ('hannam', 4, 'common', 'The line runs along the ridge and slopes. The tallest building or rocky knoll is the watchtower, the slope itself is the cleared strip, and grilles close the sewer outlets on the valley side; The river is the moat on one side. The embankment is the wall, bridges and sewer outlets are the gates. A frozen river becomes a road in winter, so there is an ice watch post', '능선과 비탈을 따라 두른다. 가장 높은 건물·바위 언덕이 망루, 비탈 자체가 비워 둔 띠, 골짜기 쪽 하수 수구에 창살; 하천 한쪽이 해자다. 둑이 성벽, 다리와 하수 출구가 문. 겨울에 언 하천은 길이 되므로 얼음 감시 초소', 5045, 449, 'water', 168, 'space', 0, 0, 2.5, 1624, 50, 73, 16, 0, 8.6, 48, 43.2, 298, 404, 2);
INSERT INTO stronghold_stage (stronghold_id, stage, variant, terrain_works, terrain_works_ko, floor_m2, capacity, cap_by_max, living_capacity, cap_by, over_living, over_max, air_speed, overcrowd_limit, guard_standing, guard_emergency, mobilisable, defensible, food_t, water_m3, fuel_t, surface_line_m, surface_line_real_m, watchtowers) VALUES ('hannam', 5, 'common', 'Signal points on the ridge keep a line of sight to the neighbouring stations; One bridge is blocked and one is held as the crossing', '능선 위 신호 자리로 이웃 역과 보이는 줄을 잇는다; 다리 하나를 막고 하나는 지켜 건너는 길로 쓴다', 10445, 449, 'water', 134, 'space', 0, 0, 3.0, 3167, 50, 73, 16, 0, 17.5, 120, 87.6, 298, 404, 2);
