INSERT INTO stronghold_stage (stronghold_id, stage, variant, terrain_works, terrain_works_ko, floor_m2, capacity, cap_by_max, living_capacity, cap_by, over_living, over_max, air_speed, overcrowd_limit, guard_standing, guard_emergency, mobilisable, defensible, food_t, water_m3, fuel_t, surface_line_m, surface_line_real_m, watchtowers) VALUES ('hanti', 4, 'arc', 'The apartment estate wall is the inner wall and the estate main gate is the gate. Yards between the blocks become vegetable plots and a firewood yard; The outer walls of the high-rise buildings form the wall. Ground and first-floor windows are blocked, the rooftops are watchtowers, and only the gaps between buildings get barriers', '아파트 단지 담장이 안뜰 성벽, 단지 정문이 성문, 동 사이 마당이 텃밭과 땔감 마당; 고층 건물의 외벽 줄이 성벽, 1~2층 창을 막고 고층 꼭대기가 망루, 건물 사이 틈만 방벽', 9755, 3279, 'space', 1219, 'space', 0, 0, 2.5, 3279, 62, 55, 339, 1, 122.0, 678, 244.1, 0, 0, 0);
INSERT INTO stronghold_stage (stronghold_id, stage, variant, terrain_works, terrain_works_ko, floor_m2, capacity, cap_by_max, living_capacity, cap_by, over_living, over_max, air_speed, overcrowd_limit, guard_standing, guard_emergency, mobilisable, defensible, food_t, water_m3, fuel_t, surface_line_m, surface_line_real_m, watchtowers) VALUES ('hanti', 5, 'arc', 'Neighbouring estates are taken in one by one, joining several estate strongholds; High-rise buildings are linked through underground car parks and connecting passages, so people move between them without going outside', '이웃 단지를 차례로 편입해 단지 성채 여럿을 잇는다; 고층 건물끼리 지하 주차장·연결 통로로 이어 지상에 나가지 않고 오간다', 15155, 3766, 'water', 1130, 'water', 0, 0, 3.0, 4822, 62, 55, 339, 1, 247.5, 1695, 494.9, 0, 0, 0);
