INSERT INTO stronghold_stage (stronghold_id, stage, variant, terrain_works, terrain_works_ko, floor_m2, capacity, cap_by_max, living_capacity, cap_by, over_living, over_max, air_speed, overcrowd_limit, guard_standing, guard_emergency, mobilisable, defensible, food_t, water_m3, fuel_t, surface_line_m, surface_line_real_m, watchtowers) VALUES ('hwarangdae', 5, 'common', 'Neighbouring estates are taken in one by one, joining several estate strongholds; A shallow station cannot stand alone. It exists only as a pair with a deep neighbour', '이웃 단지를 차례로 편입해 단지 성채 여럿을 잇는다; 얕은 역은 혼자 서지 못한다. 깊은 이웃 역과의 짝으로만 성립', 15258, 2915, 'water', 874, 'water', 1, 0, 3.0, 4856, 60, 75, 278, 1, 304.4, 2085, 811.8, 154, 202, 1);
