INSERT INTO stronghold_stage (stronghold_id, stage, variant, terrain_works, terrain_works_ko, floor_m2, capacity, cap_by_max, living_capacity, cap_by, over_living, over_max, air_speed, overcrowd_limit, guard_standing, guard_emergency, mobilisable, defensible, food_t, water_m3, fuel_t, surface_line_m, surface_line_real_m, watchtowers) VALUES ('hyochanggongwonap', 3, 'common', 'Basements of low-rise buildings above the entrances used as hidden storerooms; A passage is cut from the estate''s underground car park to the station precinct', '출입구 위 저층 건물의 지하실을 숨긴 창고로; 단지 지하 주차장을 구내와 잇는 통로를 낸다', 16133, 2520, 'water', 1260, 'water', 0, 0, 2.0, 5422, 64, 53, 252, 1, 90.7, 265, 241.9, 0, 0, 0);
INSERT INTO stronghold_stage (stronghold_id, stage, variant, terrain_works, terrain_works_ko, floor_m2, capacity, cap_by_max, living_capacity, cap_by, over_living, over_max, air_speed, overcrowd_limit, guard_standing, guard_emergency, mobilisable, defensible, food_t, water_m3, fuel_t, surface_line_m, surface_line_real_m, watchtowers) VALUES ('hyochanggongwonap', 4, 'common', 'Only a few alley mouths stay open and the rest are blocked into a maze of dead ends; building walls are broken through to make inner passages; The apartment estate wall is the inner wall and the estate main gate is the gate. Yards between the blocks become vegetable plots and a firewood yard', '골목 입구 몇 곳만 열고 나머지는 막아 막다른 미로로, 건물 벽을 뚫어 안쪽 통로를 낸다; 아파트 단지 담장이 안뜰 성벽, 단지 정문이 성문, 동 사이 마당이 텃밭과 땔감 마당', 16541, 2872, 'water', 1077, 'water', 1, 0, 2.5, 5539, 74, 118, 252, 1, 136.1, 756, 362.9, 325, 391, 2);
INSERT INTO stronghold_stage (stronghold_id, stage, variant, terrain_works, terrain_works_ko, floor_m2, capacity, cap_by_max, living_capacity, cap_by, over_living, over_max, air_speed, overcrowd_limit, guard_standing, guard_emergency, mobilisable, defensible, food_t, water_m3, fuel_t, surface_line_m, surface_line_real_m, watchtowers) VALUES ('hyochanggongwonap', 5, 'common', 'Passages through buildings are joined toward the neighbouring station, giving a route that never goes outside; Neighbouring estates are taken in one by one, joining several estate strongholds', '건물 안 통로를 이어 이웃 역 방향으로 지상에 나가지 않는 길을 낸다; 이웃 단지를 차례로 편입해 단지 성채 여럿을 잇는다', 24641, 2872, 'water', 861, 'water', 1, 0, 3.0, 7853, 74, 118, 252, 1, 275.9, 1890, 735.8, 325, 391, 2);
INSERT INTO stronghold_stage (stronghold_id, stage, variant, terrain_works, terrain_works_ko, floor_m2, capacity, cap_by_max, living_capacity, cap_by, over_living, over_max, air_speed, overcrowd_limit, guard_standing, guard_emergency, mobilisable, defensible, food_t, water_m3, fuel_t, surface_line_m, surface_line_real_m, watchtowers) VALUES ('heukseok', 1, 'common', '', '', 2484, 2839, 'space', 1656, 'space', 1, 0, 1.0, 2484, 9, 56, 699, 1, 21.8, 39, 43.5, 0, 0, 0);
INSERT INTO stronghold_stage (stronghold_id, stage, variant, terrain_works, terrain_works_ko, floor_m2, capacity, cap_by_max, living_capacity, cap_by, over_living, over_max, air_speed, overcrowd_limit, guard_standing, guard_emergency, mobilisable, defensible, food_t, water_m3, fuel_t, surface_line_m, surface_line_real_m, watchtowers) VALUES ('heukseok', 2, 'common', '', '', 5465, 2839, 'space', 1561, 'space', 1, 0, 1.0, 2839, 26, 68, 699, 1, 93.2, 136, 186.5, 0, 0, 0);
INSERT INTO stronghold_stage (stronghold_id, stage, variant, terrain_works, terrain_works_ko, floor_m2, capacity, cap_by_max, living_capacity, cap_by, over_living, over_max, air_speed, overcrowd_limit, guard_standing, guard_emergency, mobilisable, defensible, food_t, water_m3, fuel_t, surface_line_m, surface_line_real_m, watchtowers) VALUES ('heukseok', 3, 'common', 'Sumps and drainage pumps in the last-stand zone, grilles at the ends of the drains on the river side; A passage is cut from the estate''s underground car park to the station precinct', '집수정과 배수펌프를 최후 구역에, 하천 쪽 배수 관로 끝에 창살; 단지 지하 주차장을 구내와 잇는 통로를 낸다', 8446, 2839, 'space', 1535, 'space', 1, 0, 2.0, 2839, 50, 72, 699, 1, 186.5, 544, 373.0, 0, 0, 0);
INSERT INTO stronghold_stage (stronghold_id, stage, variant, terrain_works, terrain_works_ko, floor_m2, capacity, cap_by_max, living_capacity, cap_by, over_living, over_max, air_speed, overcrowd_limit, guard_standing, guard_emergency, mobilisable, defensible, food_t, water_m3, fuel_t, surface_line_m, surface_line_real_m, watchtowers) VALUES ('heukseok', 4, 'common', 'The river is the moat on one side. The embankment is the wall, bridges and sewer outlets are the gates. A frozen river becomes a road in winter, so there is an ice watch post; The apartment estate wall is the inner wall and the estate main gate is the gate. Yards between the blocks become vegetable plots and a firewood yard', '하천 한쪽이 해자다. 둑이 성벽, 다리와 하수 출구가 문. 겨울에 언 하천은 길이 되므로 얼음 감시 초소; 아파트 단지 담장이 안뜰 성벽, 단지 정문이 성문, 동 사이 마당이 텃밭과 땔감 마당', 8446, 2839, 'space', 1055, 'space', 1, 0, 2.5, 2839, 58, 165, 699, 1, 279.7, 1554, 559.4, 312, 385, 2);
INSERT INTO stronghold_stage (stronghold_id, stage, variant, terrain_works, terrain_works_ko, floor_m2, capacity, cap_by_max, living_capacity, cap_by, over_living, over_max, air_speed, overcrowd_limit, guard_standing, guard_emergency, mobilisable, defensible, food_t, water_m3, fuel_t, surface_line_m, surface_line_real_m, watchtowers) VALUES ('heukseok', 5, 'common', 'One bridge is blocked and one is held as the crossing; Neighbouring estates are taken in one by one, joining several estate strongholds', '다리 하나를 막고 하나는 지켜 건너는 길로 쓴다; 이웃 단지를 차례로 편입해 단지 성채 여럿을 잇는다', 13846, 4382, 'space', 1384, 'space', 1, 0, 3.0, 4382, 58, 165, 699, 1, 567.2, 3885, 1134.4, 312, 385, 2);
